INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他承认自己是一个很大污染者。", "corrected_sentence": "他承认自己是一个很大的污染者。", "error_description": "结构错误：“很大”修饰名词时要加“的”，应说“很大的污染者”，漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们找到了一座污染者，正在调查。", "corrected_sentence": "我们找到了一个污染者，正在调查。", "error_description": "量词错误：“污染者”应该用“个”，“座”多用于大型建筑或山，这里应改为“一个污染者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
