INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25996, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "action", "definition": "把一件事分成几个步骤来做。", "primary_collocate": null, "pronunciation": "fēn jiē duàn", "ipa": "fən˥ tɕjɛ˥ twan˥˩", "syllable_count": 3, "sentences": [{"text": "我们把这个大项目分阶段做，就不会太累。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语要分阶段，先学拼音。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们分阶段写这篇文章。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分阶段给这个大房子买家具。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家可以分阶段进行，一天搬一点。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分阶段学习，每个月学一个主题。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先复习数学，再复习语文，把考试复习分阶段安排好了。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜要分阶段做，先炒后煮。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，存钱也要分阶段，一步一步来。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们分阶段看完了这本很厚的书。", "target_word": "分阶段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把一件事分成几步来做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分阶段", "is_correct": true, "explanation": "分阶段：副词，表示把工作分成几步来做，与“不会太累”的前提相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上完成，与“分成几步来做”的意思相悖。"}, {"text": "一口气", "is_correct": false, "explanation": "语义：“一口气”表示一次做完、不停歇，与分步做以减轻劳累的意思相悖。"}, {"text": "早已", "is_correct": false, "explanation": "体貌：“早已”表示早就完成，而句中说的是做事的方法，不能用“早已”。"}], "explanations": {"分阶段": "分阶段：副词，表示把工作分成几步来做，与“不会太累”的前提相符。", "立即": "语义：“立即”表示马上完成，与“分成几步来做”的意思相悖。", "一口气": "语义：“一口气”表示一次做完、不停歇，与分步做以减轻劳累的意思相悖。", "早已": "体貌：“早已”表示早就完成，而句中说的是做事的方法，不能用“早已”。"}, "sentence_index": 0, "correct_answer": "分阶段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们分阶段拍了一张合影。", "explanation": "“合影”是一次拍下的画面，无法分成几步来完成，这里“分阶段”不这么用。"}, {"text": "他分阶段打了一个喷嚏。", "explanation": "打喷嚏是一下子发生的动作，不能分成几步来做，这里不能用“分阶段”。"}, {"text": "他们分阶段摔碎了这个大花瓶。", "explanation": "“摔碎”是一瞬间的动作，没有分步完成的过程，这里不能用“分阶段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分阶段", "is_correct": true, "explanation": "分阶段：副词，表示把复习安排成几步，与“安排好了”的说法相符。"}, {"text": "一下子", "is_correct": false, "explanation": "语义：“一下子”表示一次完成，与分步安排复习的做法相悖。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”表示过去的经历，而句中说的是刚完成的安排，不能用“曾经”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不时发生，与对复习进行整体安排的意思相悖。"}], "explanations": {"分阶段": "分阶段：副词，表示把复习安排成几步，与“安排好了”的说法相符。", "一下子": "语义：“一下子”表示一次完成，与分步安排复习的做法相悖。", "曾经": "体貌：“曾经”表示过去的经历，而句中说的是刚完成的安排，不能用“曾经”。", "偶尔": "语义：“偶尔”表示不时发生，与对复习进行整体安排的意思相悖。"}, "sentence_index": 6, "correct_answer": "分阶段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "灯分阶段一下子灭了。", "explanation": "这里应该用〈突然〉。灯灭是一瞬间的事，没有分步的过程，不能用“分阶段”。"}, {"text": "他分阶段突然笑了起来。", "explanation": "这里应该用〈一下子〉。分阶段指分步做，笑起来是瞬间的反应，不能用“分阶段”。"}, {"text": "他分阶段拍了一下桌子。", "explanation": "这里应该用〈一次性〉。分阶段指分几步做，拍一下桌子是一次完成的动作，不能分阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分阶段了整理房间。", "corrected_sentence": "我们分阶段整理房间。", "error_description": "错误：“分阶段”后面加了“了”。正确：“分阶段”是副词，后面不能直接加“了”，应写作“我们分阶段整理房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的分阶段搬走了东西。", "corrected_sentence": "他们分阶段搬走了东西。", "error_description": "错误：“分阶段”前误加了“的”。正确：“分阶段”直接作状语，放在动词之前，写作“他们分阶段搬走了东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
