INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来做塑料袋和塑料瓶的软软的、可以弯的材料。", "primary_collocate": null, "pronunciation": "jù yǐ xī", "ipa": "tɕy˥˩ i˨˩˦ ɕi˥", "syllable_count": 3, "sentences": [{"text": "这个塑料瓶是聚乙烯做的，捏一下就会变形。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯软软的，可以弯，也很轻。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一个聚乙烯做的小水桶。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的塑料袋都是聚乙烯做的。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯不会碎，小孩用着很放心。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子用聚乙烯做，掉在地上也不会破。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，聚乙烯比纸软，也比纸轻。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用聚乙烯做的袋子装水果。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯可以弯来弯去，所以适合做水管。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗发水的瓶子常常是聚乙烯做的，一捏就扁。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高密度聚乙烯", "label": "复合"}, {"form": "聚乙烯薄膜", "label": "复合"}], "register": "中性", "sense_fingerprint": "又软又能弯的塑料材料，常做塑料袋和塑料瓶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚乙烯", "is_correct": true, "explanation": "聚乙烯：名词，指又软又能弯的塑料材料，与“捏一下就会变形”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃硬，不会因为捏一下就变形，与句中的描述矛盾。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁很硬，捏一下不会变形，与句意矛盾。"}, {"text": "陶瓷", "is_correct": false, "explanation": "搭配：“塑料瓶”的材料不说陶瓷，而且陶瓷也不会被捏变形。"}], "explanations": {"聚乙烯": "聚乙烯：名词，指又软又能弯的塑料材料，与“捏一下就会变形”相符。", "玻璃": "语义：玻璃硬，不会因为捏一下就变形，与句中的描述矛盾。", "钢铁": "语义：钢铁很硬，捏一下不会变形，与句意矛盾。", "陶瓷": "搭配：“塑料瓶”的材料不说陶瓷，而且陶瓷也不会被捏变形。"}, "sentence_index": 0, "correct_answer": "聚乙烯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "聚乙烯昨天给我打了一个电话。", "explanation": "聚乙烯是材料，不是人，不会打电话，这个词不这么用。"}, {"text": "他们吃了一大碗聚乙烯。", "explanation": "聚乙烯是塑料，不能食用，这里不能当作食物来吃。"}, {"text": "这些聚乙烯是我的好朋友。", "explanation": "聚乙烯是材料，不能指人，这里不能用来称呼朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚乙烯", "is_correct": true, "explanation": "聚乙烯：名词，指又软又轻的塑料，与“比纸软，也比纸轻”的描述相符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头比纸硬，也不比纸轻，与句中“比纸软”的比较矛盾。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁很硬，并不比纸软，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头很硬，并不比纸软，也比纸重，与句意矛盾。"}], "explanations": {"聚乙烯": "聚乙烯：名词，指又软又轻的塑料，与“比纸软，也比纸轻”的描述相符。", "木头": "语义：木头比纸硬，也不比纸轻，与句中“比纸软”的比较矛盾。", "铁": "语义：铁很硬，并不比纸软，与句意矛盾。", "石头": "语义：石头很硬，并不比纸软，也比纸重，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "聚乙烯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在聚乙烯里举行了婚礼。", "explanation": "聚乙烯是材料，不是场所，不能作为举行婚礼的地点，这个词不这么用。"}, {"text": "妈妈每天给聚乙烯浇水施肥。", "explanation": "聚乙烯是塑料，不是植物，不需要浇水施肥，这里用法不对。"}, {"text": "他把这块聚乙烯读完了，还写了读后感。", "explanation": "聚乙烯是材料，不是书籍，不能用“读完”来说，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个袋子是被聚乙烯做的，很轻。", "corrected_sentence": "这个袋子是用聚乙烯做的，很轻。", "error_description": "错误：用“被”引出做材料的“聚乙烯”不自然。正确：材料应用“用”引出，写作“这个袋子是用聚乙烯做的，很轻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用一个聚乙烯做了一个大箱子。", "corrected_sentence": "工人用聚乙烯做了一个大箱子。", "error_description": "错误：“聚乙烯”是材料，前面不能加“一个”这类量词。正确：直接说“工人用聚乙烯做了一个大箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违规", "is_correct": true, "explanation": "正确：“违规”指不符合规定，与“合规”意思相反。"}, {"text": "陈旧", "is_correct": false, "explanation": "不是反义：“陈旧”说东西旧，与“合规”的意思无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "不是反义：“粗糙”说表面不光滑，与“合规”无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "不是反义：“迟钝”说反应慢，与“合规”无关。"}], "correct_answer": "违规", "explanations": {"违规": "正确：“违规”指不符合规定，与“合规”意思相反。", "陈旧": "不是反义：“陈旧”说东西旧，与“合规”的意思无关。", "粗糙": "不是反义：“粗糙”说表面不光滑，与“合规”无关。", "迟钝": "不是反义：“迟钝”说反应慢，与“合规”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违规", "is_correct": true, "explanation": "正确：“违规”指不符合规定，与“合规”意思相反。"}, {"text": "宽敞", "is_correct": false, "explanation": "不是反义：“宽敞”说空间大，与“合规”无关。"}, {"text": "甜", "is_correct": false, "explanation": "不是反义：“甜”说味道，与“合规”无关。"}, {"text": "干净", "is_correct": false, "explanation": "不是反义：“干净”说卫生状况，与“合规”无关。"}], "correct_answer": "违规", "explanations": {"违规": "正确：“违规”指不符合规定，与“合规”意思相反。", "宽敞": "不是反义：“宽敞”说空间大，与“合规”无关。", "甜": "不是反义：“甜”说味道，与“合规”无关。", "干净": "不是反义：“干净”说卫生状况，与“合规”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情符合规则或要求。", "primary_collocate": null, "pronunciation": "hé guī", "ipa": "xɤ˧˥ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "这家公司的做法完全合规。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查这份合同是否合规。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要合规经营，不能骗客人。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法不合规，经理不同意。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的每一笔交易都要合规。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的采购流程都合规。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每年都要做合规检查。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样写报告不合规，要重新写。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要合规，你就可以放心做。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的广告很合规，没有问题。", "target_word": "合规", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合规", "label": "否定形式"}, {"form": "合规性", "label": "复合词"}], "register": "正式", "sense_fingerprint": "做法符合法规、制度或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合规", "is_correct": true, "explanation": "正确：“完全”后面要接形容词，“合规”说明做法符合规定。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能用来形容做法。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或房间，不能用来形容做法。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或人，“做法安静”说不通。"}], "explanations": {"合规": "正确：“完全”后面要接形容词，“合规”说明做法符合规定。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不能用来形容做法。", "明亮": "语义：“明亮”形容光线或房间，不能用来形容做法。", "安静": "语义：“安静”形容环境或人，“做法安静”说不通。"}, "sentence_index": 0, "correct_answer": "合规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很合规，上课从不说话。", "explanation": "这里应该用〈规矩〉。“合规”用于做法、流程，说人守规矩要用“规矩”。"}, {"text": "这次考试他合规了，成绩很好。", "explanation": "这里应该用〈合格〉。考试、产品说“合格”，“合规”指做法符合规定。"}, {"text": "他的身高很合规，比同班同学都高。", "explanation": "这里应该用〈高〉。“合规”指做法符合规定，不能用来形容身高，说身高要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合规", "is_correct": true, "explanation": "正确：“合规检查”指检查是否符合规定，符合这里的语境。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说的是味道，“辣检查”说不通。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面，不能用来修饰检查。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外表，不能用来修饰“检查”。"}], "explanations": {"合规": "正确：“合规检查”指检查是否符合规定，符合这里的语境。", "辣": "语义：“辣”说的是味道，“辣检查”说不通。", "热闹": "语义：“热闹”形容场面，不能用来修饰检查。", "漂亮": "搭配：“漂亮”形容外表，不能用来修饰“检查”。"}, "sentence_index": 6, "correct_answer": "合规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话很合规，大家都愿意听。", "explanation": "这里应该用〈合理〉。“合规”用于做法、流程，说话有道理要用“合理”。"}, {"text": "她今天穿的裙子很合规，非常好看。", "explanation": "这里应该用〈漂亮〉。说衣服好看要用“漂亮”，“合规”指做法符合规定，不用来评价外表。"}, {"text": "他最近的身体很合规。", "explanation": "这里应该用〈正常〉。说身体的状态要用“正常”，“合规”不用于身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的做法被完全合规。", "corrected_sentence": "他们的做法完全合规。", "error_description": "错误：“被”用在形容词“合规”前面，“合规”不是被动动词；正确：“完全合规”，直接用程度副词修饰形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的做法已经把合规了。", "corrected_sentence": "这家店的做法已经合规了。", "error_description": "错误：“把”用在形容词“合规”前面，“把”字句需要有动作和宾语；正确：“已经合规了”，直接用形容词加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
