INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种很薄很软的片。", "primary_collocate": null, "pronunciation": "bó mó", "ipa": "po˧˥ mo˧˥", "syllable_count": 2, "sentences": [{"text": "这层薄膜又薄又软。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用薄膜把剩菜盖上。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的手机上有一层薄膜。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撕下薄膜，才开始用新手机。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "薄膜很透明，能看到里面的东西。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩玩薄膜，不小心把它弄破了。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张薄膜太软了，拿不稳。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把杯口的薄膜撕掉。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户上贴着一层薄膜，外面看不清里面。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "薄膜有点儿粘手，不好撕。", "target_word": "薄膜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层薄膜", "label": "量词"}, {"form": "一张薄膜", "label": "量词"}, {"form": "塑料薄膜", "label": "复合"}], "register": "中性", "sense_fingerprint": "又薄又软的一片东西，可以盖在物品上或撕下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薄膜", "is_correct": true, "explanation": "正确：指又薄又软的一片东西，「这层薄膜又薄又软」与之相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头坚硬，不可能又薄又软。"}, {"text": "铁皮", "is_correct": false, "explanation": "语义：铁皮是金属，质地硬，与「又软」矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃硬而脆，与「又软」矛盾。"}], "explanations": {"薄膜": "正确：指又薄又软的一片东西，「这层薄膜又薄又软」与之相符。", "石头": "语义：石头坚硬，不可能又薄又软。", "铁皮": "语义：铁皮是金属，质地硬，与「又软」矛盾。", "玻璃": "语义：玻璃硬而脆，与「又软」矛盾。"}, "sentence_index": 0, "correct_answer": "薄膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子把薄膜搭成了一座城堡。", "explanation": "这里应该用〈积木〉。〈薄膜〉薄而软，立不起来，不能像积木那样搭成城堡。"}, {"text": "妈妈用薄膜洗碗。", "explanation": "这里应该用〈海绵〉。薄膜又薄又滑，不能用来擦洗；洗碗要用海绵这类能吸水、能擦洗的东西。"}, {"text": "他用薄膜当了一张餐桌，饭菜都放在上面。", "explanation": "这里应该用〈木板〉。〈薄膜〉薄而软，撑不起饭菜，做不了餐桌；餐桌要用〈木板〉这类硬实材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薄膜", "is_correct": true, "explanation": "正确：薄膜软而难拿稳，「这张薄膜太软了，拿不稳」与之相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子坚硬，不可能「太软」，与句意矛盾。"}, {"text": "钢板", "is_correct": false, "explanation": "搭配：形容钢板常用「硬」「厚」，不说「太软」。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是坚硬的平板，与「太软」「拿不稳」的说法矛盾。"}], "explanations": {"薄膜": "正确：薄膜软而难拿稳，「这张薄膜太软了，拿不稳」与之相符。", "桌子": "语义：桌子坚硬，不可能「太软」，与句意矛盾。", "钢板": "搭配：形容钢板常用「硬」「厚」，不说「太软」。", "黑板": "语义：黑板是坚硬的平板，与「太软」「拿不稳」的说法矛盾。"}, "sentence_index": 6, "correct_answer": "薄膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用薄膜熨衣服，衣服很快就平了。", "explanation": "这里应该用〈熨斗〉。〈薄膜〉经不起高温，不能熨衣服；熨衣服要用〈熨斗〉。"}, {"text": "她用薄膜擦眼泪，眼睛都红了。", "explanation": "这里应该用〈纸巾〉。薄膜光滑、不吸水，不能用来擦眼泪。"}, {"text": "这台老冰箱的薄膜门生锈了，关不严。", "explanation": "这里应该用〈铁皮〉。〈薄膜〉是薄软的片材，不会生锈，也做不了冰箱门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把菜盖上一只薄膜，放进冰箱。", "corrected_sentence": "妈妈把菜盖上一张薄膜，放进冰箱。", "error_description": "量词错误：薄膜是片状材料，应说「一张薄膜」或「一层薄膜」，不能用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明把书上的一本薄膜撕下来了。", "corrected_sentence": "小明把书上的一张薄膜撕下来了。", "error_description": "量词错误：薄膜是片状的东西，应说「一张薄膜」或「一层薄膜」，不能用「本」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
