INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "替代品就是可以代替别的东西的东西。", "primary_collocate": null, "pronunciation": "tì dài pǐn", "ipa": "tʰi˥˩ taɪ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "牛奶喝不了，可以用豆浆做替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的笔丢了，先用铅笔当替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有黄油的时候，植物油是个好替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架坏了，我暂时用纸箱做替代品。", "target_word": "替代品", "complexity_tier": "T3", "furigana": "shū jià huài le wǒ zàn shí yòng zhǐ xiāng zuò tì dài pǐn", "sentence_source": "generated"}, {"text": "白糖的替代品有蜂蜜，也有红糖。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里没有真花，只有塑料花这种替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗衣液比原来的便宜，是很好的替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影票卖完了，在家看视频只是替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有雨伞，一份报纸也能当替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具太贵，妈妈给我买了替代品。", "target_word": "替代品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "替代品：可以代替别的东西的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011ef80-ac60-421d-b57c-d6ae5cde0e0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替代品", "is_correct": true, "explanation": "正确。“用豆浆做替代品”表示用豆浆代替牛奶，句意通顺。"}, {"text": "老师", "is_correct": false, "explanation": "语义：豆浆不能被做成老师，这个搭配不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用豆浆来制作，与句中“做”的对象不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不能用豆浆制作，“用豆浆做钢琴”不成立。"}], "explanations": {"替代品": "正确。“用豆浆做替代品”表示用豆浆代替牛奶，句意通顺。", "老师": "语义：豆浆不能被做成老师，这个搭配不成立。", "空气": "语义：空气不能用豆浆来制作，与句中“做”的对象不符。", "钢琴": "语义：钢琴不能用豆浆制作，“用豆浆做钢琴”不成立。"}, "sentence_index": 0, "correct_answer": "替代品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是公司的替代品，经常接受采访。", "explanation": "这里应该用〈发言人〉。替代品指可代替物品或功能的东西，不用来指代表公司接受采访的人。"}, {"text": "我们的替代品是南方的一支球队。", "explanation": "这里应该用〈对手〉。替代品指可代替某物或某功能的东西，不能用来指比赛中与我们竞争的队伍。"}, {"text": "他是球队的替代品，负责带领大家训练。", "explanation": "这里应该用〈队长〉。替代品指可代替物品或功能的东西，不用来指担任职务、带领大家训练的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替代品", "is_correct": true, "explanation": "正确。“是很好的替代品”说明这种洗衣液能代替原来的产品，句意通顺。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是动作，不能与“很好的”组成指物的名词短语来评价洗衣液。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是动作，不能作为洗衣液的替代物，与句意不符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指成婚，与洗衣液无关，不能作为“替代品”，句意不通。"}], "explanations": {"替代品": "正确。“是很好的替代品”说明这种洗衣液能代替原来的产品，句意通顺。", "睡觉": "语义：睡觉是动作，不能与“很好的”组成指物的名词短语来评价洗衣液。", "唱歌": "语义：唱歌是动作，不能作为洗衣液的替代物，与句意不符。", "结婚": "语义：“结婚”指成婚，与洗衣液无关，不能作为“替代品”，句意不通。"}, "sentence_index": 6, "correct_answer": "替代品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班的替代品，每天帮老师收作业。", "explanation": "这里应该用〈班长〉。替代品指可以代替别的东西的东西，不用来指班里负责事务的人。"}, {"text": "替代品带我们去了博物馆。", "explanation": "这里应该用〈导游〉。替代品指可代替物品或功能的东西，不用来指带领游客参观的人。"}, {"text": "这家饭店的替代品做菜很好吃。", "explanation": "这里应该用〈厨师〉。替代品指可以代替别的东西的东西，不用来指做菜的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一块替代品。", "corrected_sentence": "我买了一种替代品。", "error_description": "量词错误：“块”用于块状或片状的东西，替代品应用“种”或“个”，“一块替代品”应改为“一种替代品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一个很好替代品。", "corrected_sentence": "我买了一个很好的替代品。", "error_description": "修饰语漏“的”：形容词“很好”修饰名词“替代品”时应加“的”，“很好替代品”应改为“很好的替代品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低落", "is_correct": true, "explanation": "正确。“低落”与“高昂”相对，都指情绪或精神的高低。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”形容清楚明白，与情绪高低没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”形容质地结实，与情绪高低没有反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "“遥远”形容距离远，与情绪高低没有反义关系。"}], "correct_answer": "低落", "explanations": {"低落": "正确。“低落”与“高昂”相对，都指情绪或精神的高低。", "清晰": "“清晰”形容清楚明白，与情绪高低没有反义关系。", "坚硬": "“坚硬”形容质地结实，与情绪高低没有反义关系。", "遥远": "“遥远”形容距离远，与情绪高低没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
