INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "情绪很高，很激动。", "primary_collocate": null, "pronunciation": "gāo áng", "ipa": "kɑʊ˥ ɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始前，球员们士气高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他热情高昂地向大家介绍了新计划。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队赢了以后，球迷们兴致高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们斗志高昂地出发了。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演讲时，他的情绪越来越高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游团的游客们情绪高昂，一路说笑。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励让我们的学习热情更高昂了。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，但是大家的精神依然高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到出发的消息，孩子们的情绪立刻高昂起来。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员们整天训练，却始终保持着高昂的士气。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "士气高昂", "label": "复合"}, {"form": "斗志高昂", "label": "复合"}, {"form": "情绪高昂", "label": "复合"}], "register": "中性", "sense_fingerprint": "情绪、士气、斗志很高涨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高昂", "is_correct": true, "explanation": "正确。“士气高昂”形容精神饱满、情绪高涨，符合比赛前的语境。"}, {"text": "高明", "is_correct": false, "explanation": "语义：“高明”形容技艺或见识出众，不能形容“士气”。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“高速”说速度，不能说士气高速。"}, {"text": "高深", "is_correct": false, "explanation": "语义：“高深”形容学问或道理深奥，与“士气”不搭。"}], "explanations": {"高昂": "正确。“士气高昂”形容精神饱满、情绪高涨，符合比赛前的语境。", "高明": "语义：“高明”形容技艺或见识出众，不能形容“士气”。", "高速": "搭配：“高速”说速度，不能说士气高速。", "高深": "语义：“高深”形容学问或道理深奥，与“士气”不搭。"}, "sentence_index": 0, "correct_answer": "高昂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温很高昂。", "explanation": "这里应该用〈高〉。高昂形容情绪、激动的心情，不能用来说气温。"}, {"text": "她的书法很高昂，很多人都来请教。", "explanation": "这里应该用〈高明〉。高昂形容情绪，不能用来说书法的水平，形容技艺要用“高明”。"}, {"text": "他的个子很高昂。", "explanation": "这里应该用〈高〉。高昂形容情绪、士气，不能描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高昂", "is_correct": true, "explanation": "正确。“热情更高昂了”表示情绪比之前更高涨，符合鼓励后的语境。"}, {"text": "高超", "is_correct": false, "explanation": "搭配：“高超”修饰技艺，不能修饰“热情”。"}, {"text": "高傲", "is_correct": false, "explanation": "语义：“高傲”形容态度自大，与“鼓励”带来的积极情绪相反。"}, {"text": "高雅", "is_correct": false, "explanation": "语义：“高雅”形容格调文雅，不能形容学习热情。"}], "explanations": {"高昂": "正确。“热情更高昂了”表示情绪比之前更高涨，符合鼓励后的语境。", "高超": "搭配：“高超”修饰技艺，不能修饰“热情”。", "高傲": "语义：“高傲”形容态度自大，与“鼓励”带来的积极情绪相反。", "高雅": "语义：“高雅”形容格调文雅，不能形容学习热情。"}, "sentence_index": 6, "correct_answer": "高昂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批产品的质量很高昂，客户都很满意。", "explanation": "这里应该用〈好〉。高昂形容情绪，不能用来形容产品的质量，形容质量要用“好”。"}, {"text": "这场晚会的观众人数很高昂，场面很热闹。", "explanation": "这里应该用〈众多〉。高昂形容情绪，不能用来形容人数的多少，这里要用“众多”。"}, {"text": "周末的高昂时段，商场里很挤。", "explanation": "这里应该用〈高峰〉。高昂形容情绪，不能用来形容人流最多的时段，这里要用“高峰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们热情高昂的参加了运动会。", "corrected_sentence": "学生们热情高昂地参加了运动会。", "error_description": "结构助词误用：修饰动词“参加”的状语要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到胜利的消息，球迷们的兴致立刻高昂下来。", "corrected_sentence": "听到胜利的消息，球迷们的兴致立刻高昂起来。", "error_description": "趋向补语误用：“高昂”表示情绪上升，应该用“起来”，“下来”表示下降，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
