INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很清楚，容易看明白。", "primary_collocate": null, "pronunciation": "qīng xī", "ipa": "tɕʰiŋ˥ ɕi˥", "syllable_count": 2, "sentences": [{"text": "这张照片很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音非常清晰，我听得懂。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里的声音不太清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机拍的照片很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得很清晰，大家都明白了。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的空气好，远处的树看得很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张地图画得清晰，我一看就懂。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的电视画面不清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话清晰，每个字都听得见。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清晰度", "label": "复合"}, {"form": "清晰地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容声音、图像、思路等很清楚，容易看明白或听明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清晰", "is_correct": true, "explanation": "正确：“清晰”形容照片的图像清楚，可以说“这张照片很清晰”。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”说声音或环境没有噪音，不能用来形容照片。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”说声音，照片不能说响亮。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与照片的清楚与否无关。"}], "explanations": {"清晰": "正确：“清晰”形容照片的图像清楚，可以说“这张照片很清晰”。", "安静": "语义：“安静”说声音或环境没有噪音，不能用来形容照片。", "响亮": "搭配：“响亮”说声音，照片不能说响亮。", "甜": "语义：“甜”说味道，与照片的清楚与否无关。"}, "sentence_index": 0, "correct_answer": "清晰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的天气很清晰，适合出去玩。", "explanation": "这里应该用〈晴朗〉。清晰指图像、声音或思路清楚，天空和天气要说晴朗。"}, {"text": "听到这个消息，她的心情很清晰。", "explanation": "这里应该用〈平静〉。心情是内心的状态，要说平静；清晰只用于能被看清或听清的事物。"}, {"text": "这个孩子的个子很清晰，比同学高出一头。", "explanation": "这里应该用〈高〉。身高要说高；清晰只用于能被看清或听清的事物或思路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清晰", "is_correct": true, "explanation": "正确：“清晰”说远处的树看得分明，符合句意。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道或辛苦，不能用来形容看树的清楚程度。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地，“看得很硬”不能成立。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”说分量或心情，与看树的状态不相干。"}], "explanations": {"清晰": "正确：“清晰”说远处的树看得分明，符合句意。", "苦": "语义：“苦”说味道或辛苦，不能用来形容看树的清楚程度。", "硬": "搭配：“硬”形容质地，“看得很硬”不能成立。", "沉重": "语义：“沉重”说分量或心情，与看树的状态不相干。"}, "sentence_index": 6, "correct_answer": "清晰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳光很清晰，照得人睁不开眼。", "explanation": "这里应该用〈明亮〉。清晰说的是能被看清的图像、声音或思路，阳光的强弱要说明亮。"}, {"text": "这朵花的香气很清晰，远远就能闻到。", "explanation": "这里应该用〈浓郁〉。清晰只用于能被看清或听清的事物或思路，花香要说浓郁。"}, {"text": "微风很清晰，吹在脸上很舒服。", "explanation": "这里应该用〈轻柔〉。微风的轻软感觉要说轻柔，清晰只用于能被看清或听清的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这张照片拍很清晰。", "corrected_sentence": "他把这张照片拍得很清晰。", "error_description": "状态补语错误：“拍”和“很清晰”之间要用“得”连接，应说“拍得很清晰”，不能说“拍很清晰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一段清晰地录音。", "corrected_sentence": "这是一段清晰的录音。", "error_description": "的地误用：修饰名词“录音”要用“的”，应说“清晰的录音”；“地”只用于修饰动词，“清晰地录音”不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
