INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们做事情或活动的地方。", "primary_collocate": null, "pronunciation": "chǎng suǒ", "ipa": "ʈʂʰaŋ˨˩˦ suo̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里是大家玩的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室是我们上课的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市是买东西的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室这种场所要注意安静。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，办公室不是睡觉的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个场所很大，能坐一千人。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们找了一个开会的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育馆是运动的好场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢去有很多游戏的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂是同学们吃饭的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场所", "label": "量词"}, {"form": "公共场所", "label": "复合"}, {"form": "娱乐场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们做事或活动的地方，如教室、超市、体育馆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场所", "is_correct": true, "explanation": "正确：指大家玩耍的地方，「这里是大家玩的场所」符合句意。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，「这里」指地点，不能说「这里是玩具」。"}, {"text": "球", "is_correct": false, "explanation": "语义：球不是地点，不能用来指「这里」。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不是地方，不能用来指「这里」。"}], "explanations": {"场所": "正确：指大家玩耍的地方，「这里是大家玩的场所」符合句意。", "玩具": "语义：玩具是物品，「这里」指地点，不能说「这里是玩具」。", "球": "语义：球不是地点，不能用来指「这里」。", "歌": "语义：歌不是地方，不能用来指「这里」。"}, "sentence_index": 0, "correct_answer": "场所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的场所很好听，大家都爱唱。", "explanation": "这里应该用〈声音〉。场所指地方，不能用来形容歌曲的声音好听。"}, {"text": "这个场所的腿断了，需要修理。", "explanation": "这里应该用〈椅子〉。场所指人们活动的地方，不是家具，没有腿。"}, {"text": "他们开了一个场所的会，很累。", "explanation": "这里应该用〈小时〉。场所指地方，不是时间单位，不能说「一个场所的会」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场所", "is_correct": true, "explanation": "正确：指开会用的地方，「他们找了一个开会的场所」符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是布置给学生的功课，不能用来指开会的地点，句子不通。"}, {"text": "话题", "is_correct": false, "explanation": "语义：话题是谈论的内容，不是开会的地点。"}, {"text": "水稻", "is_correct": false, "explanation": "搭配：「开会」与「水稻」搭配不当，水稻是农作物。"}], "explanations": {"场所": "正确：指开会用的地方，「他们找了一个开会的场所」符合句意。", "作业": "语义：“作业”是布置给学生的功课，不能用来指开会的地点，句子不通。", "话题": "语义：话题是谈论的内容，不是开会的地点。", "水稻": "搭配：「开会」与「水稻」搭配不当，水稻是农作物。"}, "sentence_index": 6, "correct_answer": "场所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他犯了一个很大的场所。", "explanation": "这里应该用〈错误〉。场所指地方，不能指错误；犯的是〈错误〉。"}, {"text": "他放假后回到了场所，见到了家人。", "explanation": "这里应该用〈住处〉。场所指人们做事情、活动的地方，回到自己的住处要说〈住处〉。"}, {"text": "这个场所有十公斤，大家都抬不动。", "explanation": "这里应该用〈箱子〉。场所是地方，不能说有多重；有重量的是〈箱子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房里找了一条安静的场所。", "corrected_sentence": "妈妈在厨房里找了一个安静的场所。", "error_description": "量词错误：场所应说「一个场所」，不能用「条」，「条」用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家把行李搬进了这本场所。", "corrected_sentence": "大家把行李搬进了这个场所。", "error_description": "量词错误：场所应说「这个场所」，不能用「本」，「本」用于书。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确。“充足”表示够、充分，与“不足”互为反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指清晰明白，与“不足”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“不足”没有反义关系。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”形容情绪或场面，与“不足”没有反义关系。"}], "correct_answer": "充足", "explanations": {"充足": "正确。“充足”表示够、充分，与“不足”互为反义。", "清楚": "“清楚”指清晰明白，与“不足”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“不足”没有反义关系。", "热烈": "“热烈”形容情绪或场面，与“不足”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确。“充足”表示够、充分，与“不足”互为反义。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容范围广大，与“不足”没有反义关系。"}, {"text": "平稳", "is_correct": false, "explanation": "“平稳”形容状态安定，与“不足”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或难度，与“不足”没有反义关系。"}], "correct_answer": "充足", "explanations": {"充足": "正确。“充足”表示够、充分，与“不足”互为反义。", "辽阔": "“辽阔”形容范围广大，与“不足”没有反义关系。", "平稳": "“平稳”形容状态安定，与“不足”没有反义关系。", "轻松": "“轻松”形容心情或难度，与“不足”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不够，缺少。", "primary_collocate": null, "pronunciation": "bù zú", "ipa": "pu˥˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "今天我睡眠不足，一直想睡觉。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里光线不足，看书很累。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作经验不足，需要多学习。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的资金不足，不能买这么大的房子。", "target_word": "不足", "complexity_tier": "T3", "furigana": "wǒ men de zī jīn bù zú, bù néng mǎi zhè me dà de fáng zi。", "sentence_source": "generated"}, {"text": "考试时间不足，很多同学没有写完。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这盆花水分不足，叶子都黄了。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他信心不足，所以不敢上台唱歌。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队伍的人数不足，比赛开始不了。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为力气不足，他没有搬动那个箱子。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电量不足，手机马上就要关机了。", "target_word": "不足", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量、程度达不到需要，不够，缺少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c41e43-d819-4200-99d8-f4259434702f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不足", "is_correct": true, "explanation": "正确。不足 bù zú，意思是不够、缺少。"}, {"text": "富足", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f/b），富足意思是钱财、物资充裕，与“不足”相反。"}, {"text": "补足", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，补足意思是补充使之充足。"}, {"text": "不俗", "is_correct": false, "explanation": "sú（第二声）与 zú（第二声）声母不同（z/s），意思是不庸俗。"}], "explanations": {"不足": "正确。不足 bù zú，意思是不够、缺少。", "富足": "fù（第四声）与 bù（第四声）声母不同（f/b），富足意思是钱财、物资充裕，与“不足”相反。", "补足": "bǔ（第三声）与 bù（第四声）声调不同，补足意思是补充使之充足。", "不俗": "sú（第二声）与 zú（第二声）声母不同（z/s），意思是不庸俗。"}, "sentence_index": null, "correct_answer": "不足"}, "level_3": {"options": [{"text": "不足", "is_correct": true, "explanation": "正确。“睡眠不足”指睡得不够，与“一直想睡觉”相符。"}, {"text": "充沛", "is_correct": false, "explanation": "语义：“充沛”指充足饱满，与后文“一直想睡觉”矛盾。"}, {"text": "充裕", "is_correct": false, "explanation": "搭配：“充裕”多用于时间、钱财，一般不说“睡眠充裕”。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”多形容内容、经验，不能说“睡眠丰富”。"}], "explanations": {"不足": "正确。“睡眠不足”指睡得不够，与“一直想睡觉”相符。", "充沛": "语义：“充沛”指充足饱满，与后文“一直想睡觉”矛盾。", "充裕": "搭配：“充裕”多用于时间、钱财，一般不说“睡眠充裕”。", "丰富": "搭配：“丰富”多形容内容、经验，不能说“睡眠丰富”。"}, "sentence_index": 0, "correct_answer": "不足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题的答案很不足，老师却给了满分。", "explanation": "这里应该用〈正确〉。“不足”说数量或条件不够，不能用来评价答案的对错；答案对要说“正确”。"}, {"text": "我们的资金不足，所以能买很大的房子。", "explanation": "这里应该用〈充足〉。“不足”表示不够，与“能买很大的房子”矛盾；说资金多要用“充足”。"}, {"text": "我们的生意很不足，每天都有很多客人。", "explanation": "这里应该用〈兴隆〉。“不足”说数量不够，形容生意好要说“兴隆”，“不足”不能用来描述生意的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不足", "is_correct": true, "explanation": "正确。不足 bù zú，意思是不够、缺少。"}, {"text": "不熟", "is_correct": false, "explanation": "shú（第二声）与 zú（第二声）声母不同（sh/z），不熟意思是不熟悉、不成熟。"}, {"text": "不如", "is_correct": false, "explanation": "rú（第二声）与 zú（第二声）声母不同（r/z），不如意思是比不上。"}, {"text": "不住", "is_correct": false, "explanation": "zhù（第四声）与 zú（第二声）声母不同（zh/z），声调也不同，“不住”意思是控制不了、站不稳。"}, {"text": "不做", "is_correct": false, "explanation": "zuò（第四声）与 zú（第二声）只差韵母中的 o，且声调不同，听感易混；“不做”意思是不去做、不进行。"}], "explanations": {"不足": "正确。不足 bù zú，意思是不够、缺少。", "不熟": "shú（第二声）与 zú（第二声）声母不同（sh/z），不熟意思是不熟悉、不成熟。", "不如": "rú（第二声）与 zú（第二声）声母不同（r/z），不如意思是比不上。", "不住": "zhù（第四声）与 zú（第二声）声母不同（zh/z），声调也不同，“不住”意思是控制不了、站不稳。", "不做": "zuò（第四声）与 zú（第二声）只差韵母中的 o，且声调不同，听感易混；“不做”意思是不去做、不进行。"}, "sentence_index": null, "correct_answer": "不足"}, "level_3": {"options": [{"text": "不足", "is_correct": true, "explanation": "正确。“信心不足”与“不敢上台唱歌”相符。"}, {"text": "坚定", "is_correct": false, "explanation": "语义：“坚定”表示有信心，与“不敢上台唱歌”矛盾。"}, {"text": "高涨", "is_correct": false, "explanation": "语义：“高涨”表示情绪旺盛，与“不敢上台”矛盾。"}, {"text": "冷淡", "is_correct": false, "explanation": "搭配：“冷淡”形容态度，不能用来形容“信心”。"}], "explanations": {"不足": "正确。“信心不足”与“不敢上台唱歌”相符。", "坚定": "语义：“坚定”表示有信心，与“不敢上台唱歌”矛盾。", "高涨": "语义：“高涨”表示情绪旺盛，与“不敢上台”矛盾。", "冷淡": "搭配：“冷淡”形容态度，不能用来形容“信心”。"}, "sentence_index": 6, "correct_answer": "不足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色不足，看起来很健康。", "explanation": "这里应该用〈红润〉。“不足”说数量或条件不够，不能形容脸色；脸色好看、健康要说“红润”。"}, {"text": "这座桥的高度很不足，大船可以安全通过。", "explanation": "这里应该用〈高〉。说桥的净空高度够大船通过要说“高”，“不足”只说数量不够，与“可以安全通过”矛盾。"}, {"text": "今天的天气很不足，我们去爬山吧。", "explanation": "这里应该用〈晴朗〉。天气好坏要用“晴朗”之类的词，“不足”只说数量或条件不够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店人手不足得，忙不过来。", "corrected_sentence": "这家店人手不足，忙不过来。", "error_description": "「不足」作谓语后面直接停顿时不能加“得”，“得”要接补语。应说“人手不足，忙不过来”，不能说“人手不足得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些钱不足买这套房子。", "corrected_sentence": "这些钱不足以买这套房子。", "error_description": "「不足」表示“不够”，后面接动词时要用“不足以”。应说“这些钱不足以买这套房子”，不能说“这些钱不足买这套房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合规", "is_correct": true, "explanation": "合规：符合规定，与“违规”意思相反，是正确答案。"}, {"text": "发表", "is_correct": false, "explanation": "与“违规”无反义关系：“发表”指公开刊登或宣布，与违反规定没有对立关系。"}, {"text": "检查", "is_correct": false, "explanation": "与“违规”无反义关系：“检查”指查看是否有问题，本身不与违规构成反义。"}, {"text": "安排", "is_correct": false, "explanation": "与“违规”无反义关系：“安排”指事先筹划，与违反规定没有对立关系。"}], "correct_answer": "合规", "explanations": {"合规": "合规：符合规定，与“违规”意思相反，是正确答案。", "发表": "与“违规”无反义关系：“发表”指公开刊登或宣布，与违反规定没有对立关系。", "检查": "与“违规”无反义关系：“检查”指查看是否有问题，本身不与违规构成反义。", "安排": "与“违规”无反义关系：“安排”指事先筹划，与违反规定没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合规", "is_correct": true, "explanation": "合规：符合规定，与“违规”意思相反，是正确答案。"}, {"text": "完成", "is_correct": false, "explanation": "与“违规”无反义关系：“完成”指做好某件事，与违反规定没有对立关系。"}, {"text": "参加", "is_correct": false, "explanation": "与“违规”无反义关系：“参加”指加入某项活动，不是违规行为的对立面。"}, {"text": "批准", "is_correct": false, "explanation": "与“违规”无反义关系：“批准”指准许，与违反规定不构成反义。"}], "correct_answer": "合规", "explanations": {"合规": "合规：符合规定，与“违规”意思相反，是正确答案。", "完成": "与“违规”无反义关系：“完成”指做好某件事，与违反规定没有对立关系。", "参加": "与“违规”无反义关系：“参加”指加入某项活动，不是违规行为的对立面。", "批准": "与“违规”无反义关系：“批准”指准许，与违反规定不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做了不对的事情，违反了规定。", "primary_collocate": null, "pronunciation": "wéi guī", "ipa": "uei³⁵ kuei⁵⁵", "syllable_count": 2, "sentences": [{"text": "学生在教室里吃东西就是违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上课玩手机，这是违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时用手打球算违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机闯红灯，违规了。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟违规了，妈妈不让他看电视。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池里跑步是违规的。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开会时睡觉，大家都说他违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次违规，老师没有生气。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在图书馆大声说话也算违规。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队员违规太多，教练很生气。", "target_word": "违规", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "违规了", "label": "体标"}, {"form": "违规过", "label": "体标"}, {"form": "违规行为", "label": "复合"}, {"form": "違規", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做了不对的事，违反了规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011ef80-ac60-421d-b57c-d6ae5cde0e0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违规", "is_correct": true, "explanation": "违规：做了不对的事，与“学生在教室里吃东西就是……”的判断相合，是正确答案。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是赞许好的行为，与“在教室里吃东西”的负面判断矛盾。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对好行为的回报，在教室吃东西不应得到奖励，句意不通。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”指中午睡觉，与“吃东西”无关，句意不通。"}], "explanations": {"违规": "违规：做了不对的事，与“学生在教室里吃东西就是……”的判断相合，是正确答案。", "表扬": "语义：“表扬”是赞许好的行为，与“在教室里吃东西”的负面判断矛盾。", "奖励": "语义：“奖励”是对好行为的回报，在教室吃东西不应得到奖励，句意不通。", "午睡": "语义：“午睡”指中午睡觉，与“吃东西”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "违规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他当众说错话，显得很违规。", "explanation": "这里应该用〈失礼〉。违规指违反规定，不用于形容言行不得体。"}, {"text": "我今天吃了很多蔬菜，真违规。", "explanation": "这里应该用〈健康〉。违规指违反规定，不用于形容吃蔬菜这类健康的行为。"}, {"text": "这台机器违规了，需要维修。", "explanation": "这里应该用〈故障〉。违规的主体是人或行为，机器不能违规，应说出现故障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违规", "is_correct": true, "explanation": "违规：做了不对的事，与“他开会时睡觉，大家都说他……”的评价相合，是正确答案。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是肯定和支持，与“大家都说他”后面的批评性评价矛盾。"}, {"text": "通报", "is_correct": false, "explanation": "语义：“通报”指告知情况，不是对行为的评价，与“大家都说他”的评价语境不合。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”指关心和帮助，与开会睡觉的负面行为无关，句意不通。"}], "explanations": {"违规": "违规：做了不对的事，与“他开会时睡觉，大家都说他……”的评价相合，是正确答案。", "鼓励": "语义：“鼓励”是肯定和支持，与“大家都说他”后面的批评性评价矛盾。", "通报": "语义：“通报”指告知情况，不是对行为的评价，与“大家都说他”的评价语境不合。", "照顾": "语义：“照顾”指关心和帮助，与开会睡觉的负面行为无关，句意不通。"}, "sentence_index": 6, "correct_answer": "违规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的题目很违规，大家都没做完。", "explanation": "这里应该用〈难〉。违规指违反规定，不用于形容题目难度。"}, {"text": "这个学生很违规，每天都早起读书。", "explanation": "这里应该用〈刻苦〉。违规指违反规定，不用于形容学习认真。"}, {"text": "他见到老师很违规，主动问好。", "explanation": "这里应该用〈礼貌〉。违规不用于形容言行有礼貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在课堂上睡觉，被违规了。", "corrected_sentence": "他在课堂上睡觉，违规了。", "error_description": "被字句错误：“违规”不能用于被动句，应说“他违规了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在图书馆里大声喧哗，违规了过。", "corrected_sentence": "她在图书馆里大声喧哗，违规了。", "error_description": "体标错误：“了”和“过”不能连用，应说“违规了”或“违规过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
