INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把政策、计划、办法等付诸执行。", "primary_collocate": null, "pronunciation": "shí shī", "ipa": "ʂʅ˧˥ ʂʅ˥˥", "syllable_count": 2, "sentences": [{"text": "学校下个月开始实施新规定。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定实施这个新办法。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案已经实施三年了。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按时实施了环保方案。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院从下周起实施新的收费标准。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的交通规则明年一月实施。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要实施这个计划，我们还缺钱。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在全城实施了限行。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策实施以后，空气好多了。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师实施了新的教学方法。", "target_word": "实施", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實施", "label": "繁体"}, {"form": "实施方案", "label": "复合"}], "register": "书面", "sense_fingerprint": "把政策、计划、办法等付诸执行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26018, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实施", "is_correct": true, "explanation": "正确：实施 shí shī，做事使计划、政策成为现实，如「实施方案」。"}, {"text": "时事", "is_correct": false, "explanation": "时事 shí shì：第二个字 shì（第四声）与 shī（第一声）声调不同，意思是当前发生的新闻或大事。"}, {"text": "时时", "is_correct": false, "explanation": "时时 shí shí：第二个字 shí（第二声）与 shī（第一声）声调不同，意思是常常、经常。"}, {"text": "史诗", "is_correct": false, "explanation": "史诗 shǐ shī：第一个字 shǐ（第三声）与 shí（第二声）声调不同，意思是叙述英雄事迹的长篇诗歌。"}, {"text": "失事", "is_correct": false, "explanation": "失事 shī shì：两个字的声调都与「实施」不同，意思是飞机、船只等遭遇事故。"}], "explanations": {"实施": "正确：实施 shí shī，做事使计划、政策成为现实，如「实施方案」。", "时事": "时事 shí shì：第二个字 shì（第四声）与 shī（第一声）声调不同，意思是当前发生的新闻或大事。", "时时": "时时 shí shí：第二个字 shí（第二声）与 shī（第一声）声调不同，意思是常常、经常。", "史诗": "史诗 shǐ shī：第一个字 shǐ（第三声）与 shí（第二声）声调不同，意思是叙述英雄事迹的长篇诗歌。", "失事": "失事 shī shì：两个字的声调都与「实施」不同，意思是飞机、船只等遭遇事故。"}, "sentence_index": null, "correct_answer": "实施"}, "level_3": {"options": [{"text": "实施", "is_correct": true, "explanation": "正确：「实施」与「新规定」搭配，表示使规定付诸执行。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带「规定」作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指去除污垢，与「规定」无关。"}, {"text": "养成", "is_correct": false, "explanation": "搭配：「养成」接习惯、作风，不接「规定」。"}], "explanations": {"实施": "正确：「实施」与「新规定」搭配，表示使规定付诸执行。", "吃": "搭配：「吃」不能带「规定」作宾语。", "洗": "语义：「洗」指去除污垢，与「规定」无关。", "养成": "搭配：「养成」接习惯、作风，不接「规定」。"}, "sentence_index": 0, "correct_answer": "实施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司实施了一次合作。", "explanation": "这里应该用〈进行〉。实施指把方案或政策付诸执行，合作这类事件要用进行。"}, {"text": "学校实施了一场运动会。", "explanation": "这里应该用〈举办〉。实施用于方案、措施，运动会要用举办。"}, {"text": "他们和我们实施了新的关系。", "explanation": "这里应该用〈建立〉。实施的对象是方案或措施，关系要用建立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26018, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实施", "is_correct": true, "explanation": "正确：实施 shí shī，做事使计划、政策成为现实。"}, {"text": "时世", "is_correct": false, "explanation": "时世 shí shì：第二个字 shì（第四声）与 shī（第一声）声调不同，意思是时代、世道。"}, {"text": "世事", "is_correct": false, "explanation": "世事 shì shì：两个字的声调都与「实施」不同，意思是社会上的各种事情。"}, {"text": "史事", "is_correct": false, "explanation": "史事 shǐ shì：shǐ（第三声）与 shí 声调不同，shì 与 shī 声调也不同，意思是历史上的事件。"}, {"text": "失实", "is_correct": false, "explanation": "失实 shī shí：两个字的声调互换，意思是与事实不符。"}], "explanations": {"实施": "正确：实施 shí shī，做事使计划、政策成为现实。", "时世": "时世 shí shì：第二个字 shì（第四声）与 shī（第一声）声调不同，意思是时代、世道。", "世事": "世事 shì shì：两个字的声调都与「实施」不同，意思是社会上的各种事情。", "史事": "史事 shǐ shì：shǐ（第三声）与 shí 声调不同，shì 与 shī 声调也不同，意思是历史上的事件。", "失实": "失实 shī shí：两个字的声调互换，意思是与事实不符。"}, "sentence_index": null, "correct_answer": "实施"}, "level_3": {"options": [{"text": "实施", "is_correct": true, "explanation": "正确：「实施」与「计划」搭配，表示把计划付诸执行。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」指用牙齿夹住，与「计划」无关。"}, {"text": "踢", "is_correct": false, "explanation": "语义：「踢」指用脚击打，计划不能被这样处理。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」接歌曲，不接「计划」作宾语。"}], "explanations": {"实施": "正确：「实施」与「计划」搭配，表示把计划付诸执行。", "咬": "语义：「咬」指用牙齿夹住，与「计划」无关。", "踢": "语义：「踢」指用脚击打，计划不能被这样处理。", "唱": "搭配：「唱」接歌曲，不接「计划」作宾语。"}, "sentence_index": 6, "correct_answer": "实施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给孩子实施了很大的压力。", "explanation": "这里应该用〈施加〉。实施用于方案、措施，压力要用施加。"}, {"text": "她终于实施了自己的梦想。", "explanation": "这里应该用〈实现〉。实施指把计划付诸执行，梦想要用实现。"}, {"text": "政府在山上实施了一座大桥。", "explanation": "这里应该用〈修建〉。实施的对象是方案或措施，建造桥梁要用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决定下个月实施了新的交通措施。", "corrected_sentence": "政府决定下个月实施新的交通措施。", "error_description": "错误：「实施了」。正确：「实施」。「下个月」是将来的时间，动词后面不能加「了」表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项政策实施地很顺利。", "corrected_sentence": "这项政策实施得很顺利。", "error_description": "错误：「实施地很顺利」。正确：「实施得很顺利」。状态补语要用「得」连接动词和补语，「地」用在动词前作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
