INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "已经有的东西或事情。", "primary_collocate": null, "pronunciation": "yǐ yǒu", "ipa": "i˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "已有的电脑用了五年，该换新的了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de diàn nǎo yòng le wǔ nián gāi huàn xīn de le", "sentence_source": "generated"}, {"text": "已有的椅子不够，再搬两把来。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已有的衣服够穿，我不想再买。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没去相亲，因为他很珍惜已有的感情。", "target_word": "已有", "complexity_tier": "T3", "furigana": "tā méi qù xiàng qīn yīn wèi tā hěn zhēn xī yǐ yǒu de gǎn qíng", "sentence_source": "generated"}, {"text": "请先用完已有的牛奶，再买新的。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已有的答案很清楚，不用再讨论了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de dá àn hěn qīng chu bú yòng zài tǎo lùn le", "sentence_source": "generated"}, {"text": "家里已有的两辆自行车足够了，不需要第三辆。", "target_word": "已有", "complexity_tier": "T3", "furigana": "jiā li yǐ yǒu de liǎng liàng zì xíng chē zú gòu le bù xū yào dì sān liàng", "sentence_source": "generated"}, {"text": "这本书是图书馆已有的，你可以去借。", "target_word": "已有", "complexity_tier": "T3", "furigana": "zhè běn shū shì tú shū guǎn yǐ yǒu de nǐ kě yǐ qù jiè", "sentence_source": "generated"}, {"text": "他对已有的工作流程很熟，做事很快。", "target_word": "已有", "complexity_tier": "T3", "furigana": "tā duì yǐ yǒu de gōng zuò liú chéng hěn shú zuò shì hěn kuài", "sentence_source": "generated"}, {"text": "已有的计划不能改，只能照做。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "已有：已经有的东西或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011ef80-ac60-421d-b57c-d6ae5cde0e0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "已有", "is_correct": true, "explanation": "正确。“已有的电脑”指已经有的电脑，与“用了五年，该换新的了”相呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是动作，不能修饰“电脑”，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是动作，不能用来修饰“电脑”。"}, {"text": "搞", "is_correct": false, "explanation": "语义：“搞”指做、弄，不能修饰“电脑”表示“已经有的”，句意不通。"}], "explanations": {"已有": "正确。“已有的电脑”指已经有的电脑，与“用了五年，该换新的了”相呼应。", "吃": "语义：“吃”是动作，不能修饰“电脑”，句意不通。", "唱": "语义：“唱”是动作，不能用来修饰“电脑”。", "搞": "语义：“搞”指做、弄，不能修饰“电脑”表示“已经有的”，句意不通。"}, "sentence_index": 0, "correct_answer": "已有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天已有去北京了。", "explanation": "这里应该用〈已经〉。“已有”指已经有的东西，不能作副词修饰动作“去”。"}, {"text": "我已有吃过早饭了。", "explanation": "这里应该用〈已经〉。“已有”不能直接放在动词“吃”前面表示动作完成。"}, {"text": "妈妈已有回家了。", "explanation": "这里应该用〈已经〉。“已有”指已经有的东西，不能修饰动作“回家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已有", "is_correct": true, "explanation": "正确。“家里已有的两辆自行车”指家里已经有的两辆自行车，句意通顺。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是动作，不能用来修饰“两辆自行车”。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是动作，不能用来修饰“自行车”，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指成婚，不能用来修饰“自行车”，句意不通。"}], "explanations": {"已有": "正确。“家里已有的两辆自行车”指家里已经有的两辆自行车，句意通顺。", "写": "语义：“写”是动作，不能用来修饰“两辆自行车”。", "打": "语义：“打”是动作，不能用来修饰“自行车”，句意不通。", "结婚": "语义：“结婚”指成婚，不能用来修饰“自行车”，句意不通。"}, "sentence_index": 6, "correct_answer": "已有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个已有的想法，以前从来没人想过。", "explanation": "这里应该用〈新〉。“已有”指已经有的，与“以前从来没人想过”矛盾。"}, {"text": "比赛已有结束了。", "explanation": "这里应该用〈已经〉。“已有”不能作副词修饰动作“结束”。"}, {"text": "我已有知道这件事了。", "explanation": "这里应该用〈已经〉。“已有”不能放在动词“知道”前表示状态已成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家已有了的电脑很旧了。", "corrected_sentence": "我家已有的电脑很旧了。", "error_description": "多余“了”：“已有”作定语时不能带“了”，应说“我家已有的电脑很旧了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家里已有电脑很新。", "corrected_sentence": "我家里已有的电脑很新。", "error_description": "定语标志漏“的”：“已有”修饰“电脑”时要加“的”，“已有电脑”应改为“已有的电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
