INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给别人或对别人做某个动作。", "primary_collocate": null, "pronunciation": "shī yǐ", "ipa": "ʂʅ⁵⁵ i²¹⁴", "syllable_count": 2, "sentences": [{"text": "路人对受伤的人施以急救。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对迟到的学生施以惩罚。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对病人施以治疗，病人很快好了。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民对迷路的旅客施以援手。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对生病的孩子施以关怀。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对乱扔垃圾的人施以惩处。", "target_word": "施以", "complexity_tier": "T3", "furigana": "jǐng chá duì luàn rēng lā jī de rén shī yǐ chéng chǔ", "sentence_source": "generated"}, {"text": "家长要对孩子施以耐心的教育。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对违约的客户施以约束。", "target_word": "施以", "complexity_tier": "T3", "furigana": "gōng sī duì wéi yuē de kè hù shī yǐ yuē shù", "sentence_source": "generated"}, {"text": "他对哭泣的朋友施以安慰。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的人对落水的孩子施以救助。", "target_word": "施以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "给别人或对别人做某个动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011ef80-ac60-421d-b57c-d6ae5cde0e0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施以", "is_correct": true, "explanation": "施以 shīyǐ：给别人或对别人做某个动作，是正确答案。"}, {"text": "十亿", "is_correct": false, "explanation": "十亿 shíyì 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是数字“十亿”。"}, {"text": "诗意", "is_correct": false, "explanation": "诗意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“诗的意境”。"}, {"text": "石椅", "is_correct": false, "explanation": "石椅 shíyǐ 与 施以 shīyǐ 第一个音节声调不同：shí（第二声）与 shī（第一声），意思是“石头做的椅子”。"}, {"text": "时宜", "is_correct": false, "explanation": "时宜 shíyí 与 施以 shīyǐ 两个音节声调都不同，意思是“适合当时的情况”。"}], "explanations": {"施以": "施以 shīyǐ：给别人或对别人做某个动作，是正确答案。", "十亿": "十亿 shíyì 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是数字“十亿”。", "诗意": "诗意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“诗的意境”。", "石椅": "石椅 shíyǐ 与 施以 shīyǐ 第一个音节声调不同：shí（第二声）与 shī（第一声），意思是“石头做的椅子”。", "时宜": "时宜 shíyí 与 施以 shīyǐ 两个音节声调都不同，意思是“适合当时的情况”。"}, "sentence_index": null, "correct_answer": "施以"}, "level_3": {"options": [{"text": "收到", "is_correct": false, "explanation": "配价：“收到”的主语应是接受者，这里主语是“路人”，不能说“路人收到急救”。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能与“急救”搭配，不说“扔急救”。"}, {"text": "施以", "is_correct": true, "explanation": "施以：对受伤的人实施急救，与“急救”搭配，符合句意。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指得到乐趣或好处，与“急救”的救助义不符。"}], "explanations": {"收到": "配价：“收到”的主语应是接受者，这里主语是“路人”，不能说“路人收到急救”。", "扔": "搭配：“扔”不能与“急救”搭配，不说“扔急救”。", "施以": "施以：对受伤的人实施急救，与“急救”搭配，符合句意。", "享受": "语义：“享受”指得到乐趣或好处，与“急救”的救助义不符。"}, "sentence_index": 0, "correct_answer": "施以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村民对迷路的旅客施以问候。", "explanation": "这里应该用〈致以〉。施以的宾语是援手、救助等实际行为，问候是礼节性的话语，要说“致以问候”。"}, {"text": "村民对迷路的旅客施以欢迎。", "explanation": "这里应该用〈表示〉。施以的宾语是援手、关怀等具体行为，欢迎是态度，要说“表示欢迎”。"}, {"text": "村民对迷路的旅客施以建议。", "explanation": "这里应该用〈提出〉。施以的宾语是行为或帮助，建议是言语，要说“提出建议”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26022, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "施以", "is_correct": true, "explanation": "施以 shīyǐ：给别人或对别人做某个动作，是正确答案。"}, {"text": "示意", "is_correct": false, "explanation": "示意 shìyì 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是“用动作或表情表达意思”。"}, {"text": "事宜", "is_correct": false, "explanation": "事宜 shìyí 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yí（第二声）与 yǐ（第三声），意思是“具体的事情和安排”。"}, {"text": "失意", "is_correct": false, "explanation": "失意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“不得志、情绪低落”。"}, {"text": "十一", "is_correct": false, "explanation": "十一 shíyī 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yī（第一声）与 yǐ（第三声），意思是数字“十一”。"}], "explanations": {"施以": "施以 shīyǐ：给别人或对别人做某个动作，是正确答案。", "示意": "示意 shìyì 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是“用动作或表情表达意思”。", "事宜": "事宜 shìyí 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yí（第二声）与 yǐ（第三声），意思是“具体的事情和安排”。", "失意": "失意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“不得志、情绪低落”。", "十一": "十一 shíyī 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yī（第一声）与 yǐ（第三声），意思是数字“十一”。"}, "sentence_index": null, "correct_answer": "施以"}, "level_3": {"options": [{"text": "献出", "is_correct": false, "explanation": "搭配：“献出”多接“生命、爱心、力量”，不说“献出耐心的教育”。"}, {"text": "施以", "is_correct": true, "explanation": "施以：对孩子给予教育，与“耐心的教育”搭配，符合句意。"}, {"text": "接受", "is_correct": false, "explanation": "配价：“接受”的主语应是受教育的孩子，这里主语是“家长”，不能说“家长接受耐心的教育”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指享有好处，与句中家长对孩子施予教育的方向相反。"}], "explanations": {"献出": "搭配：“献出”多接“生命、爱心、力量”，不说“献出耐心的教育”。", "施以": "施以：对孩子给予教育，与“耐心的教育”搭配，符合句意。", "接受": "配价：“接受”的主语应是受教育的孩子，这里主语是“家长”，不能说“家长接受耐心的教育”。", "享受": "语义：“享受”指享有好处，与句中家长对孩子施予教育的方向相反。"}, "sentence_index": 6, "correct_answer": "施以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她对同事施以责任。", "explanation": "这里应该用〈承担〉。施以用于对人施加行为，责任是承担的，要说“承担责任”。"}, {"text": "老师对同学施以意见。", "explanation": "这里应该用〈发表〉。施以的宾语是行为或援助，意见是要发表的，要说“发表意见”。"}, {"text": "公司对客户施以费用。", "explanation": "这里应该用〈收取〉。费用是收取的，施以用于对人施加行为，不说“施以费用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士受伤的士兵施以护理。", "corrected_sentence": "护士对受伤的士兵施以护理。", "error_description": "错误：引出承受者的「对」被丢掉，「受伤的士兵」与「护士」连在一起，句意不通。正确：「施以」的对象要用「对」引出，应写作「护士对受伤的士兵施以护理」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防员把被困的人施以救援。", "corrected_sentence": "消防员对被困的人施以救援。", "error_description": "错误：「施以」引出承受者须用「对」，「把」字句不能与「施以」搭配。正确：应写作「消防员对被困的人施以救援」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
