INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "禁令是不许做某件事的规定。", "primary_collocate": null, "pronunciation": "jìn lìng", "ipa": "tɕin⁵¹ liŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "学校有一条禁令：上课不许玩手机。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条禁令很清楚，大家都要遵守。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的禁令说，办公室里不能抽烟。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院走廊里贴着一条禁令：不许在病房里吸烟。", "target_word": "禁令", "complexity_tier": "T3", "furigana": "yī yuàn zǒu láng lǐ tiē zhe yì tiáo jìn lìng bù xǔ zài bìng fáng lǐ xī yān", "sentence_source": "generated"}, {"text": "他没看到禁令，还在草地上踢球。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这个禁令是为了大家的安全。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给家里定了一条禁令：晚上十点后不看电视。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的牌子上写着禁令：不许游泳。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个禁令已经有十年了，现在还有用。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都不喜欢家里的新禁令。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "项", "label": "量词"}], "register": "书面", "sense_fingerprint": "不许做某件事的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011ef80-ac60-421d-b57c-d6ae5cde0e0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：与“学校有一条……：上课不许玩手机”的规定内容相合，是正确答案。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”是菜谱，与“上课不许玩手机”的禁止内容无关，句子不通。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：“奖状”是表彰证书，不是禁止规定，与后面的禁止内容矛盾。"}, {"text": "课表", "is_correct": false, "explanation": "语义：“课表”是课程安排表，不是禁止性规定，与句中的禁止内容不符。"}], "explanations": {"禁令": "禁令：与“学校有一条……：上课不许玩手机”的规定内容相合，是正确答案。", "食谱": "语义：“食谱”是菜谱，与“上课不许玩手机”的禁止内容无关，句子不通。", "奖状": "语义：“奖状”是表彰证书，不是禁止规定，与后面的禁止内容矛盾。", "课表": "语义：“课表”是课程安排表，不是禁止性规定，与句中的禁止内容不符。"}, "sentence_index": 0, "correct_answer": "禁令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校贴出一条禁令，要求每位学生都穿校服。", "explanation": "这里应该用〈规定〉。禁令专指禁止某种行为，要求穿校服属于一般规定。"}, {"text": "医院走廊里贴着一条禁令：下周三有体检。", "explanation": "这里应该用〈通知〉。禁令是禁止性的规定，不用于告知体检时间。"}, {"text": "出门前，妈妈的禁令是：一定要带好雨伞。", "explanation": "这里应该用〈嘱咐〉。禁令是不许做某事的规定，要求带伞是叮嘱人去做事，应说“妈妈的嘱咐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：与“定了一条……：晚上十点后不看电视”的约束内容相合，是正确答案。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“定”多接规定、规则，不能说“定了一条座位”。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：“歌词”是歌曲的文字，与“晚上十点后不看电视”的约束内容无关。"}, {"text": "名言", "is_correct": false, "explanation": "语义：“名言”是有道理的格言，没有约束力，不能用来“定”下不看电视的要求。"}], "explanations": {"禁令": "禁令：与“定了一条……：晚上十点后不看电视”的约束内容相合，是正确答案。", "座位": "搭配：“定”多接规定、规则，不能说“定了一条座位”。", "歌词": "语义：“歌词”是歌曲的文字，与“晚上十点后不看电视”的约束内容无关。", "名言": "语义：“名言”是有道理的格言，没有约束力，不能用来“定”下不看电视的要求。"}, "sentence_index": 6, "correct_answer": "禁令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸给大家发了一份禁令，邀请我们周末去公园。", "explanation": "这里应该用〈请柬〉。禁令是不许做某事的规定，不用于发出邀请这类事项。"}, {"text": "老师写了一条禁令，评价我的作文很好。", "explanation": "这里应该用〈评语〉。禁令是不许做某事的规定，不用于对作文作出评价。"}, {"text": "妈妈定了一条禁令：下周全家去旅行。", "explanation": "这里应该用〈计划〉。禁令是不许做某事的规定，去旅行是安排，要说“定了一个计划”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里有一只禁令：不许在教室里吃东西。", "corrected_sentence": "班里有一条禁令：不许在教室里吃东西。", "error_description": "量词错误：“禁令”的量词应为“条”（或“项”），“只”多用于动物，不能用于“禁令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈定了一只禁令：晚饭前不许吃零食。", "corrected_sentence": "妈妈定了一条禁令：晚饭前不许吃零食。", "error_description": "量词错误：“禁令”的量词应为“条”（或“项”），“只”多用于动物，不能用于“禁令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5baedbf5-3518-409d-ac55-0b411a166a81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "反义：“放纵”指任由自己或他人不受约束，与“约束”相对。"}, {"text": "陪伴", "is_correct": false, "explanation": "无反义关系：“陪伴”是跟随相伴，与“约束”不构成反义。"}, {"text": "检查", "is_correct": false, "explanation": "无反义关系：“检查”是查看核实，与“约束”不是对立关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "无反义关系：“欢迎”是表示接纳的态度，与“约束”不构成反义。"}], "correct_answer": "放纵", "explanations": {"放纵": "反义：“放纵”指任由自己或他人不受约束，与“约束”相对。", "陪伴": "无反义关系：“陪伴”是跟随相伴，与“约束”不构成反义。", "检查": "无反义关系：“检查”是查看核实，与“约束”不是对立关系。", "欢迎": "无反义关系：“欢迎”是表示接纳的态度，与“约束”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "反义：“放任”指任其自由、不加限制，与“约束”相对。"}, {"text": "尊重", "is_correct": false, "explanation": "无反义关系：“尊重”是敬重，与“约束”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”是修复物品，与“约束”不相对。"}, {"text": "表扬", "is_correct": false, "explanation": "无反义关系：“表扬”是称赞，不是“约束”的反义词。"}], "correct_answer": "放任", "explanations": {"放任": "反义：“放任”指任其自由、不加限制，与“约束”相对。", "尊重": "无反义关系：“尊重”是敬重，与“约束”不构成反义。", "修理": "无反义关系：“修理”是修复物品，与“约束”不相对。", "表扬": "无反义关系：“表扬”是称赞，不是“约束”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是管住别人或自己，不让他做不该做的事。", "primary_collocate": null, "pronunciation": "yuē shù", "ipa": "ɥe˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他很会约束自己。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "父母要约束孩子玩手机的行为。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你应该约束一下自己的脾气。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我约束不了他。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师约束学生不要在课上说话。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常约束不住自己，一直吃零食。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥要约束自己，少吃甜食。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他约束了自己一个月，没有玩游戏。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子太小，没人约束就会乱跑。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自由惯了，不喜欢别人约束他。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约束了", "label": "体标"}, {"form": "约束过", "label": "体标"}, {"form": "自我约束", "label": "复合"}, {"form": "約束", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管住别人或自己，不让做不该做的事（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f2a7402-8426-418d-9154-8fbf1758617b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约束", "is_correct": true, "explanation": "正确：“约束”指管住自己，不让自己做不该做的事，与句意相符。"}, {"text": "绑架", "is_correct": false, "explanation": "语义：“绑架”是非法扣押他人，不能用于“很会……自己”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”接的是车辆等，不能接“自己”。"}, {"text": "批发", "is_correct": false, "explanation": "语义：“批发”是大批销售货物，不能用在人身上。"}], "explanations": {"约束": "正确：“约束”指管住自己，不让自己做不该做的事，与句意相符。", "绑架": "语义：“绑架”是非法扣押他人，不能用于“很会……自己”。", "驾驶": "搭配：“驾驶”接的是车辆等，不能接“自己”。", "批发": "语义：“批发”是大批销售货物，不能用在人身上。"}, "sentence_index": 0, "correct_answer": "约束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校约束学生的宿舍。", "explanation": "这里应该用〈管理〉。“约束”是管住人的行为，不能用于宿舍这类场所。"}, {"text": "他约束着生病的父母。", "explanation": "这里应该用〈照顾〉。“约束”是管住人不让其越界，不表示照料。"}, {"text": "这场大雨约束了一个小时。", "explanation": "这里应该用〈持续〉。“约束”是管住人的行为，不能用来表示时间的长度；大雨的时长应说“持续”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约束", "is_correct": true, "explanation": "正确：“约束”指管住自己，与“减肥要……少吃甜食”的要求相符。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是任由自己，与“少吃甜食”的要求相反。"}, {"text": "纵容", "is_correct": false, "explanation": "语义：“纵容”是迁就、不加制止，与“减肥”的要求相反。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”接的是节目或影像，不能接“自己”。"}], "explanations": {"约束": "正确：“约束”指管住自己，与“减肥要……少吃甜食”的要求相符。", "放纵": "语义：“放纵”是任由自己，与“少吃甜食”的要求相反。", "纵容": "语义：“纵容”是迁就、不加制止，与“减肥”的要求相反。", "播放": "搭配：“播放”接的是节目或影像，不能接“自己”。"}, "sentence_index": 6, "correct_answer": "约束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈约束孩子的健康。", "explanation": "这里应该用〈关心〉。“约束”的对象是人的行为，不能用于“健康”。"}, {"text": "他约束了那幅美丽的画。", "explanation": "这里应该用〈欣赏〉。“约束”是管住人的行为，不能用于画作；欣赏画作应说“欣赏那幅画”。"}, {"text": "这个乐队约束了那首老歌。", "explanation": "这里应该用〈演唱〉。“约束”是管住人的行为，不能用于歌曲；演唱歌曲应说“演唱那首老歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对自己约束了很严格。", "corrected_sentence": "他对自己约束得很严格。", "error_description": "体标误用：「了」表示完成，不能直接接形容词作补语；程度补语前应当用「得」。正确说法是「他对自己约束得很严格」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是约束自己着。", "corrected_sentence": "他总是约束自己。", "error_description": "错误：体标“着”放在了句末宾语“自己”之后。正确句中“约束”后直接接宾语，不加“着”，正确应为“他总是约束自己”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
