INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从另一个方面看，就能看到不同的情况。", "primary_collocate": null, "pronunciation": "fǎn guān", "ipa": "fan˨˩˦ kuan˥˥", "syllable_count": 2, "sentences": [{"text": "小李的成绩一直很好，反观小王，常常不及格。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天南方很热，反观北方，晚上还有点凉。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西的人越来越多，反观商店，客人越来越少。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐喜欢吃辣，反观妹妹，一点辣的也不吃。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的同学都很安静，反观隔壁班，吵得很。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话总是很客气，反观他的朋友，一点也不礼貌。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市工作机会很多，反观小镇，年轻人都走了。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这家工厂赚了很多钱，反观今年，生意差多了。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸身体很好，反观我，经常生病。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边的房子很新，反观右边的，已经很旧了。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "换到另一方面来看，发现情况不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f2a7402-8426-418d-9154-8fbf1758617b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”表示思念过去的人或事，与成绩的前后对照无关，句意不通。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、重量等，不能说“测量小王”，句子不通。"}, {"text": "反观", "is_correct": true, "explanation": "反观：从另一方面看，发现不同的情况，“反观小王”引出与小李相反的成绩，句中正确。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“常常不及格”的情况相矛盾，句意不通。"}], "explanations": {"怀念": "语义：“怀念”表示思念过去的人或事，与成绩的前后对照无关，句意不通。", "测量": "搭配：“测量”的对象是长度、重量等，不能说“测量小王”，句子不通。", "反观": "反观：从另一方面看，发现不同的情况，“反观小王”引出与小李相反的成绩，句中正确。", "赞美": "语义：“赞美”表示称赞，与“常常不及格”的情况相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "反观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在音乐会上反观演奏，非常陶醉。", "explanation": "这里应该用〈聆听〉。反观指引出对照的另一方，不表示用耳朵认真听。"}, {"text": "我们在美术馆反观名画，很有收获。", "explanation": "这里应该用〈欣赏〉。反观指从另一方面看、引出不同的情况，不表示欣赏艺术品。"}, {"text": "站在山上反观大海，心情很好。", "explanation": "这里应该用〈远眺〉。反观指引出对照的情况，不表示向远处望去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”的对象是物品或人，不能说“赠送小镇”，句子不通。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”指洗涤，与城乡机会的对比无关，句意不通。"}, {"text": "挥舞", "is_correct": false, "explanation": "语义：“挥舞”指挥动，与年轻人外流的情况无关，放入句中读不通。"}, {"text": "反观", "is_correct": true, "explanation": "反观：从另一方面看，发现不同的情况，“反观小镇”引出与大城市相反的情况，句中正确。"}], "explanations": {"赠送": "搭配：“赠送”的对象是物品或人，不能说“赠送小镇”，句子不通。", "清洗": "语义：“清洗”指洗涤，与城乡机会的对比无关，句意不通。", "挥舞": "语义：“挥舞”指挥动，与年轻人外流的情况无关，放入句中读不通。", "反观": "反观：从另一方面看，发现不同的情况，“反观小镇”引出与大城市相反的情况，句中正确。"}, "sentence_index": 6, "correct_answer": "反观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家来到纪念馆，反观烈士的遗像。", "explanation": "这里应该用〈瞻仰〉。反观指引出对照的另一方，不表示恭敬地观看。"}, {"text": "他反观这张旧照片，陷入了回忆。", "explanation": "这里应该用〈端详〉。反观指引出对照的另一方，不表示仔细观察某物。"}, {"text": "他反观手机屏幕，半天没说话。", "explanation": "这里应该用〈盯〉。反观指从另一方面看、引出不同的情况，不表示目不转睛地看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里的房价很高，反观，却便宜得多。", "corrected_sentence": "城里的房价很高，反观乡下，却便宜得多。", "error_description": "缺少宾语：“反观”是动词，后面要直接带对照的对象，此处缺少对象；应说「反观乡下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地今年收成很好，反观，几乎没有收成。", "corrected_sentence": "这块地今年收成很好，反观邻居家的地，几乎没有收成。", "error_description": "缺少宾语：“反观”后面要带对照的对象（邻居家的地），不能单独使用。正确说法是「反观邻居家的地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
