INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "几个小地区合起来组成的一个大国家。", "primary_collocate": null, "pronunciation": "lián bāng", "ipa": "ljɛn˧˥ pɑŋ˥", "syllable_count": 2, "sentences": [{"text": "德国是一个联邦，由十六个州组成。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联邦有很多小地区。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小国家合起来，成了一个联邦。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联邦的首都在一个大城市里。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在这个联邦的南部。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联邦的人民都说同一种语言。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联邦有自己的国旗。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瑞士也是一个联邦。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想建立一个新的联邦。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联邦里的每个州都有自己的法律。", "target_word": "联邦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "联邦政府", "label": "复合"}], "register": "书面语", "sense_fingerprint": "由若干州或小国联合组成的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "联邦", "is_correct": true, "explanation": "联邦：由几个州或小国合起来组成的国家，这里指德国。"}, {"text": "省", "is_correct": false, "explanation": "语义：“省”是国家下属的行政区，不能由十六个州组成一个国家。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”指人口聚居的地方，不是由州组成的国家。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“由……组成”通常用于国家、组织等整体，不说公司由州组成。"}], "explanations": {"联邦": "联邦：由几个州或小国合起来组成的国家，这里指德国。", "省": "语义：“省”是国家下属的行政区，不能由十六个州组成一个国家。", "城市": "语义：“城市”指人口聚居的地方，不是由州组成的国家。", "公司": "搭配：“由……组成”通常用于国家、组织等整体，不说公司由州组成。"}, "sentence_index": 0, "correct_answer": "联邦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只联邦很大，有五十个州。", "explanation": "这里应该用〈个〉。“只”多用于动物，联邦指国家，要用量词“个”。"}, {"text": "上海是一个联邦，有很多大街。", "explanation": "这里应该用〈城市〉。联邦指由几个州或地区组成的国家，上海是一座城市，不能说是联邦。"}, {"text": "美国有五十个联邦。", "explanation": "这里应该用〈州〉。联邦是由州组成的整个国家，美国有五十个州，不能说有五十个联邦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联邦", "is_correct": true, "explanation": "联邦：由几个州组成的国家，这里指一个有国旗的国家。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是国家或组织，不能有自己的国旗。"}, {"text": "毛衣", "is_correct": false, "explanation": "语义：“毛衣”是衣物，不可能有自己的国旗。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁”是交通系统，说“有自己的国旗”搭配不当。"}], "explanations": {"联邦": "联邦：由几个州组成的国家，这里指一个有国旗的国家。", "房子": "语义：“房子”不是国家或组织，不能有自己的国旗。", "毛衣": "语义：“毛衣”是衣物，不可能有自己的国旗。", "地铁": "搭配：“地铁”是交通系统，说“有自己的国旗”搭配不当。"}, "sentence_index": 6, "correct_answer": "联邦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "联邦有一百九十多个成员国，每年都召开大会。", "explanation": "这里应该用〈联合国〉。联邦指由几个州或小国组成的一个国家，联合国是由许多国家参加的国际组织，不能叫联邦。"}, {"text": "我和朋友组成了一个联邦，每周聚会。", "explanation": "这里应该用〈小组〉。联邦指由几个州或国家组成的政体，朋友之间的小团体不能叫联邦。"}, {"text": "这座联邦很古老，有很多历史。", "explanation": "这里应该用〈个〉。“座”多用于山、房屋等，联邦要用量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "瑞士是一联邦，有四种官方语言。", "corrected_sentence": "瑞士是一个联邦，有四种官方语言。", "error_description": "错误：瑞士是一联邦。正确：瑞士是一个联邦。作可数名词时前面要加量词“个”，不能直接用数词“一”加名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个联邦们的首都很干净。", "corrected_sentence": "这个联邦的首都很干净。", "error_description": "错误：联邦们的首都。正确：联邦的首都。“们”只用于指人的名词，“联邦”指国家，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "反义：作为名词，“奖励”与“处罚”意思相对，一个是好的回报，一个是惩罚。"}, {"text": "钱包", "is_correct": false, "explanation": "无反义关系：“钱包”是装钱的物品，与“处罚”无关。"}, {"text": "天气", "is_correct": false, "explanation": "无反义关系：“天气”指气候状况，与“处罚”不构成反义。"}, {"text": "花园", "is_correct": false, "explanation": "无反义关系：“花园”是种植花草的地方，与“处罚”不构成反义。"}], "correct_answer": "奖励", "explanations": {"奖励": "反义：作为名词，“奖励”与“处罚”意思相对，一个是好的回报，一个是惩罚。", "钱包": "无反义关系：“钱包”是装钱的物品，与“处罚”无关。", "天气": "无反义关系：“天气”指气候状况，与“处罚”不构成反义。", "花园": "无反义关系：“花园”是种植花草的地方，与“处罚”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
