INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做了不对的事，就要受到处罚。", "primary_collocate": null, "pronunciation": "chǔ fá", "ipa": "tʂʰu˨˩˦ fa˧˥", "syllable_count": 2, "sentences": [{"text": "做错事就要受到处罚。", "target_word": "处罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他因为迟到受到了处罚。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的处罚太重了。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给了他一个小小的处罚。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁都不想接受处罚。", "target_word": "处罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "违规的处罚是罚款五百元。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不怕处罚，还是继续迟到。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对这种行为，法律有严格的处罚。", "target_word": "处罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认了错误，处罚轻了一些。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中打人的处罚是停赛一场。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项处罚", "label": "量词"}, {"form": "处罚决定", "label": "复合"}, {"form": "行政处罚", "label": "复合"}, {"form": "處罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做错事后所受的惩罚（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f2a7402-8426-418d-9154-8fbf1758617b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。"}, {"text": "出发", "is_correct": false, "explanation": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。"}, {"text": "除法", "is_correct": false, "explanation": "chú fǎ（除法）与 chǔ fá 两个音节的声调都不同，意思是数学中的除法。"}, {"text": "触发", "is_correct": false, "explanation": "chù fā（触发）与 chǔ fá 声母韵母相同，两个音节声调不同，意思是引起、引发。"}], "explanations": {"处罚": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。", "出发": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。", "除法": "chú fǎ（除法）与 chǔ fá 两个音节的声调都不同，意思是数学中的除法。", "触发": "chù fā（触发）与 chǔ fá 声母韵母相同，两个音节声调不同，意思是引起、引发。"}, "sentence_index": null, "correct_answer": "处罚"}, "level_3": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确：“处罚”指做错事后受到的惩罚，与句意相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对好表现的回报，与“做错事”相矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“做错事”相矛盾。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“受到”后面接“礼物”不自然，应说“收到礼物”。"}], "explanations": {"处罚": "正确：“处罚”指做错事后受到的惩罚，与句意相符。", "奖励": "语义：“奖励”是对好表现的回报，与“做错事”相矛盾。", "表扬": "语义：“表扬”是称赞，与“做错事”相矛盾。", "礼物": "搭配：“受到”后面接“礼物”不自然，应说“收到礼物”。"}, "sentence_index": 0, "correct_answer": "处罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次违规要交五百元处罚。", "explanation": "这里应该用〈罚款〉。“交”的是钱，应说“交五百元罚款”；“处罚”是制裁本身，不能用“交……元”来表示付款。"}, {"text": "他这次考试得了好处罚。", "explanation": "这里应该用〈成绩〉。“好”用于成绩、结果，“处罚”本身是负面的，不能说“好处罚”。"}, {"text": "他的处罚唱得很好听。", "explanation": "这里应该用〈歌曲〉。“处罚”是对违规行为的制裁，不能用来指歌声；这句要说“他的歌唱得很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。"}, {"text": "厨房", "is_correct": false, "explanation": "chú fáng（厨房）与 chǔ fá 第一音节声调不同，第二音节多了韵尾 ng，意思是做饭的地方。"}, {"text": "出访", "is_correct": false, "explanation": "chū fǎng（出访）与 chǔ fá 两个音节的声调都不同，第二音节多了韵尾 ng，意思是到外国访问。"}, {"text": "初犯", "is_correct": false, "explanation": "chū fàn（初犯）与 chǔ fá 两个音节的声调都不同，第二音节多了韵尾 n，意思是第一次犯错或犯罪。"}, {"text": "处方", "is_correct": false, "explanation": "chǔ fāng（处方）与 chǔ fá 第二音节声调不同且多了韵尾 ng，意思是医生开的药方。"}], "explanations": {"处罚": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。", "厨房": "chú fáng（厨房）与 chǔ fá 第一音节声调不同，第二音节多了韵尾 ng，意思是做饭的地方。", "出访": "chū fǎng（出访）与 chǔ fá 两个音节的声调都不同，第二音节多了韵尾 ng，意思是到外国访问。", "初犯": "chū fàn（初犯）与 chǔ fá 两个音节的声调都不同，第二音节多了韵尾 n，意思是第一次犯错或犯罪。", "处方": "chǔ fāng（处方）与 chǔ fá 第二音节声调不同且多了韵尾 ng，意思是医生开的药方。"}, "sentence_index": null, "correct_answer": "处罚"}, "level_3": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确：“处罚”指做错事后受到的惩罚，与“不怕”的语境相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：没有人会“怕”蛋糕，与句意不符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”不是令人害怕的事物，“不怕食物，还是继续迟到”句意不通。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”不是令人害怕的事物，与“不怕”的语义不合。"}], "explanations": {"处罚": "正确：“处罚”指做错事后受到的惩罚，与“不怕”的语境相符。", "蛋糕": "语义：没有人会“怕”蛋糕，与句意不符。", "食物": "语义：“食物”不是令人害怕的事物，“不怕食物，还是继续迟到”句意不通。", "早餐": "语义：“早餐”不是令人害怕的事物，与“不怕”的语义不合。"}, "sentence_index": 6, "correct_answer": "处罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次学习有很大的处罚。", "explanation": "这里应该用〈收获〉。“收获”指好的成果，“处罚”是负面的制裁，不能用来描述学习的成果。"}, {"text": "他获得了很多处罚。", "explanation": "这里应该用〈奖金〉。“获得”多用于奖金、荣誉等好的结果，受罚应说“受到处罚”。"}, {"text": "老师给了他一只处罚。", "explanation": "这里应该用〈项〉（一项处罚）。“只”是动物的量词，处罚的量词应是“项”或“次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他受到很重处罚。", "corrected_sentence": "他受到很重的处罚。", "error_description": "错误：“很重”修饰名词“处罚”时须加“的”，应说“受到很重的处罚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校给了他一头处罚。", "corrected_sentence": "学校给了他一次处罚。", "error_description": "错误：量词“头”用于大型牲畜，处罚应用“次”。正确应为“学校给了他一次处罚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
