INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "北美地区是美国、加拿大这些国家所在的地方。", "primary_collocate": null, "pronunciation": "běi měi dì qū", "ipa": "pei˨˩˦ mei˨˩˦ ti˥˩ tɕʰy˥", "syllable_count": 4, "sentences": [{"text": "北美地区北部的冬天很长。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友大多住在北美地区。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区有很多大湖和高山。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果在北美地区很常见。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区的人喜欢开车上班。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备明年去北美地区旅行。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北美地区，足球没有篮球受欢迎。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日在北美地区很重要。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区的农场又大又多。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了北美地区的历史。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北美地區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "美国、加拿大等国家所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f2a7402-8426-418d-9154-8fbf1758617b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "北美地区", "is_correct": true, "explanation": "北美地区北部纬度较高，冬季漫长，“北美地区北部的冬天很长”句意相符。"}, {"text": "赤道地区", "is_correct": false, "explanation": "语义：赤道地区终年炎热，四季不分明，不会有“冬天很长”的气候。"}, {"text": "北美居民", "is_correct": false, "explanation": "语义：“居民”指人，不能说“北部的冬天很长”。"}, {"text": "北美语言", "is_correct": false, "explanation": "搭配：“语言”不能作气候描述的主语；“北部的冬天很长”描述的只能是地方或季节。"}], "explanations": {"北美地区": "北美地区北部纬度较高，冬季漫长，“北美地区北部的冬天很长”句意相符。", "赤道地区": "语义：赤道地区终年炎热，四季不分明，不会有“冬天很长”的气候。", "北美居民": "语义：“居民”指人，不能说“北部的冬天很长”。", "北美语言": "搭配：“语言”不能作气候描述的主语；“北部的冬天很长”描述的只能是地方或季节。"}, "sentence_index": 0, "correct_answer": "北美地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北美地区有五十个州。", "explanation": "这里应该用〈美国〉。“州”是国家内部的行政区划，北美地区包含多个国家，不能说它有五十个州。"}, {"text": "北美地区的首都是渥太华。", "explanation": "这里应该用〈加拿大〉。北美地区不是国家，没有首都，渥太华是加拿大的首都。"}, {"text": "他去过一条北美地区。", "explanation": "量词用错：“条”多用于河流、道路等细长事物，“北美地区”应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北美地区", "is_correct": true, "explanation": "“在北美地区”作地点状语，足球与篮球的受欢迎程度是该地区的情况，句意通顺。"}, {"text": "北美公民", "is_correct": false, "explanation": "语义：“公民”指人，不能作“在……”的地点，句意不通。"}, {"text": "北美作品", "is_correct": false, "explanation": "搭配：“在……”后应接地点，“作品”不能充当地点。"}, {"text": "北美天气", "is_correct": false, "explanation": "语义：“天气”是气象现象，不能作“在……”的场所，句意不通。"}], "explanations": {"北美地区": "“在北美地区”作地点状语，足球与篮球的受欢迎程度是该地区的情况，句意通顺。", "北美公民": "语义：“公民”指人，不能作“在……”的地点，句意不通。", "北美作品": "搭配：“在……”后应接地点，“作品”不能充当地点。", "北美天气": "语义：“天气”是气象现象，不能作“在……”的场所，句意不通。"}, "sentence_index": 6, "correct_answer": "北美地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在北美地区的市中心见面吧。", "explanation": "这里应该用〈纽约〉。北美地区是大范围的区域，没有市中心，见面要说具体的城市，比如纽约。"}, {"text": "他会说北美地区。", "explanation": "这里应该用〈英语〉。北美地区是地理区域，不是语言，“会说”后面要接语言名称。"}, {"text": "北美地区是我的好朋友，每周都来看我。", "explanation": "这里应该用〈他〉。北美地区是地理区域，不是人，不能做朋友，也不会来看我。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的同学大多北美地区工作。", "corrected_sentence": "我的同学大多在北美地区工作。", "error_description": "缺少介词：“北美地区”作处所要用“在”引出，应说“我的同学大多在北美地区工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个品牌到北美地区很有名。", "corrected_sentence": "这个品牌在北美地区很有名。", "error_description": "介词错误：表示“在某地很有名”的处所要用“在”。“到”表示动作的目的地，后面须接动词（如“到北美地区去”），这里没有动词，不能直接作“很有名”的处所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
