INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外卖就是别人把做好的饭送到你家里。", "primary_collocate": null, "pronunciation": "wài mài", "ipa": "uai˥˩ mai˥˩", "syllable_count": 2, "sentences": [{"text": "我不想出门，今晚在家吃外卖。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外卖到了，快来吃饭吧。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用手机点了一份外卖。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作很忙，常常吃外卖。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家的外卖送得很快，二十分钟就到。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点外卖以前，先看看别人的评价。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给朋友叫了外卖，他很高兴。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪了，我们在家吃着外卖看电影。", "target_word": "外卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢吃中餐外卖，还是西餐外卖？", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末我想试试那家店的外卖。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "外卖员", "label": "复合"}, {"form": "外卖平台", "label": "复合"}], "register": "口语", "sense_fingerprint": "别人把做好的饭送到家里的饭菜或服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51fb9fe-8abb-41e1-afcc-9db367ee8af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外卖", "is_correct": true, "explanation": "外卖：别人做好送到家里的饭菜，符合“在家吃”的句意。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”是可以观看的作品，不能被“吃”，句意不通。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“饮料”应说“喝”，不能说“吃”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”不能被“吃”，句意不通。"}], "explanations": {"外卖": "外卖：别人做好送到家里的饭菜，符合“在家吃”的句意。", "电影": "语义：“电影”是可以观看的作品，不能被“吃”，句意不通。", "饮料": "搭配：“饮料”应说“喝”，不能说“吃”。", "音乐": "语义：“音乐”不能被“吃”，句意不通。"}, "sentence_index": 0, "correct_answer": "外卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去外卖聊天，很开心。", "explanation": "这里应该用〈咖啡馆〉。外卖不是可以聊天的地方，它指送到家的饭菜。"}, {"text": "妈妈给我叫了一只外卖，很香。", "explanation": "这里应该用〈份〉。外卖按份计数，〈只〉用于动物或成对的东西。"}, {"text": "我在网上买的鞋子，外卖明天就能到。", "explanation": "这里应该用〈快递〉。快递指寄来的包裹，外卖只指送到家的饭菜，不能指鞋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外卖", "is_correct": true, "explanation": "外卖：送到家的饭菜，是“叫”的对象，句意通顺。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“叫”不能带“闹钟”作宾语，闹钟应说“响”或“定”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”应说“布置”或“做”，不能说“叫”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”无法被“叫”，句意不通。"}], "explanations": {"外卖": "外卖：送到家的饭菜，是“叫”的对象，句意通顺。", "闹钟": "搭配：“叫”不能带“闹钟”作宾语，闹钟应说“响”或“定”。", "作业": "搭配：“作业”应说“布置”或“做”，不能说“叫”。", "雨": "语义：“雨”无法被“叫”，句意不通。"}, "sentence_index": 6, "correct_answer": "外卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本外卖教我怎么写毛笔字。", "explanation": "这里应该用〈字帖〉。外卖指送到家的饭菜或服务，不是教人写字的书。"}, {"text": "我们班来了一位新外卖，很年轻。", "explanation": "这里应该用〈同学〉。外卖不指人，送餐的人应说〈外卖员〉。"}, {"text": "这部外卖我看了两遍。", "explanation": "这里应该用〈电影〉。外卖指送到家的饭菜或服务，不是可以观看的影片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今晚点了一辆外卖。", "corrected_sentence": "我今晚点了一份外卖。", "error_description": "量词错误：“外卖”按份计数，应说“一份外卖”，“辆”只用于车辆，不能说“一辆外卖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候过吃外卖，觉得很新鲜。", "corrected_sentence": "我小时候吃过外卖，觉得很新鲜。", "error_description": "“过”位置错误：经历体“过”应紧跟动词之后，说“吃过外卖”，不能放在动词之前说“过吃外卖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
