INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做一件事，看看它行不行。", "primary_collocate": null, "pronunciation": "shì yàn", "ipa": "ʂɻ̩˥˩ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们先在一个班试验这种新方法。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法行不行，我想先试验一下。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司打算先在上海试验新的送货方式。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把新做法试验了几次，发现很有用。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民正在试验一种新的种菜方法。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家先别急着买，让我来试验一下。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校试验过新的上课时间，学生都很喜欢。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想试验一下，小组学习是不是更有效。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂试验了三种材料，最后选了最便宜的。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的厨师想在店里试验几种新菜。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "试验了", "label": "体标"}, {"form": "试验过", "label": "体标"}, {"form": "試驗", "label": "繁体"}], "register": "通用", "sense_fingerprint": "动手先做一做，看方法或东西行不行（动词：试验一下）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验（shì yàn）：动手做一做，看方法或东西行不行，是正确答案。"}, {"text": "式样", "is_correct": false, "explanation": "式样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是款式、样子。"}, {"text": "食盐", "is_correct": false, "explanation": "食盐（shí yán）两个音节的声调都与试验不同，意思是吃的盐。"}, {"text": "誓言", "is_correct": false, "explanation": "誓言（shì yán）第二个音节为第二声，与试验的 yàn（第四声）声调不同，意思是发誓的话。"}, {"text": "失言", "is_correct": false, "explanation": "失言（shī yán）两个音节的声调都与试验不同，意思是说错了话。"}, {"text": "试演", "is_correct": false, "explanation": "试演（shì yǎn）第二个音节 yǎn（第三声）与试验的 yàn（第四声）声调不同，意思是试着表演。"}], "explanations": {"试验": "试验（shì yàn）：动手做一做，看方法或东西行不行，是正确答案。", "式样": "式样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是款式、样子。", "食盐": "食盐（shí yán）两个音节的声调都与试验不同，意思是吃的盐。", "誓言": "誓言（shì yán）第二个音节为第二声，与试验的 yàn（第四声）声调不同，意思是发誓的话。", "失言": "失言（shī yán）两个音节的声调都与试验不同，意思是说错了话。", "试演": "试演（shì yǎn）第二个音节 yǎn（第三声）与试验的 yàn（第四声）声调不同，意思是试着表演。"}, "sentence_index": null, "correct_answer": "试验"}, "level_3": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验：动词，动手做一做看效果，与“这种新方法”搭配，句意正确。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，不能带“这种新方法”作宾语。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“新方法”不搭，句子的意思不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”与“新方法”不搭，句子的意思不通。"}], "explanations": {"试验": "试验：动词，动手做一做看效果，与“这种新方法”搭配，句意正确。", "出生": "配价：“出生”是不及物动词，不能带“这种新方法”作宾语。", "睡觉": "语义：“睡觉”与“新方法”不搭，句子的意思不通。", "咳嗽": "语义：“咳嗽”与“新方法”不搭，句子的意思不通。"}, "sentence_index": 0, "correct_answer": "试验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "专家每年都要试验学校的教学质量。", "explanation": "这里应该用〈评估〉。试验是动手做一做看行不行，全面评定学校质量要说“评估”。"}, {"text": "医生每天试验病人的心情，让他放心。", "explanation": "这里应该用〈安慰〉。试验是动手做一做看行不行，安抚病人的心情要说“安慰”。"}, {"text": "他每天试验学生的出勤情况，记在本子上。", "explanation": "这里应该用〈统计〉。试验是动手做一做看行不行，记录学生的出勤数字要说“统计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26048, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验（shì yàn）：动手做一做，看方法或东西行不行，是正确答案。"}, {"text": "食言", "is_correct": false, "explanation": "食言（shí yán）两个音节的声调都与试验不同，意思是不守诺言。"}, {"text": "试样", "is_correct": false, "explanation": "试样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是用来检测的样品。"}, {"text": "誓言", "is_correct": false, "explanation": "誓言（shì yán）第二个音节为第二声，与试验的 yàn（第四声）声调不同，意思是发誓的话。"}, {"text": "时延", "is_correct": false, "explanation": "时延（shí yán）两个音节的声调都与试验不同，意思是时间上的延迟。"}], "explanations": {"试验": "试验（shì yàn）：动手做一做，看方法或东西行不行，是正确答案。", "食言": "食言（shí yán）两个音节的声调都与试验不同，意思是不守诺言。", "试样": "试样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是用来检测的样品。", "誓言": "誓言（shì yán）第二个音节为第二声，与试验的 yàn（第四声）声调不同，意思是发誓的话。", "时延": "时延（shí yán）两个音节的声调都与试验不同，意思是时间上的延迟。"}, "sentence_index": null, "correct_answer": "试验"}, "level_3": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验：动词，表示尝试过一次，与“过”搭配，句意正确。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“新的上课时间”作宾语。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”不能施加于“新的上课时间”，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“新的上课时间”作宾语。"}], "explanations": {"试验": "试验：动词，表示尝试过一次，与“过”搭配，句意正确。", "哭": "配价：“哭”是不及物动词，不能带“新的上课时间”作宾语。", "游泳": "语义：“游泳”不能施加于“新的上课时间”，句意不通。", "散步": "配价：“散步”是不及物动词，不能带“新的上课时间”作宾语。"}, "sentence_index": 6, "correct_answer": "试验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工会每月都试验工厂的安全生产。", "explanation": "这里应该用〈监督〉。试验是动手做一做看行不行，对安全生产的日常督促要用“监督”。"}, {"text": "专家试验了这幅画，说它值一万元。", "explanation": "这里应该用〈估价〉。试验是动手做一做看行不行，给画定价要说“估价”。"}, {"text": "游客在博物馆里试验名画。", "explanation": "这里应该用〈欣赏〉。试验是动手做一做看行不行，观看名画要说“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这种新方法试验着一遍。", "corrected_sentence": "他把这种新方法试验了一遍。", "error_description": "“着”表示持续的状态，不能与“一遍”这种已完成的动作次数搭配。应说“试验了一遍”，不能说“试验着一遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐把新的烤法试验着两次。", "corrected_sentence": "姐姐把新的烤法试验了两次。", "error_description": "“着”表示持续的状态，不能与表示已完成次数的“两次”搭配。应说“试验了两次”，不能说“试验着两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26052, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
