INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方正式订立约定、条约或关系。", "primary_collocate": null, "pronunciation": "dì jié", "ipa": "ti˥˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "两个国家缔结了约定，一起保护这片海。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国在边境会谈后缔结了盟约，共同维护和平。", "target_word": "缔结", "complexity_tier": "T3", "furigana": "dì jié", "sentence_source": "generated"}, {"text": "两个村子缔结盟约，决定一起修这条路。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，两个部落缔结了和平的约定。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国领导人缔结了友好协定，承诺长期互不侵犯。", "target_word": "缔结", "complexity_tier": "T3", "furigana": "dì jié", "sentence_source": "generated"}, {"text": "为了保护森林，三个国家缔结了共同的协议。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司缔结合作协议，说好一起做新玩具。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王和邻国缔结条约，答应不再打仗。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两座城市缔结了友好关系，每年互派学生交流。", "target_word": "缔结", "complexity_tier": "T3", "furigana": "dì jié", "sentence_source": "generated"}, {"text": "两国在峰会上缔结了合作协定，决定共同开发资源。", "target_word": "缔结", "complexity_tier": "T3", "furigana": "dì jié", "sentence_source": "generated"}], "morphological_forms": [{"form": "缔结了", "label": "体标"}, {"form": "缔结过", "label": "体标"}, {"form": "締結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "双方说好一起做某事，订下约定（缔结约定、缔结友好关系）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缔结", "is_correct": true, "explanation": "正确：「缔结了约定」指两国说好共同行动，与「一起保护这片海」相符。"}, {"text": "打破", "is_correct": false, "explanation": "语义：打破约定与「一起保护这片海」的目的相反，句意自相矛盾。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：「拆」用于房屋、信件等，不能说拆约定。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，约定不能吃。"}], "explanations": {"缔结": "正确：「缔结了约定」指两国说好共同行动，与「一起保护这片海」相符。", "打破": "语义：打破约定与「一起保护这片海」的目的相反，句意自相矛盾。", "拆": "搭配：「拆」用于房屋、信件等，不能说拆约定。", "吃": "搭配：「吃」的对象是食物，约定不能吃。"}, "sentence_index": 0, "correct_answer": "缔结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他缔结了老师的要求。", "explanation": "这里应该用〈答应〉。缔结的对象是约定、协议，接受别人的要求要用答应。"}, {"text": "我在夏令营缔结了很多新朋友。", "explanation": "这里应该用〈结识〉。缔结用于订立约定或协议，认识新朋友要用结识。"}, {"text": "学校缔结了一场运动会。", "explanation": "这里应该用〈举办〉。缔结指订立约定，运动会是活动，应说举办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缔结", "is_correct": true, "explanation": "正确：「缔结合作协议」指双方订立协议，与「说好一起做」相符。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁合作协议与后句「说好一起做新玩具」相矛盾。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：「购买」的对象是商品，不能说购买协议。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：「弹」用于乐器，协议不能弹。"}], "explanations": {"缔结": "正确：「缔结合作协议」指双方订立协议，与「说好一起做」相符。", "撕毁": "语义：撕毁合作协议与后句「说好一起做新玩具」相矛盾。", "购买": "搭配：「购买」的对象是商品，不能说购买协议。", "弹": "搭配：「弹」用于乐器，协议不能弹。"}, "sentence_index": 6, "correct_answer": "缔结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们缔结了一顿晚餐。", "explanation": "这里应该用〈准备〉。缔结用于订立约定、协议，做饭要用准备。"}, {"text": "我们缔结了一次深入的讨论。", "explanation": "这里应该用〈进行〉。缔结指订立约定或协议，讨论不是约定，应说进行讨论。"}, {"text": "她缔结了一首歌。", "explanation": "这里应该用〈写〉。缔结用于订立约定，创作歌曲要用写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个村子缔结了一只约定，每年一起修路。", "corrected_sentence": "两个村子缔结了一项约定，每年一起修路。", "error_description": "量词错误：「只」用于动物或成对的器物，不能修饰「约定」；应说「一项约定」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两家公司把合作协议缔结，决定一起做新玩具。", "corrected_sentence": "两家公司把合作协议缔结了，决定一起做新玩具。", "error_description": "错误形式：把合作协议缔结。正确形式：把合作协议缔结了。「把」字句的动词后需要有其他成分（如「了」），单独的「缔结」不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
