INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "管住人或事的能力。", "primary_collocate": null, "pronunciation": "yuē shù lì", "ipa": "ɥɛ˧˥ ʂu˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "这条规定对所有人都有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话对他没有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们签的合同有约束力吗？", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班规的约束力很大。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母对长大的孩子约束力变小了。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只写在纸上的规则没有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的约定也有一定的约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校规对新生很有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛规则对每个队员都有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份承诺书对他有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约束", "label": "词根（动词）"}], "register": "中性", "sense_fingerprint": "能管住人或事的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d2bbf4-79da-4014-b207-c5baecb20bf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约束力", "is_correct": true, "explanation": "语境正确：“有约束力”指规定能管住人，与“这条规定对所有人都有”相合。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：“食欲”指想吃东西的欲望，规定不能对所有人产生食欲，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有”后接“颜色”指事物的色彩，规定的作用不能说“有颜色”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与规定的作用无关，句子不通。"}], "explanations": {"约束力": "语境正确：“有约束力”指规定能管住人，与“这条规定对所有人都有”相合。", "食欲": "语义：“食欲”指想吃东西的欲望，规定不能对所有人产生食欲，句子不通。", "颜色": "搭配：“有”后接“颜色”指事物的色彩，规定的作用不能说“有颜色”。", "体温": "语义：“体温”指身体的温度，与规定的作用无关，句子不通。"}, "sentence_index": 0, "correct_answer": "约束力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种地雷的约束力很大。", "explanation": "这里应该用〈杀伤力〉。约束力指限制人或事的能力，形容武器的毁伤作用要用“杀伤力”。"}, {"text": "这笔钱的约束力下降了。", "explanation": "这里应该用〈购买力〉。约束力不用于货币，说钱能买到东西的能力要用“购买力”。"}, {"text": "这门大炮的约束力很猛。", "explanation": "这里应该用〈火力〉。约束力只指限制作用，形容武器的攻击能力要用“火力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约束力", "is_correct": true, "explanation": "语境正确：“有一定的约束力”指约定能管住人的行为，与“朋友之间的约定”相合。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“香味”是嗅觉对象，约定没有香味，句子不通。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指三维空间的大小，不能用来说约定的作用。"}, {"text": "光泽", "is_correct": false, "explanation": "搭配：“光泽”用于物体表面，约定不能说“有光泽”。"}], "explanations": {"约束力": "语境正确：“有一定的约束力”指约定能管住人的行为，与“朋友之间的约定”相合。", "香味": "语义：“香味”是嗅觉对象，约定没有香味，句子不通。", "体积": "语义：“体积”指三维空间的大小，不能用来说约定的作用。", "光泽": "搭配：“光泽”用于物体表面，约定不能说“有光泽”。"}, "sentence_index": 6, "correct_answer": "约束力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的约束力很强。", "explanation": "这里应该用〈感染力〉。约束力指限制作用，形容歌曲打动人心的力量要用“感染力”。"}, {"text": "这位设计师的约束力很强。", "explanation": "这里应该用〈创造力〉。约束力指限制作用，形容设计师的创作能力要用“创造力”。"}, {"text": "这个景点很有约束力。", "explanation": "这里应该用〈吸引力〉。约束力指限制作用，形容景点吸引游客要用“吸引力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份公约对成员有一个约束力。", "corrected_sentence": "这份公约对成员有一定的约束力。", "error_description": "错误：“约束力”前用了个体量词“一个”。“约束力”是抽象名词，应说“一定的约束力”或“一种约束力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套纪律对全体队员都是约束力。", "corrected_sentence": "这套纪律对全体队员都有约束力。", "error_description": "错误：“约束力”前用了“是”。“具有、拥有”的意思要用“有”，应说“有约束力”，不能说“是约束力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
