INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几个人商量好、大家一起照着做的约定。", "primary_collocate": null, "pronunciation": "xié yì", "ipa": "ɕjɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我们三人订立了一项协议：谁迟到，谁请客。", "target_word": "协议", "complexity_tier": "T3", "furigana": "wǒmen sān rén dìnglì le yí xiàng xiéyì: shéi chídào, shéi qǐngkè", "sentence_source": "generated"}, {"text": "几个朋友订立了协议：每天早上一起跑步。", "target_word": "协议", "complexity_tier": "T3", "furigana": "jǐ gè péngyou dìnglì le xiéyì: měitiān zǎoshang yìqǐ pǎobù", "sentence_source": "generated"}, {"text": "孩子们有个小协议，不告诉老师。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和妹妹有协议，轮流洗碗。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家事先订立了协议，下午六点在门口见。", "target_word": "协议", "complexity_tier": "T3", "furigana": "dàjiā shìxiān dìnglì le xiéyì, xiàwǔ liù diǎn zài ménkǒu jiàn", "sentence_source": "generated"}, {"text": "他忘了我们的协议，没有来。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的协议是谁先到，谁买水。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们几个人的小协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家有个协议：吃饭时不看手机。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们事先订立了协议：考试前不熬夜。", "target_word": "协议", "complexity_tier": "T3", "furigana": "tóngxuémen shìxiān dìnglì le xiéyì: kǎoshì qián bú áoyè", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "協議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几个人私下商量好、大家一起照着做的约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "协议（xié yì，第二声、第四声）指几个人私下商量好、大家一起照做的约定，是正确答案。"}, {"text": "谢意", "is_correct": false, "explanation": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢。"}, {"text": "写意", "is_correct": false, "explanation": "写意（xiě yì）的第一个音节是第三声，与 xié（第二声）声调不同，意思是轻松舒适，或国画中不求细致的画法。"}, {"text": "洗衣", "is_correct": false, "explanation": "洗衣（xǐ yī）两个音节的声调都与协议（xié yì）不同，意思是洗衣服。"}, {"text": "西医", "is_correct": false, "explanation": "西医（xī yī）两个音节的声调都与协议（xié yì）不同，意思是西方医学。"}], "explanations": {"协议": "协议（xié yì，第二声、第四声）指几个人私下商量好、大家一起照做的约定，是正确答案。", "谢意": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢。", "写意": "写意（xiě yì）的第一个音节是第三声，与 xié（第二声）声调不同，意思是轻松舒适，或国画中不求细致的画法。", "洗衣": "洗衣（xǐ yī）两个音节的声调都与协议（xié yì）不同，意思是洗衣服。", "西医": "西医（xī yī）两个音节的声调都与协议（xié yì）不同，意思是西方医学。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "“订立了一项协议”指几个人商量好的约定，“谁迟到，谁请客”正是约定内容，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能被订立，“订立了一项天气”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是约定，“谁迟到，谁请客”不能作为价格的内容。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位与“谁迟到，谁请客”无关，不能作为订立的约定内容。"}], "explanations": {"协议": "“订立了一项协议”指几个人商量好的约定，“谁迟到，谁请客”正是约定内容，符合句意。", "天气": "搭配：“天气”不能被订立，“订立了一项天气”说不通。", "价格": "语义：价格不是约定，“谁迟到，谁请客”不能作为价格的内容。", "座位": "语义：座位与“谁迟到，谁请客”无关，不能作为订立的约定内容。"}, "sentence_index": 0, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩很有协议，一个眼神就知道对方的想法。", "explanation": "这里应该用〈默契〉。协议要事先商量明确，不能用来形容心照不宣的配合。"}, {"text": "早上跑步已经成了我的协议。", "explanation": "这里应该用〈习惯〉。协议是几个人事先商量好的约定，自己长期养成的做法用习惯。"}, {"text": "我把这周的协议写在了日记本上。", "explanation": "这里应该用〈计划〉。协议需要几个人一起商量好，自己一个人定的安排用计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "“我们的协议是谁先到，谁买水”说明的是大家商量好的约定，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是约定，“名字是谁先到，谁买水”无法成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能表示“谁先到，谁买水”的约定。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是要喝的东西，不能说“饮料是谁先到，谁买水”。"}], "explanations": {"协议": "“我们的协议是谁先到，谁买水”说明的是大家商量好的约定，符合句意。", "名字": "语义：名字不是约定，“名字是谁先到，谁买水”无法成立。", "作业": "语义：作业是学习任务，不能表示“谁先到，谁买水”的约定。", "饮料": "语义：饮料是要喝的东西，不能说“饮料是谁先到，谁买水”。"}, "sentence_index": 6, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对妈妈许下了协议，每天写作业。", "explanation": "这里应该用〈承诺〉。承诺是一方对另一方的保证，协议要几个人一起商量好。"}, {"text": "老师给我们布置了协议：背十首古诗。", "explanation": "这里应该用〈任务〉。协议要几个人商量好，老师单方面布置的要求用任务。"}, {"text": "我们班的协议唱起来很好听。", "explanation": "这里应该用〈班歌〉。协议是几个人商量好要遵守的约定，不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们三人订好了一协议。", "corrected_sentence": "我们三人订好了一项协议。", "error_description": "量词缺失：数词“一”和名词“协议”之间要用量词，应说“一项协议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前订了过协议。", "corrected_sentence": "我们以前订过协议。", "error_description": "“了”和“过”不能同时用在同一动词后。表示曾经做过要用“过”，应说“订过协议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群人为商量事情、做决定而组成的团体。", "primary_collocate": null, "pronunciation": "wěi yuán huì", "ipa": "weɪ²¹⁴ ɥɛn³⁵ xweɪ⁵¹", "syllable_count": 3, "sentences": [{"text": "她加入了委员会，负责决定班级的活动。", "target_word": "委员会", "complexity_tier": "T3", "furigana": "tā jiā rù le wěi yuán huì fù zé jué dìng bān jí de huó dòng", "sentence_source": "generated"}, {"text": "她每个星期五都去委员会开会。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会的人正在商量明天的活动。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区成立了一个委员会，管理公共花园。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想参加委员会的会议，看看大家怎么做决定。", "target_word": "委员会", "complexity_tier": "T3", "furigana": "tā xiǎng cān jiā wěi yuán huì de huì yì kànkan dà jiā zěnme zuò jué dìng", "sentence_source": "generated"}, {"text": "委员会里有七个人，大家一起做决定。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我们要问一下委员会。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会决定下周六打扫公园。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去过那个委员会的办公室吗？", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们在委员会讨论停车的问题。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个委员会", "label": "量词（个）"}, {"form": "学生委员会", "label": "复合词"}, {"form": "委員會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为商量事情、做决定而组成的一群人（团体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "委员会", "is_correct": true, "explanation": "“加入”的对象应是团体，且“负责决定班级的活动”说明它是一群人做决定的团体，“委员会”符合语境。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不能负责决定班级的活动。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋是食物，不具备决定活动的能力。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“加入”后接的应是团体，“课本”不能被加入，二者不搭。"}], "explanations": {"委员会": "“加入”的对象应是团体，且“负责决定班级的活动”说明它是一群人做决定的团体，“委员会”符合语境。", "公园": "语义：公园是场所，不能负责决定班级的活动。", "冰淇淋": "语义：冰淇淋是食物，不具备决定活动的能力。", "课本": "搭配：“加入”后接的应是团体，“课本”不能被加入，二者不搭。"}, "sentence_index": 0, "correct_answer": "委员会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是我们班的委员会，负责管理图书角。", "explanation": "这里应该用〈委员〉。委员会指一群人组成的集体，一个人应说“委员”。"}, {"text": "我把委员会借给了同桌。", "explanation": "这里应该用〈课本〉。委员会是一群人组成的团体，不是物品，不能借给别人。"}, {"text": "这块委员会很好吃。", "explanation": "这里应该用〈蛋糕〉。委员会是为商量事情、做决定而组成的团体，不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "委员会", "is_correct": true, "explanation": "“问一下”后接的对象应是能给出意见、做决定的集体或人，“委员会”符合语境。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不能被询问，也无法给出解答。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物体，无法就问题作答。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“问”的对象应是人或机构，“电影”不能用“问一下”。"}], "explanations": {"委员会": "“问一下”后接的对象应是能给出意见、做决定的集体或人，“委员会”符合语境。", "西瓜": "语义：西瓜是水果，不能被询问，也无法给出解答。", "窗户": "语义：窗户是物体，无法就问题作答。", "电影": "搭配：“问”的对象应是人或机构，“电影”不能用“问一下”。"}, "sentence_index": 6, "correct_answer": "委员会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "邻居们给委员会浇了水，讨论停车的问题。", "explanation": "这里应该用〈花草〉。委员会是一群人商量事情、做决定的团体，不是植物，不能浇水；浇水的对象应是〈花草〉。"}, {"text": "妈妈把委员会放进了冰箱。", "explanation": "委员会是团体，不是物品，不能放进冰箱；这里应说〈饭菜〉。"}, {"text": "我们的委员会今天生病了，请了假。", "explanation": "委员会是团体，不会生病；把它当成人来说是误用，应说〈某位成员〉生病了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只委员会每个月都要开一次会。", "corrected_sentence": "这个委员会每个月都要开一次会。", "error_description": "量词错误：“委员会”是组织，量词应用“个”，“只”只用于动物；应说“这个委员会”，不能说“这只委员会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每个星期五都委员会开会。", "corrected_sentence": "我每个星期五都在委员会开会。", "error_description": "介词漏用：表示地点时，“在”必须放在处所词前，应说“在委员会开会”，不能说“委员会开会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "助长", "is_correct": true, "explanation": "“助长”与“遏制”意义相反：遏制是阻止坏事继续发生，助长是促使其发展。"}, {"text": "完成", "is_correct": false, "explanation": "与“遏制”没有反义关系，“完成”表示做好一件事，与阻止、促进都不相关。"}, {"text": "开始", "is_correct": false, "explanation": "与“遏制”没有反义关系，“开始”表示起步，并不是促使坏事发展。"}, {"text": "接受", "is_correct": false, "explanation": "与“遏制”没有反义关系，“接受”表示同意或承认，与阻止、促进都无关。"}], "correct_answer": "助长", "explanations": {"助长": "“助长”与“遏制”意义相反：遏制是阻止坏事继续发生，助长是促使其发展。", "完成": "与“遏制”没有反义关系，“完成”表示做好一件事，与阻止、促进都不相关。", "开始": "与“遏制”没有反义关系，“开始”表示起步，并不是促使坏事发展。", "接受": "与“遏制”没有反义关系，“接受”表示同意或承认，与阻止、促进都无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "助长", "is_correct": true, "explanation": "“助长”与“遏制”意义相反：遏制是阻止不良势头，助长是促使其发展。"}, {"text": "完善", "is_correct": false, "explanation": "与“遏制”没有反义关系，“完善”表示使事物更加完美，与阻止、促进坏事都无关。"}, {"text": "观察", "is_correct": false, "explanation": "与“遏制”没有反义关系，“观察”表示仔细看，与阻止或促进都不相关。"}, {"text": "讨论", "is_correct": false, "explanation": "与“遏制”没有反义关系，“讨论”表示交换意见，与阻止、促进都无关。"}], "correct_answer": "助长", "explanations": {"助长": "“助长”与“遏制”意义相反：遏制是阻止不良势头，助长是促使其发展。", "完善": "与“遏制”没有反义关系，“完善”表示使事物更加完美，与阻止、促进坏事都无关。", "观察": "与“遏制”没有反义关系，“观察”表示仔细看，与阻止或促进都不相关。", "讨论": "与“遏制”没有反义关系，“讨论”表示交换意见，与阻止、促进都无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让坏事继续发生", "primary_collocate": null, "pronunciation": "è zhì", "ipa": "ɤ˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我们必须尽快遏制森林大火蔓延。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师及时遏制了班里的打闹。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有早点儿遏制，小问题才不会变大。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察努力遏制犯罪继续增加。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能遏制细菌继续生长。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里修了堤坝来遏制洪水。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长要遏制孩子玩手机的坏习惯。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想遏制病情继续恶化，但没有成功。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司出台规定，遏制浪费现象。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，遏制谣言继续传播。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遏制了", "label": "完成体"}, {"form": "遏制过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "使不好的事情不再继续发生或扩大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励森林大火蔓延”与前文“尽快”的要求相反，读起来不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎森林大火蔓延”与灭火的意图完全相反。"}, {"text": "遏制", "is_correct": true, "explanation": "“遏制”表示不让坏事继续发生，与“尽快”和“大火蔓延”搭配，符合句意。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”的对象是损坏的东西，不能接“蔓延”。"}], "explanations": {"鼓励": "语义：“鼓励森林大火蔓延”与前文“尽快”的要求相反，读起来不通。", "欢迎": "语义：“欢迎森林大火蔓延”与灭火的意图完全相反。", "遏制": "“遏制”表示不让坏事继续发生，与“尽快”和“大火蔓延”搭配，符合句意。", "修复": "搭配：“修复”的对象是损坏的东西，不能接“蔓延”。"}, "sentence_index": 0, "correct_answer": "遏制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想遏制那辆自行车。", "explanation": "搭配：“遏制”的对象是行为或趋势，不能用于自行车这样的物体；这里应该用“骑”。"}, {"text": "为了遏制生病，我每天吃水果。", "explanation": "近义词混用：“防止”指事情还没发生时预先阻止，“遏制”用于已经蔓延的坏势头；这里应该用“防止”。"}, {"text": "我每天早上遏制一杯牛奶。", "explanation": "搭配：“遏制”的对象是不良的趋势或现象，不能用于一杯牛奶；这里应该用“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培养", "is_correct": false, "explanation": "语义：“培养孩子玩手机的坏习惯”与家长纠正坏习惯的意图相反。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励孩子玩手机的坏习惯”会鼓励坏习惯，与句意相反。"}, {"text": "遏制", "is_correct": true, "explanation": "“遏制”表示不让坏习惯继续发展，与“坏习惯”搭配，符合家长的意图。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的宾语是物品或方法，不能接“坏习惯”。"}], "explanations": {"培养": "语义：“培养孩子玩手机的坏习惯”与家长纠正坏习惯的意图相反。", "奖励": "语义：“奖励孩子玩手机的坏习惯”会鼓励坏习惯，与句意相反。", "遏制": "“遏制”表示不让坏习惯继续发展，与“坏习惯”搭配，符合家长的意图。", "发明": "搭配：“发明”的宾语是物品或方法，不能接“坏习惯”。"}, "sentence_index": 6, "correct_answer": "遏制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要遏制夏天的来临。", "explanation": "搭配：“遏制”的对象是可以控制的不良现象，夏天来临不能被遏制。"}, {"text": "他遏制了那把椅子。", "explanation": "搭配：“遏制”的对象是行为或趋势，不能用于椅子这样的物体；这里应该用“搬”。"}, {"text": "妈妈遏制了一顿丰盛的晚饭。", "explanation": "搭配：“遏制”的对象是不良的趋势或现象，不能用于晚饭；这里应该用“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要尽快遏制了疫情扩散。", "corrected_sentence": "我们要尽快遏制疫情扩散。", "error_description": "错误形式：“遏制”后面加了“了”。正确形式：应说“我们要尽快遏制疫情扩散。”原因：“要尽快”表示将来的意愿，“了”表示已经完成，二者矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些规定能很遏制浪费现象。", "corrected_sentence": "这些规定能遏制浪费现象。", "error_description": "错误形式：“遏制”前面加了副词“很”。正确形式：应说“这些规定能遏制浪费现象。”原因：“很”一般修饰形容词，不能修饰动作动词“遏制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
