INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26078, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个国家到另一个国家。", "primary_collocate": null, "pronunciation": "kuà jìng", "ipa": "kʰwa˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "很多工人每天跨境上班。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期跨境去买东西。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很窄，人们常常跨境走亲戚。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆货车要跨境送货。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生每天跨境上学，路上要一个小时。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跨境回家过年。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们跨境看病，因为那边医院更好。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车跨境去旅游。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨境工作的人要办特别的证件。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物不知道国界，常常跨境走动。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨境上班", "label": "复合"}, {"form": "跨境旅游", "label": "复合"}], "register": "中性", "sense_fingerprint": "越过国境从一国去另一国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨境", "is_correct": true, "explanation": "“跨境”作动词，指越过国境去另一国，句中“每天跨境上班”正是此义。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：“罢工”指停止工作，与“上班”相互矛盾。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”不能作为“上班”的方式，两者不搭配。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公外出，不表示越过国境，句意不通。"}], "explanations": {"跨境": "“跨境”作动词，指越过国境去另一国，句中“每天跨境上班”正是此义。", "罢工": "语义：“罢工”指停止工作，与“上班”相互矛盾。", "跳舞": "搭配：“跳舞”不能作为“上班”的方式，两者不搭配。", "出差": "语义：“出差”指因公外出，不表示越过国境，句意不通。"}, "sentence_index": 0, "correct_answer": "跨境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条高速公路跨境了两个城市。", "explanation": "这里应该用〈穿过〉。“跨境”指越过国境从一国到另一国，城市之间的道路不涉及国境。"}, {"text": "他从上海出发，跨境南京，最后到达杭州。", "explanation": "这里应该用〈途经〉。“跨境”指越过国境从一国到另一国，南京在国内，不能用“跨境”。"}, {"text": "他跨境去了一次城里的超市。", "explanation": "这里应该用〈去〉。“跨境”指越过国境，城里的超市在同一国内，应说“去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨境", "is_correct": true, "explanation": "“跨境”作动词，指越过国境去另一国看病，句中因果关系正合此义。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与看病无关，句意不通。"}, {"text": "冲浪", "is_correct": false, "explanation": "语义：“冲浪”是海上运动，不能用来看病。"}, {"text": "午睡", "is_correct": false, "explanation": "搭配：“午睡”是休息动作，不能作为“看病”的方式。"}], "explanations": {"跨境": "“跨境”作动词，指越过国境去另一国看病，句中因果关系正合此义。", "唱歌": "语义：“唱歌”与看病无关，句意不通。", "冲浪": "语义：“冲浪”是海上运动，不能用来看病。", "午睡": "搭配：“午睡”是休息动作，不能作为“看病”的方式。"}, "sentence_index": 6, "correct_answer": "跨境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在河边跨境了那片草地，发现了鱼群。", "explanation": "这里应该用〈走过〉。跨境指越过国境，草地不涉及国境，应说“走过”。"}, {"text": "他跨境了那座小屋，找到了厨房。", "explanation": "这里应该用〈进〉。跨境指越过国境，进屋不涉及国境，应说“进”。"}, {"text": "这只猫跨境到了楼上。", "explanation": "这里应该用〈爬〉。“跨境”指越过国境，猫上楼不涉及国境，应说“爬上楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师每天跨境了去上课。", "corrected_sentence": "这位老师每天跨境去上课。", "error_description": "“了”位置错误：“跨境”作状语修饰动词“去”，“了”不能插在“跨境”与“去”之间，应为“跨境去上课”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈每个月跨境了去探望亲戚。", "corrected_sentence": "我妈妈每个月跨境去探望亲戚。", "error_description": "“了”位置错误：“跨境”后不能加“了”再接“去”，应为“跨境去探望亲戚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
