INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文书就是写在纸上的文件或信件。", "primary_collocate": null, "pronunciation": "wén shū", "ipa": "wən³⁵ ʂu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他把重要的文书放在抽屉里。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶留下了一份很旧的文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文书是用毛笔写的。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在桌子上找到一份文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文书上写着我们家的地址。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看文书，一边写笔记。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份文书寄给王先生。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文书丢了，我们得重新写一份。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们抄写一份文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过那份文书，没有说话。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份文书", "label": "量词（份）"}, {"form": "旧文书", "label": "形容词修饰"}, {"form": "文書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写在纸上的文件或信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文书", "is_correct": true, "explanation": "文书指写在纸上的文件或信件，可以放进抽屉，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车体积太大，放不进抽屉。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不可能放进抽屉里。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：形容词“重要的”通常修饰文件、证件等，不修饰饮料。"}], "explanations": {"文书": "文书指写在纸上的文件或信件，可以放进抽屉，与句意相符。", "汽车": "语义：汽车体积太大，放不进抽屉。", "大象": "语义：大象不可能放进抽屉里。", "饮料": "搭配：形容词“重要的”通常修饰文件、证件等，不修饰饮料。"}, "sentence_index": 0, "correct_answer": "文书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在晚会上唱了文书，大家都很喜欢。", "explanation": "这里应该用〈歌〉。唱的是歌曲，文书指写在纸上的文件或信件，不能用来唱。"}, {"text": "他花了一晚上煮了一份文书，香味很浓。", "explanation": "这里应该用〈汤〉。文书指写在纸上的文件或信件，不能用来煮。"}, {"text": "我在桌子上找到一只文书。", "explanation": "这里应该用〈份〉。文书是纸张，量词用“份”或“封”（信件），“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文书", "is_correct": true, "explanation": "文书指写在纸上的文件或信件，可以寄出，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能装进信封寄出。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是自然现象，不是可以寄出的物品。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：量词“份”一般搭配文件、礼物，不说“这份雨水”。"}], "explanations": {"文书": "文书指写在纸上的文件或信件，可以寄出，与句意相符。", "空气": "语义：空气看不见摸不着，不能装进信封寄出。", "闪电": "语义：闪电是自然现象，不是可以寄出的物品。", "雨水": "搭配：量词“份”一般搭配文件、礼物，不说“这份雨水”。"}, "sentence_index": 6, "correct_answer": "文书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天晚上写文书，记录当天的心情。", "explanation": "这里应该用〈日记〉。文书是写在纸上的文件或信件，多用于办事或传递信息，不用来记录个人心情。"}, {"text": "他在操场上踢文书，玩得很开心。", "explanation": "这里应该用〈足球〉。文书指写在纸上的文件或信件，不能用来踢。"}, {"text": "他这几年一直在写文书，讲一个小镇的故事。", "explanation": "这里应该用〈小说〉。文书指写在纸上的公务文件或信件，不是虚构的叙事作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只文书交给了律师。", "corrected_sentence": "他把那份文书交给了律师。", "error_description": "量词错误：“文书”是纸张，应用量词“份”，不用“只”（“只”用于动物等）。应说“那份文书”，不说“那只文书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些文书们都要寄给王先生。", "corrected_sentence": "这些文书都要寄给王先生。", "error_description": "复数错误：“文书”是事物名词，前面已有“这些”，不能再加“们”。应说“这些文书”，不说“这些文书们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
