INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26086, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个阶段慢慢变成另一个阶段。", "primary_collocate": null, "pronunciation": "guò dù", "ipa": "kwo˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "白天慢慢过渡到了夜晚。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的心情从难过过渡到平静。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天快结束了，天气慢慢过渡到冬天。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明从学生过渡到上班族，还不习惯。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝宝从喝奶过渡到吃饭，要一步一步来。", "target_word": "过渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济要平稳地过渡到新的发展方式。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的中间部分过渡得很自然。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从旧工作过渡到新工作，用了三个月。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校正在从线下教学过渡到线上教学。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天慢慢过渡到秋天，天气逐渐变凉。", "target_word": "过渡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过渡了", "label": "完成体"}, {"form": "过渡期", "label": "复合"}], "register": "中性", "sense_fingerprint": "由一种状态慢慢转变成另一种状态，中间没有明显断开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过渡", "is_correct": true, "explanation": "过渡：由一种状态慢慢变成另一种状态，正合“慢慢”和“到了夜晚”的渐变语境。"}, {"text": "降临", "is_correct": false, "explanation": "语义：“降临”指某事物来到，如夜幕降临，不能说白天本身“降临到”夜晚。"}, {"text": "抵达", "is_correct": false, "explanation": "搭配：“抵达”后接地点，不接时间段，“抵达到了夜晚”不合。"}, {"text": "变形", "is_correct": false, "explanation": "语义：“变形”指形体的改变，不用于时间段之间的转换。"}], "explanations": {"过渡": "过渡：由一种状态慢慢变成另一种状态，正合“慢慢”和“到了夜晚”的渐变语境。", "降临": "语义：“降临”指某事物来到，如夜幕降临，不能说白天本身“降临到”夜晚。", "抵达": "搭配：“抵达”后接地点，不接时间段，“抵达到了夜晚”不合。", "变形": "语义：“变形”指形体的改变，不用于时间段之间的转换。"}, "sentence_index": 0, "correct_answer": "过渡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书已过渡成英文。", "explanation": "这里应该用〈翻译〉。过渡指事物自身逐渐进入另一阶段，把书改写成另一种语言要说“翻译”。"}, {"text": "他的工资已过渡到五千元。", "explanation": "这里应该用〈提升〉。过渡指由一个阶段转入另一个阶段，工资数额的增加要说“提升”。"}, {"text": "他的成绩过渡了很多分。", "explanation": "这里应该用〈提高〉。过渡指由一个阶段转入另一个阶段，分数的增长要说“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过渡", "is_correct": true, "explanation": "过渡：由一个状态慢慢转入另一个状态，正合“得很自然”描述的衔接效果。"}, {"text": "争论", "is_correct": false, "explanation": "语义：“争论”的主体必须是人，歌曲的中间部分不能争论。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人的生理动作，与歌曲的衔接毫无关系。"}, {"text": "闲聊", "is_correct": false, "explanation": "语域：“闲聊”是口语，且主体须是人，与这句书面的乐评语体不协调。"}], "explanations": {"过渡": "过渡：由一个状态慢慢转入另一个状态，正合“得很自然”描述的衔接效果。", "争论": "语义：“争论”的主体必须是人，歌曲的中间部分不能争论。", "咳嗽": "语义：“咳嗽”是人的生理动作，与歌曲的衔接毫无关系。", "闲聊": "语域：“闲聊”是口语，且主体须是人，与这句书面的乐评语体不协调。"}, "sentence_index": 6, "correct_answer": "过渡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电话已经过渡到了客服那里。", "explanation": "这里应该用〈转接〉。过渡不用于电话被人转交的情况，过渡指事物自身逐渐进入另一阶段。"}, {"text": "这批文件已过渡到各个部门。", "explanation": "这里应该用〈派发〉。过渡指事物逐渐进入另一阶段，把文件分送各部门要说“派发”。"}, {"text": "气温过渡到了三十度。", "explanation": "这里应该用〈上涨〉。过渡强调由一种状态转入另一种状态，数值的上升不能说过渡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师的教学方法正在从传统模式过渡了到现代模式。", "corrected_sentence": "这位老师的教学方法正在从传统模式过渡到现代模式。", "error_description": "错误：“过渡”和“到”之间多了“了”。正确应为“过渡到”，“了”不能插在引出终点的“到”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的节奏正慢慢过渡着到新的阶段。", "corrected_sentence": "这个城市的节奏正慢慢过渡到新的阶段。", "error_description": "错误：“过渡”后多了“着”。正确应为“慢慢过渡到”，“着”不能插在“过渡”和“到”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏废", "is_correct": true, "explanation": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。"}, {"text": "思考", "is_correct": false, "explanation": "思考指动脑筋考虑问题，与“兼顾”不构成反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指把东西从一处移到另一处，与“兼顾”无关。"}, {"text": "寻找", "is_correct": false, "explanation": "寻找指设法找到某物，与“兼顾”无关。"}], "correct_answer": "偏废", "explanations": {"偏废": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。", "思考": "思考指动脑筋考虑问题，与“兼顾”不构成反义关系。", "搬运": "搬运指把东西从一处移到另一处，与“兼顾”无关。", "寻找": "寻找指设法找到某物，与“兼顾”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏废", "is_correct": true, "explanation": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买指用钱换取物品，与“兼顾”无关。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗指用水等去除污垢，与“兼顾”无关。"}, {"text": "批评", "is_correct": false, "explanation": "批评指指出缺点或错误，与“兼顾”无关。"}], "correct_answer": "偏废", "explanations": {"偏废": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。", "购买": "购买指用钱换取物品，与“兼顾”无关。", "清洗": "清洗指用水等去除污垢，与“兼顾”无关。", "批评": "批评指指出缺点或错误，与“兼顾”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同时照顾到两个方面。", "primary_collocate": null, "pronunciation": "jiān gù", "ipa": "tɕjɛn˥ ku˥˩", "syllable_count": 2, "sentences": [{"text": "他一边上班，一边读书，两头都兼顾。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的菜兼顾了味道和价格。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这款手机兼顾了拍照和续航。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈努力兼顾工作和家务。", "target_word": "兼顾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校想兼顾考试成绩和学生兴趣。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的计划兼顾了短期和长期目标。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要兼顾速度和安全，不能只想快。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种做法既兼顾了公平，又提高了效率。", "target_word": "兼顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想兼顾事业与爱情，但很难做到。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前，他也兼顾了学习和身体健康。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼顾了", "label": "完成体"}, {"form": "兼顾过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "同时顾及两件事或两个方面，不偏向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兼顾", "is_correct": true, "explanation": "兼顾指同时照顾两件事，与“两头都”的表达一致。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃其中一件事，与“一边上班，一边读书”的句意相反。"}, {"text": "偏向", "is_correct": false, "explanation": "配价：“偏向”只带一个偏向的对象，不能用于“两头都”。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略任何一头，都与“一边上班，一边读书”的句意相反。"}], "explanations": {"兼顾": "兼顾指同时照顾两件事，与“两头都”的表达一致。", "放弃": "语义：放弃其中一件事，与“一边上班，一边读书”的句意相反。", "偏向": "配价：“偏向”只带一个偏向的对象，不能用于“两头都”。", "忽略": "语义：忽略任何一头，都与“一边上班，一边读书”的句意相反。"}, "sentence_index": 0, "correct_answer": "兼顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司兼顾了另一家小公司，规模扩大了。", "explanation": "这里应该用〈兼并〉。兼并指把其他企业并入自己，兼顾指同时顾及几件事，不表示收购。"}, {"text": "他周末兼顾做家教，收入不错。", "explanation": "这里应该用〈兼职〉。兼职指在本职工作之外再做另一份工作，兼顾不能用来说做工作。"}, {"text": "她每天都在兼顾孩子，很辛苦。", "explanation": "这里应该用〈照顾〉。兼顾须同时顾及两件事，只照顾孩子一方时用“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兼顾", "is_correct": true, "explanation": "兼顾指同时顾及速度和安全，与“不能只想快”的句意相符。"}, {"text": "陪伴", "is_correct": false, "explanation": "配价：“陪伴”的对象一般是人，不能说“陪伴速度和安全”。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与“不能只想快”的句意相悖，也不符合同时顾及两方面的语境。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于庆祝成就或事件，不说“祝贺速度和安全”。"}], "explanations": {"兼顾": "兼顾指同时顾及速度和安全，与“不能只想快”的句意相符。", "陪伴": "配价：“陪伴”的对象一般是人，不能说“陪伴速度和安全”。", "反对": "语义：“反对”与“不能只想快”的句意相悖，也不符合同时顾及两方面的语境。", "祝贺": "搭配：“祝贺”用于庆祝成就或事件，不说“祝贺速度和安全”。"}, "sentence_index": 6, "correct_answer": "兼顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上兼顾电视剧，很放松。", "explanation": "这里应该用〈看〉。兼顾指同时顾及几方面，不用于说观看节目。"}, {"text": "这两根电线兼顾在一起，使用很方便。", "explanation": "这里应该用〈连接〉。兼顾指同时照顾几方面，不用于说物体连在一起。"}, {"text": "他每天都在兼顾老人，很辛苦。", "explanation": "这里应该用〈照料〉。兼顾须同时顾及两件事，只照料老人一方时用“照料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他工作和家务都很兼顾好了。", "corrected_sentence": "他工作和家务都兼顾好了。", "error_description": "副词错误：“很”不能修饰动作动词“兼顾”，应说“都兼顾好了”，不说“都很兼顾好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事的质量和进度我们都兼顾了过。", "corrected_sentence": "这件事的质量和进度我们都兼顾过了。", "error_description": "体标错误：“了”与“过”不能叠用，应说“兼顾过了”，不说“兼顾了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
