INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "科学技术，以及由此产生的新成果。", "primary_collocate": null, "pronunciation": "kē jì", "ipa": "kʰɤ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "现在的科技发展得很快。", "target_word": "科技", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司用新科技做手机。", "target_word": "科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技让我们的生活更方便。", "target_word": "科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家科技公司工作。", "target_word": "科技", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人也要学习新科技。", "target_word": "科技", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有了科技，我们可以在家上课。", "target_word": "科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们都喜欢这个科技博物馆。", "target_word": "科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技越来越发达，人们的工作也越来越轻松。", "target_word": "科技", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很关心国外的新科技，每天都看新闻。", "target_word": "科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市用科技管理交通，所以路上不太堵。", "target_word": "科技", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高科技", "label": "复合"}, {"form": "科技馆", "label": "复合"}], "register": "中性", "sense_fingerprint": "科学技术及其新成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科技", "is_correct": true, "explanation": "正确答案。科技（kē jì）指科学技术，也指让生活更方便的新东西。"}, {"text": "客机", "is_correct": false, "explanation": "客机（kè jī）两个音节的声调都与科技（kē jì）不同，意思是载客的飞机。"}, {"text": "科系", "is_correct": false, "explanation": "科系（kē xì）与科技第二个音节的声母不同（jì 与 xì），意思是学科或专业的分类。"}, {"text": "科级", "is_correct": false, "explanation": "科级（kē jí）与科技只有第二个音节的声调不同（jì 第四声，jí 第二声），意思是科长一级的职务。"}, {"text": "柯基", "is_correct": false, "explanation": "柯基（kē jī）与科技只有第二个音节的声调不同（jī 第一声），意思是柯基犬。"}], "explanations": {"科技": "正确答案。科技（kē jì）指科学技术，也指让生活更方便的新东西。", "客机": "客机（kè jī）两个音节的声调都与科技（kē jì）不同，意思是载客的飞机。", "科系": "科系（kē xì）与科技第二个音节的声母不同（jì 与 xì），意思是学科或专业的分类。", "科级": "科级（kē jí）与科技只有第二个音节的声调不同（jì 第四声，jí 第二声），意思是科长一级的职务。", "柯基": "柯基（kē jī）与科技只有第二个音节的声调不同（jī 第一声），意思是柯基犬。"}, "sentence_index": null, "correct_answer": "科技"}, "level_3": {"options": [{"text": "科技", "is_correct": true, "explanation": "正确答案。“现在的科技发展得很快”指科学技术的进步。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能作为“发展”的主体，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“发展”不与“天气”搭配，天气只会变化，不说“发展”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是具体物件，不能“发展得很快”。"}], "explanations": {"科技": "正确答案。“现在的科技发展得很快”指科学技术的进步。", "时间": "语义：时间不能作为“发展”的主体，句子说不通。", "天气": "搭配：“发展”不与“天气”搭配，天气只会变化，不说“发展”。", "桌子": "语义：桌子是具体物件，不能“发展得很快”。"}, "sentence_index": 0, "correct_answer": "科技"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的修车科技很熟练。", "explanation": "这里应该用〈技术〉。科技指科学技术的整体或新成果，个人具体的操作本领要说“技术”。"}, {"text": "他是一位很有名的科技。", "explanation": "这里应该用〈科学家〉。“科技”指科学技术及其成果，不指人，指从事科学研究的人要说“科学家”。"}, {"text": "她的游泳科技很好。", "explanation": "这里应该用〈技能〉。“游泳技能”指个人的游泳本领，“科技”指科学技术，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科技", "is_correct": true, "explanation": "正确答案。“科技博物馆”指展示科学技术的博物馆。"}, {"text": "胡说", "is_correct": false, "explanation": "语义：「胡说」是说假话，不能修饰博物馆，句意不通。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：「愤怒」是情绪，不能修饰博物馆，句意不通。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：“眼泪博物馆”与“孩子们都喜欢”的语境冲突，句意不通。"}], "explanations": {"科技": "正确答案。“科技博物馆”指展示科学技术的博物馆。", "胡说": "语义：「胡说」是说假话，不能修饰博物馆，句意不通。", "愤怒": "语义：「愤怒」是情绪，不能修饰博物馆，句意不通。", "眼泪": "语义：“眼泪博物馆”与“孩子们都喜欢”的语境冲突，句意不通。"}, "sentence_index": 6, "correct_answer": "科技"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司研发了一张新科技。", "explanation": "这里应该用〈项〉。科技是抽象的成果，量词用「项」；「张」用于纸、桌子等平面的东西。"}, {"text": "我们学习了一只新科技。", "explanation": "这里应该用〈门〉。“只”用于动物或成对器官中的一个，不能修饰“科技”，应说“一门科技”。"}, {"text": "老师向我们介绍了一根新科技。", "explanation": "这里应该用〈项〉。“根”用于细长的东西，不能修饰“科技”，应说“一项科技”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在学习这台新科技。", "corrected_sentence": "我们正在学习这项新科技。", "error_description": "量词错误：“科技”是抽象的概念或成果，量词应用“项”，“台”只用于机器设备。错误句中的“台”应改为“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些新科技们都很先进。", "corrected_sentence": "这些新科技都很先进。", "error_description": "后缀错误：“科技”是抽象名词，不能加复数后缀“们”，应说“这些新科技都很先进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
