INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业链就像一条长长的链条，把做不同事情的公司连在一起，一起做出一个东西。", "primary_collocate": null, "pronunciation": "chǎn yè liàn", "ipa": "ʈʂʰan˨˩˦ je˥˩ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "做一辆汽车需要很长的产业链。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块手机屏幕背后有一条产业链。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条产业链上有很多小公司。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包的产业链从种小麦开始。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业链里的每一家公司都很重要。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具的产业链里有工厂和商店。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在服装产业链工作了五年。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的产业链包括农民、卡车和超市。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条产业链断了，我们就买不到牛奶。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了咖啡的产业链。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不同公司连在一起做出一个东西的链条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产业链", "is_correct": true, "explanation": "正确。“产业链”指不同公司连在一起做出一个东西的链条，“做一辆汽车需要很长的产业链”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是能“做”出汽车所需的链条，“很长的颜色”也说不通。"}, {"text": "人情", "is_correct": false, "explanation": "语义：“人情”指人与人之间的情分，与制造汽车的环节无关。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“很长的感冒”不是常见搭配，“感冒”不能用来指做汽车需要的过程。"}], "explanations": {"产业链": "正确。“产业链”指不同公司连在一起做出一个东西的链条，“做一辆汽车需要很长的产业链”符合句意。", "颜色": "语义：“颜色”不是能“做”出汽车所需的链条，“很长的颜色”也说不通。", "人情": "语义：“人情”指人与人之间的情分，与制造汽车的环节无关。", "感冒": "搭配：“很长的感冒”不是常见搭配，“感冒”不能用来指做汽车需要的过程。"}, "sentence_index": 0, "correct_answer": "产业链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用这条产业链把自行车锁在树上。", "explanation": "这里误用了〈铁链〉的意思。产业链指多家企业连接的体系，不是能用来锁车的实物链条。"}, {"text": "这条产业链需要两个人一起拧螺丝。", "explanation": "这里应该用〈工序〉。产业链指多家企业连接的体系，不是一道具体的操作；拧螺丝属于工序。"}, {"text": "他每天在产业链里学习。", "explanation": "这里应该用〈班级〉。产业链是企业之间的链条，不是学习的地方，“在……里学习”要用班级、学校等场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产业链", "is_correct": true, "explanation": "正确。“服装产业链”指服装从生产到销售的相连环节，“他在服装产业链工作”符合句意。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”是学校的时间段，不能作为“服装”的领域让人“工作”。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”是语言变体，与“服装”不构成可以工作的领域。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“服装墨水”没有常见搭配，“墨水”与“服装”不能组成可工作的领域。"}], "explanations": {"产业链": "正确。“服装产业链”指服装从生产到销售的相连环节，“他在服装产业链工作”符合句意。", "学期": "语义：“学期”是学校的时间段，不能作为“服装”的领域让人“工作”。", "方言": "语义：“方言”是语言变体，与“服装”不构成可以工作的领域。", "墨水": "搭配：“服装墨水”没有常见搭配，“墨水”与“服装”不能组成可工作的领域。"}, "sentence_index": 6, "correct_answer": "产业链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司派产业链参加会议。", "explanation": "这里应该用〈代表〉。产业链是企业之间的连接关系，不能作为人去参加会议。"}, {"text": "这家面包店的产业链很甜。", "explanation": "这里应该用〈味道〉。产业链指企业间的链条，不能用“甜”来形容，“甜”说的是食物的味道。"}, {"text": "我们下午要去打一场产业链。", "explanation": "这里应该用〈篮球〉。“打”用于球类比赛，产业链不能被“打”，也不是一场活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座产业链连接着原料商和超市。", "corrected_sentence": "这条产业链连接着原料商和超市。", "error_description": "错误形式：“这座产业链”；正确形式：“这条产业链”。产业链的量词应为“条”，“座”用于山、桥、楼等大型固定建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂是服装产业链的一个链子。", "corrected_sentence": "这家工厂是服装产业链的一个环节。", "error_description": "错误形式：“产业链的一个链子”；正确形式：“产业链的一个环节”。产业链中的每一部分叫“环节”，不能说“链子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
