INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纺织品就是用来做衣服、毛巾、被子的布。", "primary_collocate": null, "pronunciation": "fǎng zhī pǐn", "ipa": "fɑŋ˨˩ ʈʂɨ˥ pʰin˨˩", "syllable_count": 3, "sentences": [{"text": "这家工厂专门生产纺织品。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织品要放在干燥的地方。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国出口很多纺织品。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买纺织品时要摸一摸料子。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛巾和被子都是纺织品。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家纺织品公司上班。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些纺织品是用棉花做的。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的纺织品洗后会变小。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很大的纺织品市场。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想开一家卖纺织品的店。", "target_word": "纺织品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "用线织成的布类产品，如衣服、毛巾、被子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纺织品", "is_correct": true, "explanation": "正确：工厂生产的布类产品就是纺织品，“专门生产”可以接它。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是果园种出来的，工厂不生产水果。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是写出来的作品，不是工厂生产出来的。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：天空不是工厂能“生产”的东西，搭配说不通。"}], "explanations": {"纺织品": "正确：工厂生产的布类产品就是纺织品，“专门生产”可以接它。", "水果": "语义：水果是果园种出来的，工厂不生产水果。", "诗歌": "语义：诗歌是写出来的作品，不是工厂生产出来的。", "天空": "搭配：天空不是工厂能“生产”的东西，搭配说不通。"}, "sentence_index": 0, "correct_answer": "纺织品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "纺织品每天要运转十个小时。", "explanation": "这里应该用〈纺织机〉。纺织机是机器，会运转；纺织品是布类产品，不会运转。"}, {"text": "他每天去纺织品上班，已经干了十年。", "explanation": "这里应该用〈纺织厂〉。纺织品是布料，不是工作的地方；上班要去纺织厂。"}, {"text": "纺织品每天要工作八个小时。", "explanation": "这里应该用〈纺织工人〉。工作的是人；纺织品是产品，不会工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纺织品", "is_correct": true, "explanation": "正确：“这些”指布类产品，用棉花做的正是纺织品。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是用棉花做的。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“这些”不能修饰“空气”这种不可数的东西。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不是用棉花做的。"}], "explanations": {"纺织品": "正确：“这些”指布类产品，用棉花做的正是纺织品。", "汽车": "语义：汽车不是用棉花做的。", "空气": "搭配：“这些”不能修饰“空气”这种不可数的东西。", "石头": "语义：石头是矿物，不是用棉花做的。"}, "sentence_index": 6, "correct_answer": "纺织品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂运来了一只纺织品。", "explanation": "这里应该用〈批〉。“只”用于动物或成对东西中的一个，成批的纺织品要用“批”。"}, {"text": "仓库里放着一台纺织品。", "explanation": "这里应该用〈批〉。“台”用于机器、电器，纺织品是货物，要用“批”。"}, {"text": "公司卖出了一本纺织品。", "explanation": "这里应该用〈批〉。“本”用于书、本子，不能用来数纺织品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港口运来了一只纺织品。", "corrected_sentence": "港口运来了一批纺织品。", "error_description": "错误：量词用了“只”；正确：“批”。“只”用于动物或成对东西中的一个，成批的货物要用“批”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批纺织品们是用棉花做的。", "corrected_sentence": "这批纺织品是用棉花做的。", "error_description": "错误：“们”加在了物品名词“纺织品”后面，“们”只用于指人；正确：去掉“们”，说“这批纺织品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
