INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26118, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看看东西对不对，比如检查作业有没有错。", "primary_collocate": null, "pronunciation": "jiǎn yàn", "ipa": "tɕjɛn˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "做完题，请你检验一下答案。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用计算器检验计算结果。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想检验这道题做得对不对。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把答案代回去检验一下。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写完以后，先自己检验一遍。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们互相检验答案。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又检验了一次数字。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束前，我又检验了一遍答案。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公式对不对，用例子检验就知道。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用加法检验减法的结果。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "检验了", "label": "完成体"}, {"form": "检验过", "label": "经历体"}, {"form": "检验检验", "label": "重叠"}], "register": "中性", "sense_fingerprint": "查看答案或作业对不对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语应为食物，不能说吃「答案」。"}, {"text": "检验", "is_correct": true, "explanation": "检验：查看答案对不对，与「做完题」后核对的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」只用于食材等，不能煮「答案」。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指唱歌，与核对答案的意思不符。"}], "explanations": {"吃": "搭配：「吃」的宾语应为食物，不能说吃「答案」。", "检验": "检验：查看答案对不对，与「做完题」后核对的语境相符。", "煮": "搭配：「煮」只用于食材等，不能煮「答案」。", "唱": "语义：「唱」指唱歌，与核对答案的意思不符。"}, "sentence_index": 0, "correct_answer": "检验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他检验了一个梦。", "explanation": "这里应该用〈做〉。检验指为看对不对而核对，做梦要用〈做〉，不能用检验。"}, {"text": "她检验了我的帮助。", "explanation": "这里应该用〈感谢〉。检验指为看对不对而核对，感谢别人的帮助要用〈感谢〉，不能用检验。"}, {"text": "她检验了一场晚会。", "explanation": "这里应该用〈主持〉。检验指为看对不对而核对，主持晚会要用〈主持〉，不能用检验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砍", "is_correct": false, "explanation": "语义：「砍」指用刀斩断，与核对数字的意思不符。"}, {"text": "熨", "is_correct": false, "explanation": "搭配：「熨」用于衣物等织物，不能熨「数字」。"}, {"text": "检验", "is_correct": true, "explanation": "检验：再次核对数字是否正确，与「又……一次」相符。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：「品尝」的宾语应为食物或饮品，不能说品尝「数字」。"}], "explanations": {"砍": "语义：「砍」指用刀斩断，与核对数字的意思不符。", "熨": "搭配：「熨」用于衣物等织物，不能熨「数字」。", "检验": "检验：再次核对数字是否正确，与「又……一次」相符。", "品尝": "搭配：「品尝」的宾语应为食物或饮品，不能说品尝「数字」。"}, "sentence_index": 6, "correct_answer": "检验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哥伦布检验了新大陆。", "explanation": "这里应该用〈发现〉。检验指为看对不对而核对，找到新大陆、新事物要用〈发现〉，不能用检验。"}, {"text": "天气预报检验明天的天气。", "explanation": "这里应该用〈预测〉。检验针对已有情况的核对，对未来情况的推断要用〈预测〉。"}, {"text": "她检验了一本英文小说。", "explanation": "这里应该用〈翻译〉。检验用于核对对错，把作品译成另一种语言要用〈翻译〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从没检验了作业。", "corrected_sentence": "他从没检验过作业。", "error_description": "错误：「从没」表示从未有过的经历，应与经历体「过」搭配，不能用完成体「了」。应说「从没检验过作业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在检验了答案。", "corrected_sentence": "他正在检验答案。", "error_description": "错误：「正在」表示动作正在进行，不能与完成体「了」同用。应去掉「了」，说「正在检验答案」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
