INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "干净的水是可以喝的水，没有脏东西。", "primary_collocate": null, "pronunciation": "gān jìng shuǐ", "ipa": "kan˥ tɕiŋ˥˩ ʂweɪ˨˩˦", "syllable_count": 3, "sentences": [{"text": "妈妈给宝宝准备了干净水。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干净水里没有脏东西，可以放心喝。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步以后，我想喝一杯干净水。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的人天天用干净水做饭。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校里有可以接干净水的地方。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上很远，我们带了很多干净水。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生病的人要多喝干净水。", "target_word": "干净水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水太脏，不能当干净水喝。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用干净水洗这些水果。", "target_word": "干净水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把瓶子洗好，装满了干净水。", "target_word": "干净水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "干净水：没有脏东西、可以喝的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海水", "is_correct": false, "explanation": "语义：海水是咸的，不能给宝宝喝，与“给宝宝准备”的语境矛盾。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“准备”给宝宝喝的水不能是“墨水”，墨水不能饮用。"}, {"text": "干净水", "is_correct": true, "explanation": "正确：指没有脏东西、可以喝的水，符合“给宝宝准备”的语境。"}, {"text": "脏水", "is_correct": false, "explanation": "语义：脏水里有脏东西，不能给宝宝喝，与“干净”的词义相反。"}], "explanations": {"海水": "语义：海水是咸的，不能给宝宝喝，与“给宝宝准备”的语境矛盾。", "墨水": "搭配：“准备”给宝宝喝的水不能是“墨水”，墨水不能饮用。", "干净水": "正确：指没有脏东西、可以喝的水，符合“给宝宝准备”的语境。", "脏水": "语义：脏水里有脏东西，不能给宝宝喝，与“干净”的词义相反。"}, "sentence_index": 0, "correct_answer": "干净水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我倒了一杯颜色发黑的干净水。", "explanation": "这里误用了词义。“干净水”是可以喝的水，这里却把它当成了“浑黑、不能喝的水”来用。"}, {"text": "这杯干净水不能喝，里面有很多脏东西。", "explanation": "这里误用了词义。“干净水”是可以喝的水，这里却把它当成了“污浊的水”来用。"}, {"text": "这里的人天天用一桶发臭的干净水做饭。", "explanation": "这里误用了词义。“干净水”指没有脏东西、可以喝的水，这里却把它当成了“有异味、不能用的水”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河水", "is_correct": false, "explanation": "语义：河水未经处理，可能含有细菌，生病的人喝了会更糟，不符合“多喝”的语境。"}, {"text": "汽油", "is_correct": false, "explanation": "配价：“喝”的宾语不能是汽油，汽油有毒、不能饮用。"}, {"text": "洗手液", "is_correct": false, "explanation": "搭配：“多喝”不搭配“洗手液”，洗手液不能当水喝。"}, {"text": "干净水", "is_correct": true, "explanation": "正确：指没有脏东西、可以喝的水，符合“生病的人要多喝”的语境。"}], "explanations": {"河水": "语义：河水未经处理，可能含有细菌，生病的人喝了会更糟，不符合“多喝”的语境。", "汽油": "配价：“喝”的宾语不能是汽油，汽油有毒、不能饮用。", "洗手液": "搭配：“多喝”不搭配“洗手液”，洗手液不能当水喝。", "干净水": "正确：指没有脏东西、可以喝的水，符合“生病的人要多喝”的语境。"}, "sentence_index": 6, "correct_answer": "干净水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把瓶子洗好，装满了有很多脏东西的干净水。", "explanation": "这里误用了词义。“干净水”没有脏东西，这里却把它当成了“含脏物、不干净的水”来用。"}, {"text": "他把瓶子洗好，装满了一瓶浑浊的干净水。", "explanation": "这里误用了词义。“干净水”指没有脏东西、可以喝的水，这里却把它当成了“含杂质、不干净的水”来用。"}, {"text": "他把瓶子洗好，然后把干净水喝光了，水很脏。", "explanation": "这里误用了词义。“干净水”指没有脏东西、可以喝的水，这里却把它当成了“污浊的水”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他递给我一只干净水。", "corrected_sentence": "他递给我一瓶干净水。", "error_description": "量词错误：“干净水”是液体，要用“瓶、杯”等容器量词，不能用“只”。正确说法如“一瓶干净水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天喝一干净水。", "corrected_sentence": "他每天喝一杯干净水。", "error_description": "量词缺失：“一”后面要有量词，应说“一杯干净水”，不能说“一干净水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
