INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿在身上的东西。", "primary_collocate": null, "pronunciation": "yī fu", "ipa": "i˥ fu", "syllable_count": 2, "sentences": [{"text": "这件衣服太小了，我穿不下。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，多穿一件衣服。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在洗我的衣服。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一件新衣服。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的衣服湿了，要换一下。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服挂在柜子里。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的衣服又好看又便宜。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个周末都去商店买衣服。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，快把衣服收进来。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服上有很多泥。", "target_word": "衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "口语", "sense_fingerprint": "穿在身上的衣物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb7735c-2a9b-4b0a-9aa5-30409c5f4706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "衣服", "is_correct": true, "explanation": "衣服 yīfu：穿在身上的东西，第二音节为轻声。"}, {"text": "依附", "is_correct": false, "explanation": "依附 yīfù 与 衣服 yīfu 第二音节声调不同（第四声与轻声），意思是依靠、附着。"}, {"text": "姨父", "is_correct": false, "explanation": "姨父 yífu 与 衣服 yīfu 第一音节声调不同（第二声与第一声），意思是姨妈的丈夫。"}, {"text": "已付", "is_correct": false, "explanation": "已付 yǐfù 与 衣服 yīfu 两个音节声调都不同，意思是已经支付。"}], "explanations": {"衣服": "衣服 yīfu：穿在身上的东西，第二音节为轻声。", "依附": "依附 yīfù 与 衣服 yīfu 第二音节声调不同（第四声与轻声），意思是依靠、附着。", "姨父": "姨父 yífu 与 衣服 yīfu 第一音节声调不同（第二声与第一声），意思是姨妈的丈夫。", "已付": "已付 yǐfù 与 衣服 yīfu 两个音节声调都不同，意思是已经支付。"}, "sentence_index": null, "correct_answer": "衣服"}, "level_3": {"options": [{"text": "衣服", "is_correct": true, "explanation": "衣服：穿在身上的东西，与“穿不下”相呼应。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是用来装东西的，不能穿，“穿不下”说不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是可以穿的东西，与“穿不下”冲突。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“穿”要求衣物作宾语，书包不能作“穿”的宾语。"}], "explanations": {"衣服": "衣服：穿在身上的东西，与“穿不下”相呼应。", "行李": "语义：行李是用来装东西的，不能穿，“穿不下”说不通。", "玩具": "语义：玩具不是可以穿的东西，与“穿不下”冲突。", "书包": "配价：“穿”要求衣物作宾语，书包不能作“穿”的宾语。"}, "sentence_index": 0, "correct_answer": "衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天吃衣服。", "explanation": "这里应该用〈水果〉。“吃”的对象是食物，水果可以吃；衣服不能吃，“吃衣服”不合语义。"}, {"text": "冰箱里放着很多衣服。", "explanation": "这里应该用〈牛奶〉。冰箱里放的是食品，如牛奶；衣服不放在冰箱里，这句把“衣服”放错了地方。"}, {"text": "我每天听衣服。", "explanation": "这里应该用〈音乐〉。“听”的对象是声音或音乐；衣服不能听，“听衣服”不合语义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衣服", "is_correct": true, "explanation": "衣服：商店卖的服装，与“又好看又便宜”相搭配。"}, {"text": "星星", "is_correct": false, "explanation": "语义：商店不卖星星，“这家店的星星又好看又便宜”说不通。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不是商店出售的东西，不能说“又便宜”。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“歌声”不能说“又好看”，也不属于商店出售的商品。"}], "explanations": {"衣服": "衣服：商店卖的服装，与“又好看又便宜”相搭配。", "星星": "语义：商店不卖星星，“这家店的星星又好看又便宜”说不通。", "感情": "语义：感情不是商店出售的东西，不能说“又便宜”。", "歌声": "搭配：“歌声”不能说“又好看”，也不属于商店出售的商品。"}, "sentence_index": 6, "correct_answer": "衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的衣服没电了，要充电。", "explanation": "这里应该用〈手机〉。手机需要充电；衣服没有电，“衣服没电了”不合语义。"}, {"text": "孩子在操场上踢衣服。", "explanation": "这里应该用〈足球〉。“踢”的对象是球类；衣服不能被踢，这句把“衣服”当作踢的对象，不合语义。"}, {"text": "他的衣服停在门口。", "explanation": "这里应该用〈汽车〉。“停”的主体是车辆；衣服不能停放，这句把“衣服”当作停放的主体，不合语义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她昨天买了一只新衣服。", "corrected_sentence": "她昨天买了一件新衣服。", "error_description": "量词错误：“衣服”应用量词“件”，不能用“只”（“只”用于动物或成对的器物），应说“一件新衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家商店的衣服们都很漂亮。", "corrected_sentence": "那家商店的衣服都很漂亮。", "error_description": "错误在于“们”。“衣服”是指物的名词，不能加“们”表示复数，应说“那家商店的衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变干净", "is_correct": true, "explanation": "反义：“变脏”指东西变得不干净，“变干净”指由脏变得清洁，二者相对。"}, {"text": "增高", "is_correct": false, "explanation": "无关：“增高”指高度变大，与清洁程度无关。"}, {"text": "发光", "is_correct": false, "explanation": "无关：“发光”指发出光亮，与清洁程度不相关。"}, {"text": "冻结", "is_correct": false, "explanation": "无关：“冻结”指变成固体或不能移动，与清洁程度无关。"}], "correct_answer": "变干净", "explanations": {"变干净": "反义：“变脏”指东西变得不干净，“变干净”指由脏变得清洁，二者相对。", "增高": "无关：“增高”指高度变大，与清洁程度无关。", "发光": "无关：“发光”指发出光亮，与清洁程度不相关。", "冻结": "无关：“冻结”指变成固体或不能移动，与清洁程度无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变干净", "is_correct": true, "explanation": "反义：“变脏”指东西变得不干净，“变干净”指由脏变得清洁，二者相对。"}, {"text": "拉长", "is_correct": false, "explanation": "无关：“拉长”指使物体变长，与清洁程度无关。"}, {"text": "漂浮", "is_correct": false, "explanation": "无关：“漂浮”指停留在液体表面，与清洁程度不相关。"}, {"text": "熔化", "is_correct": false, "explanation": "无关：“熔化”指固体因受热变成液体，与清洁程度无关。"}], "correct_answer": "变干净", "explanations": {"变干净": "反义：“变脏”指东西变得不干净，“变干净”指由脏变得清洁，二者相对。", "拉长": "无关：“拉长”指使物体变长，与清洁程度无关。", "漂浮": "无关：“漂浮”指停留在液体表面，与清洁程度不相关。", "熔化": "无关：“熔化”指固体因受热变成液体，与清洁程度无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变得不干净了。", "primary_collocate": null, "pronunciation": "biàn zāng", "ipa": "pjɛn˥˩ tsɑŋ˥", "syllable_count": 2, "sentences": [{"text": "白衣服沾了泥，就变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的白鞋走在雨里变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服太久不洗会变脏。", "target_word": "变脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗在泥里玩，身上都变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户很久没擦，已经变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水里放了很多垃圾，就会变脏。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭时小心，别让桌布变脏。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白色的东西最容易变脏。", "target_word": "变脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河以前很干净，现在变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些碗放在地上就变脏了。", "target_word": "变脏", "complexity_tier": "T3", "furigana": "zhè xiē wǎn fàng zài dì shàng jiù biàn zāng le", "sentence_source": "generated"}], "morphological_forms": [{"form": "变脏了", "label": "体标"}, {"form": "变脏过", "label": "体标"}], "register": "中性", "sense_fingerprint": "变脏：东西变得不干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生锈", "is_correct": false, "explanation": "搭配：衣服不会“生锈”，搭配不当。"}, {"text": "冻硬", "is_correct": false, "explanation": "语义：衣服沾了泥不会被“冻硬”，与前文的语境不符。"}, {"text": "发烫", "is_correct": false, "explanation": "语义：沾了泥的衣服不会“发烫”，句意不通。"}, {"text": "变脏", "is_correct": true, "explanation": "正确：指东西变得不干净，符合“沾了泥”的语境。"}], "explanations": {"生锈": "搭配：衣服不会“生锈”，搭配不当。", "冻硬": "语义：衣服沾了泥不会被“冻硬”，与前文的语境不符。", "发烫": "语义：沾了泥的衣服不会“发烫”，句意不通。", "变脏": "正确：指东西变得不干净，符合“沾了泥”的语境。"}, "sentence_index": 0, "correct_answer": "变脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的纪律变脏了，老师很生气。", "explanation": "这里误用了词义。“变脏”指东西沾上污垢、变得不干净，不能用于纪律，这里却把它当成了“纪律变差”的意思来用。"}, {"text": "这次出差的心情变脏了，一路上很开心。", "explanation": "这里误用了词义。“变脏”指东西沾上污垢，不能用于心情，这里却把它当成了“心情变坏”的意思来用。"}, {"text": "这家店的服务变脏了，客人很多。", "explanation": "这里误用了词义。“变脏”指东西沾上污垢，不能用于服务，这里却把它当成了“服务变差”的意思来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒烟", "is_correct": false, "explanation": "语义：桌布冒烟与“吃饭时小心”的语境矛盾，句意不通。"}, {"text": "长高", "is_correct": false, "explanation": "语义：桌布不会“长高”，与“吃饭时小心”的语境无关，句意不通。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：吃饭时的桌布不会结冰，与语境不符。"}, {"text": "变脏", "is_correct": true, "explanation": "正确：指东西变得不干净，符合“吃饭时小心，别让桌布……”的语境。"}], "explanations": {"冒烟": "语义：桌布冒烟与“吃饭时小心”的语境矛盾，句意不通。", "长高": "语义：桌布不会“长高”，与“吃饭时小心”的语境无关，句意不通。", "结冰": "语义：吃饭时的桌布不会结冰，与语境不符。", "变脏": "正确：指东西变得不干净，符合“吃饭时小心，别让桌布……”的语境。"}, "sentence_index": 6, "correct_answer": "变脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的议程变脏了，大家都很满意。", "explanation": "这里误用了词义。“变脏”指东西沾上污垢，不能用于议程，这里却把它当成了“议程出了问题”的意思来用。"}, {"text": "这些碗的质量变脏了，很多人都买了。", "explanation": "这里误用了词义。“变脏”指东西沾上污垢，不能用于质量，这里却把它当成了“质量变差”的意思来用。"}, {"text": "这次旅行的回忆变脏了，我一直很开心。", "explanation": "这里误用了词义。“变脏”指东西沾上污垢，不能用于回忆，这里却把它当成了“回忆变得不愉快”的意思来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "白毛衣沾了一点油，就很变脏了。", "corrected_sentence": "白毛衣沾了一点油，就变脏了。", "error_description": "副词位置错误：“很”修饰形容词，不能修饰动词“变脏”，应说“就变脏了”，不说“就很变脏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些杯子放在桌上很久，就变脏着。", "corrected_sentence": "这些杯子放在桌上很久，就变脏了。", "error_description": "体标错误：“变脏”表示变化后的结果，应用“了”，不能用“着”；应说“就变脏了”，不说“就变脏着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
