INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26126, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水在动，像河里的水在流。", "primary_collocate": null, "pronunciation": "shuǐ liú", "ipa": "ʂueɪ˨˩˦ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "河里的水流很快，小孩不能下水。", "target_word": "水流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，山上的水流变大了。", "target_word": "水流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的水流很慢，鱼很多。", "target_word": "水流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你听，远处有水流的声音。", "target_word": "水流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水流太急，小船过不去。", "target_word": "水流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在河边坐着，看水流慢慢向东走。", "target_word": "水流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，小河的水流比平时大。", "target_word": "水流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水流把河边的小石头冲走了。", "target_word": "水流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天水流小，河底的石头都看得见。", "target_word": "水流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里水流很急，我们不敢过河。", "target_word": "水流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "道", "label": "量词"}], "register": "中性", "sense_fingerprint": "水流|名词|流动的水，水流动的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9726593-59ca-4006-b21a-924968bd2405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水流", "is_correct": true, "explanation": "正确。水流指流动的水，即本题的目标词。"}, {"text": "水牛", "is_correct": false, "explanation": "水牛（shuǐniú）与水流的第二音节声母不同（n 与 l），声调相同，意思是一种家畜。"}, {"text": "水里", "is_correct": false, "explanation": "水里（shuǐlǐ）与水流的第二音节韵母不同（i 与 ou），声调也不同，意思是水的里面。"}, {"text": "水轮", "is_correct": false, "explanation": "水轮（shuǐlún）与水流的第二音节韵母不同（un 与 ou），声调相同，意思是利用水力转动的轮子。"}, {"text": "水鹿", "is_correct": false, "explanation": "水鹿（shuǐlù）与水流的第二音节韵母不同（u 与 ou），声调也不同，意思是一种鹿。"}], "explanations": {"水流": "正确。水流指流动的水，即本题的目标词。", "水牛": "水牛（shuǐniú）与水流的第二音节声母不同（n 与 l），声调相同，意思是一种家畜。", "水里": "水里（shuǐlǐ）与水流的第二音节韵母不同（i 与 ou），声调也不同，意思是水的里面。", "水轮": "水轮（shuǐlún）与水流的第二音节韵母不同（un 与 ou），声调相同，意思是利用水力转动的轮子。", "水鹿": "水鹿（shuǐlù）与水流的第二音节韵母不同（u 与 ou），声调也不同，意思是一种鹿。"}, "sentence_index": null, "correct_answer": "水流"}, "level_3": {"options": [{"text": "水流", "is_correct": true, "explanation": "正确。“水流”指流动的水，与“很快”相符，小孩不能下水也是因为水流急。"}, {"text": "河床", "is_correct": false, "explanation": "语义：河床是河底的土层，不会移动，不能用“很快”形容。"}, {"text": "水温", "is_correct": false, "explanation": "语义：水温说的是冷热，不能说快慢，“河里的水温很快”不成立。"}, {"text": "水体", "is_correct": false, "explanation": "语域：水体是地理、环保等书面或专业用语，口语叙述中不用；且水体本身不能说“很快”。"}], "explanations": {"水流": "正确。“水流”指流动的水，与“很快”相符，小孩不能下水也是因为水流急。", "河床": "语义：河床是河底的土层，不会移动，不能用“很快”形容。", "水温": "语义：水温说的是冷热，不能说快慢，“河里的水温很快”不成立。", "水体": "语域：水体是地理、环保等书面或专业用语，口语叙述中不用；且水体本身不能说“很快”。"}, "sentence_index": 0, "correct_answer": "水流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场水流淹没了三个村子。", "explanation": "这里应该用〈洪水〉。水流指水的流动，不指暴涨成灾的洪水；说水灾要用〈洪水〉。"}, {"text": "我渴了，想喝一杯水流。", "explanation": "这里应该用〈饮用水〉。水流指流动的水，不指装在杯中饮用的水；要喝的水应说〈饮用水〉。"}, {"text": "池塘里长满了水流，鱼都躲在水流下面。", "explanation": "这里应该用〈水草〉。水流是流动的水，不是植物；池塘里长的、鱼躲的应说〈水草〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26126, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "水流", "is_correct": true, "explanation": "正确。水流指流动的水，即本题的目标词。"}, {"text": "水雷", "is_correct": false, "explanation": "水雷（shuǐléi）与水流的第二音节韵母不同（ei 与 ou），声调相同，意思是水下布设用来爆炸的武器。"}, {"text": "水陆", "is_correct": false, "explanation": "水陆（shuǐlù）与水流的第二音节韵母不同（u 与 ou），声调也不同，意思是水上与陆地。"}, {"text": "水力", "is_correct": false, "explanation": "水力（shuǐlì）与水流的第二音节韵母和声调都不同（i 与 ou，第四声与第二声），意思是水的力量。"}], "explanations": {"水流": "正确。水流指流动的水，即本题的目标词。", "水雷": "水雷（shuǐléi）与水流的第二音节韵母不同（ei 与 ou），声调相同，意思是水下布设用来爆炸的武器。", "水陆": "水陆（shuǐlù）与水流的第二音节韵母不同（u 与 ou），声调也不同，意思是水上与陆地。", "水力": "水力（shuǐlì）与水流的第二音节韵母和声调都不同（i 与 ou，第四声与第二声），意思是水的力量。"}, "sentence_index": null, "correct_answer": "水流"}, "level_3": {"options": [{"text": "水流", "is_correct": true, "explanation": "正确。“水流”指流动的水，与“比平时大”相符，雨后水量增加，水流也随之变大。"}, {"text": "水质", "is_correct": false, "explanation": "语义：水质说的是水的好坏、清浊，不能用“比平时大”来比较。"}, {"text": "河岸", "is_correct": false, "explanation": "语义：河岸是河两侧的陆地边缘，与水势涨落无关，不能说“比平时大”。"}, {"text": "水文", "is_correct": false, "explanation": "语域：水文是水利学的专业术语，日常叙述中不用，不能说“水文比平时大”。"}], "explanations": {"水流": "正确。“水流”指流动的水，与“比平时大”相符，雨后水量增加，水流也随之变大。", "水质": "语义：水质说的是水的好坏、清浊，不能用“比平时大”来比较。", "河岸": "语义：河岸是河两侧的陆地边缘，与水势涨落无关，不能说“比平时大”。", "水文": "语域：水文是水利学的专业术语，日常叙述中不用，不能说“水文比平时大”。"}, "sentence_index": 6, "correct_answer": "水流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海上的水流很高，船差点翻了。", "explanation": "这里应该用〈波浪〉。水流指水的流动，不指起伏的高度；形容海面起伏要用〈波浪〉。"}, {"text": "湖的水流上涨了一米。", "explanation": "这里应该用〈水位〉。水流不指水面的高低；说水面升降的高度要用〈水位〉。"}, {"text": "这个湖的水流很深，别下去游泳。", "explanation": "这里应该用〈湖水〉。水流说的是水的流动，不说深浅；应说“这个湖的湖水很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山谷尽头有一个水流，冲得很急。", "corrected_sentence": "山谷尽头有一股水流，冲得很急。", "error_description": "量词错误：“水流”应搭配量词“股”，不能用通用量词“个”。正确说法是“一股水流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山上流下来一张水流，冲得很急。", "corrected_sentence": "山上流下来一股水流，冲得很急。", "error_description": "量词错误：“张”用于纸、桌子等扁平物，“水流”应该用“股”，应说“一股水流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
