INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26128, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西不干净，有土或别的让人不舒服的东西。", "primary_collocate": null, "pronunciation": "zāng", "ipa": "tsɑŋ˥", "syllable_count": 1, "sentences": [{"text": "你的手很脏，快去洗洗。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地上太脏了，我要打扫一下。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服太脏，不能穿。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的鞋很脏，进门前要脱掉。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有很多土，真脏。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子玩了一天，身上很脏。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的水很脏，别喝。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "厨房里太脏，我先把它打扫干净。", "target_word": "脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脏衣服放在这个篮子里。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗户很脏，外面的东西看不清。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "脏脏的", "label": "重叠"}], "register": "口语", "sense_fingerprint": "脏|形容词|东西不干净，有土或污物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9726593-59ca-4006-b21a-924968bd2405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26128, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脏", "is_correct": true, "explanation": "正确。脏指东西不干净，有土或污物。"}, {"text": "张", "is_correct": false, "explanation": "zh 与 z 声母不同，声调相同，意思是量词“张”，用于纸、桌子等。"}, {"text": "桑", "is_correct": false, "explanation": "s 与 z 声母不同，声调相同，意思是桑树。"}, {"text": "葬", "is_correct": false, "explanation": "zàng（第四声）与 zāng（第一声）声调不同，意思是埋葬。"}, {"text": "仓", "is_correct": false, "explanation": "c 与 z 声母不同，声调相同，意思是仓库。"}], "explanations": {"脏": "正确。脏指东西不干净，有土或污物。", "张": "zh 与 z 声母不同，声调相同，意思是量词“张”，用于纸、桌子等。", "桑": "s 与 z 声母不同，声调相同，意思是桑树。", "葬": "zàng（第四声）与 zāng（第一声）声调不同，意思是埋葬。", "仓": "c 与 z 声母不同，声调相同，意思是仓库。"}, "sentence_index": null, "correct_answer": "脏"}, "level_3": {"options": [{"text": "脏", "is_correct": true, "explanation": "正确。句中指手上有污物，需要洗。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”与后句“快去洗洗”的语境矛盾，句意不通。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”不能形容手的卫生状况。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：矮描述身高，不能用来形容手的卫生状况。"}], "explanations": {"脏": "正确。句中指手上有污物，需要洗。", "干净": "语义：“干净”与后句“快去洗洗”的语境矛盾，句意不通。", "甜": "语义：“甜”不能形容手的卫生状况。", "矮": "体貌：矮描述身高，不能用来形容手的卫生状况。"}, "sentence_index": 0, "correct_answer": "脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很脏，动不动就发火。", "explanation": "这里应该用〈坏〉。“脏”指东西不干净，不能用来形容脾气，脾气不好应说“坏”。"}, {"text": "这次的分数很脏，老师很生气。", "explanation": "这里应该用〈差〉或〈低〉。“脏”只用于东西有污物，不能形容分数，分数不理想应说“低”或“差”。"}, {"text": "这次的进度很脏，我们要加快。", "explanation": "“脏”不能形容进度，进度应说“快”或“慢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脏", "is_correct": true, "explanation": "正确。句中指河水有污染，不能喝。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”是形状，不能用来形容水的干净程度，与“别喝”的语境不符。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖描述人或动物的体形，不能用于水。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦描述人或动物的体形，不能用于水。"}], "explanations": {"脏": "正确。句中指河水有污染，不能喝。", "圆": "语义：“圆”是形状，不能用来形容水的干净程度，与“别喝”的语境不符。", "胖": "体貌：胖描述人或动物的体形，不能用于水。", "瘦": "体貌：瘦描述人或动物的体形，不能用于水。"}, "sentence_index": 6, "correct_answer": "脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的心情很脏，不想说话。", "explanation": "“脏”不能描述心情，心情应说“糟”或“好”，不能用“脏”。"}, {"text": "我们的距离很脏，要走很久。", "explanation": "“脏”不能形容距离，距离应说“远”或“近”。"}, {"text": "这个时间很脏，大家都在忙。", "explanation": "“脏”不能形容时间，时间紧张应说“紧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裤子脏很得厉害，要洗了。", "corrected_sentence": "这条裤子脏得很厉害，要洗了。", "error_description": "补语位置错误：“得”应紧跟形容词“脏”，应说“脏得很厉害”，不能说“脏很得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那件的脏衣服放在洗衣机旁边。", "corrected_sentence": "那件脏衣服放在洗衣机旁边。", "error_description": "结构错误：数量词“那件”与名词之间不能加“的”，应说“那件脏衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28b7b199-605a-4d4e-9da0-40f19d19ec2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
