INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种生活在水里的动物，可以游来游去。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "水里有一条鱼，正在游来游去。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩蹲在水边，看着鱼游来游去。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的缸里养着三条鱼，都很小。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在水里游，鸟在天上飞。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鱼放进了水里，鱼很快游走了。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里的鱼看见我，一下子都游走了。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫一直看着水里的鱼。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池子里的鱼有红的，也有黑的。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼不能离开水，不然会死。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在河边看到过一条很大的鱼。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "金鱼", "label": "复合"}, {"form": "鱼肉", "label": "复合"}, {"form": "魚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鱼：生活在水里、会游来游去的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d2bbf4-79da-4014-b207-c5baecb20bf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鱼", "is_correct": true, "explanation": "正确。鱼：生活在水里、会游来游去的动物。"}, {"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。"}, {"text": "育", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是培育。"}, {"text": "无", "is_correct": false, "explanation": "wú 与 yú 声母不同（w 与 y），意思是没有。"}, {"text": "如", "is_correct": false, "explanation": "rú 与 yú 声母不同（r 与 y），意思是像、如同。"}, {"text": "炉", "is_correct": false, "explanation": "lú 与 yú 声母不同（l 与 y），意思是炉子。"}, {"text": "局", "is_correct": false, "explanation": "jú 与 yú 声母不同（j 与 y），意思是局面、机构。"}], "explanations": {"鱼": "正确。鱼：生活在水里、会游来游去的动物。", "雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。", "育": "yù（第四声）与 yú（第二声）声调不同，意思是培育。", "无": "wú 与 yú 声母不同（w 与 y），意思是没有。", "如": "rú 与 yú 声母不同（r 与 y），意思是像、如同。", "炉": "lú 与 yú 声母不同（l 与 y），意思是炉子。", "局": "jú 与 yú 声母不同（j 与 y），意思是局面、机构。"}, "sentence_index": null, "correct_answer": "鱼"}, "level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：河是地理上的水道，不会游来游去。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线没有生命，不会在水里游来游去。"}, {"text": "鱼", "is_correct": true, "explanation": "正确。鱼生活在水里，会游来游去。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子没有生命，也不会游动。"}], "explanations": {"河": "语义：河是地理上的水道，不会游来游去。", "电线": "语义：电线没有生命，不会在水里游来游去。", "鱼": "正确。鱼生活在水里，会游来游去。", "绳子": "语义：绳子没有生命，也不会游动。"}, "sentence_index": 0, "correct_answer": "鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月交完房租，我还有一点鱼钱。", "explanation": "这里应该用〈余〉。“余”表示剩下，“余钱”是剩下的钱；鱼指水里的动物，不能这样用。"}, {"text": "这艘鱼船在海上开了一整天。", "explanation": "这里应该用〈渔船〉。捕鱼的船叫渔船，鱼指水里的动物，不能修饰船。"}, {"text": "他的爷爷一辈子都是鱼，常在海上过日子。", "explanation": "这里应该用〈渔夫〉。鱼指动物，以捕鱼为业的人叫渔夫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鱼", "is_correct": true, "explanation": "正确。鱼：生活在水里、会游来游去的动物。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。"}, {"text": "预", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是预先、事先。"}, {"text": "浴", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是洗澡。"}, {"text": "芋", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是芋头。"}, {"text": "读", "is_correct": false, "explanation": "dú 与 yú 声母不同（d 与 y），意思是阅读。"}], "explanations": {"鱼": "正确。鱼：生活在水里、会游来游去的动物。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。", "预": "yù（第四声）与 yú（第二声）声调不同，意思是预先、事先。", "浴": "yù（第四声）与 yú（第二声）声调不同，意思是洗澡。", "芋": "yù（第四声）与 yú（第二声）声调不同，意思是芋头。", "读": "dú 与 yú 声母不同（d 与 y），意思是阅读。"}, "sentence_index": null, "correct_answer": "鱼"}, "level_3": {"options": [{"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不会在水里。"}, {"text": "鱼", "is_correct": true, "explanation": "正确。水里的鱼是猫看的对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，“水里的”不能修饰它。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“看着水里的……”指水中可见的东西，桌子不与之搭配。"}], "explanations": {"电视": "语义：电视是家用电器，不会在水里。", "鱼": "正确。水里的鱼是猫看的对象。", "冰箱": "语义：冰箱是家电，“水里的”不能修饰它。", "桌子": "搭配：“看着水里的……”指水中可见的东西，桌子不与之搭配。"}, "sentence_index": 6, "correct_answer": "鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在河边看到过一张鱼，它在水里游。", "explanation": "这里应该用〈条〉。“张”用于纸、桌子等平面的东西，鱼用“条”计量。"}, {"text": "池子里有一座鱼，正在游来游去。", "explanation": "这里应该用〈条〉。“座”用于山、房子等，不用于鱼。"}, {"text": "我家养了一面鱼，很可爱。", "explanation": "这里应该用〈条〉。“面”用于镜子、旗子等平面的东西，不用于鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在湖边看见了三鱼条。", "corrected_sentence": "他们在湖边看见了三条鱼。", "error_description": "语序错误：量词“条”应放在“鱼”前面，应说“三条鱼”，不能说“三鱼条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在厨房里杀了一个鱼。", "corrected_sentence": "妈妈在厨房里杀了一条鱼。", "error_description": "量词错误：“鱼”应用“条”计量，“个”不能用于鱼，应说“一条鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
