INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一直做，没有停下。", "primary_collocate": null, "pronunciation": "bù tíng", "ipa": "pu˧˥ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们一路上说个不停，一点也不累。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不停地问问题，妈妈很有耐心。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不停地跑，一直跑到学校门口。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天她忙个不停，连饭也顾不上吃。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车不停地向前开，窗外的树一棵棵往后走。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着电视，手不停地换台。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在房间里跳个不停，楼下的人都听见了。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在树上不停地叫，吵得我睡不着。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水不停地流，从来没有停下过。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不停地看表，好像在等什么人。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不停地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "副词，一直做某事而不停下来，可放在动词前或“V个不停”中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停（bù tíng）是副词，表示一直做，没有停下。"}, {"text": "不听", "is_correct": false, "explanation": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。"}, {"text": "不疼", "is_correct": false, "explanation": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。"}, {"text": "不提", "is_correct": false, "explanation": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}], "explanations": {"不停": "不停（bù tíng）是副词，表示一直做，没有停下。", "不听": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。", "不疼": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。", "不提": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}, "sentence_index": null, "correct_answer": "不停"}, "level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：“说个不停”表示说话持续不断，与“一路上”的闲聊相符。"}, {"text": "很少", "is_correct": false, "explanation": "语法：“很少”不能放在“说个”后面，“说个很少”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”是物品，“说个桌子”不成立，与“一路上”的闲聊无关。"}, {"text": "齐全", "is_correct": false, "explanation": "搭配：“齐全”形容东西完备，不能接在“说个”后面，这个搭配不成立。"}], "explanations": {"不停": "不停：“说个不停”表示说话持续不断，与“一路上”的闲聊相符。", "很少": "语法：“很少”不能放在“说个”后面，“说个很少”不成立。", "桌子": "搭配：“桌子”是物品，“说个桌子”不成立，与“一路上”的闲聊无关。", "齐全": "搭配：“齐全”形容东西完备，不能接在“说个”后面，这个搭配不成立。"}, "sentence_index": 0, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的答案不停地是三。", "explanation": "这里误用了“不停”。“不停地”描述动作或变化持续进行，而这里说的是固定不变的判断，不会持续发生，因此不能用“不停地”修饰。"}, {"text": "他不停地道了一次歉，之后就离开了。", "explanation": "“不停”表示动作接连不断地进行，而“道歉一次”只发生一次，二者矛盾，这里不能用“不停”修饰。"}, {"text": "屋里很安静，她不停地睡着了。", "explanation": "“睡着”是瞬间发生的结果，不是可以持续不停进行的动作，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：“跳个不停”表示跳的动作持续不断，与“楼下的人都听见了”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音，与“跳”的动作和“楼下的人都听见了”矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或动作一致，不能用来描述“跳”的程度，“跳个整齐”不成立。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”是物品，“跳个椅子”不成立，不能描述跳的动作。"}], "explanations": {"不停": "不停：“跳个不停”表示跳的动作持续不断，与“楼下的人都听见了”相符。", "安静": "语义：“安静”指没有声音，与“跳”的动作和“楼下的人都听见了”矛盾。", "整齐": "搭配：“整齐”形容排列或动作一致，不能用来描述“跳”的程度，“跳个整齐”不成立。", "椅子": "搭配：“椅子”是物品，“跳个椅子”不成立，不能描述跳的动作。"}, "sentence_index": 6, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板一接到电话，不停地站了起来，走出了办公室。", "explanation": "这里应该用〈立刻〉。“立刻”表示接到电话后马上做出的一次反应，“不停”强调持续不断，用在这里语义不通。"}, {"text": "老板不停地停下了笔，抬头看了我一眼。", "explanation": "这里的“不停”表示一直持续，却修饰了表示中断、停止的动作，语义相互抵触。"}, {"text": "老板不停地收到了一份合同。", "explanation": "“收到合同”是一次性的结果，不能持续不停地发生，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹不停得翻书，想找到那张照片。", "corrected_sentence": "妹妹不停地翻书，想找到那张照片。", "error_description": "“不停地”中的“地”写成了“得”。作状语修饰动词时应用“地”；“得”用于动词或形容词之后引出补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟玩的不停，忘了写作业。", "corrected_sentence": "弟弟玩个不停，忘了写作业。", "error_description": "“个不停”是固定格式，中间的“个”不能换成“的”。应说“玩个不停”，不能说“玩的不停”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "妨碍", "is_correct": true, "explanation": "妨碍与“帮”相反，指使事情受阻、不能顺利进行。"}, {"text": "研究", "is_correct": false, "explanation": "与“帮”没有反义关系，研究指深入探讨问题。"}, {"text": "散步", "is_correct": false, "explanation": "与“帮”没有反义关系，散步指随意地走一走。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“帮”没有反义关系，唱歌指用声音表达乐曲。"}], "correct_answer": "妨碍", "explanations": {"妨碍": "妨碍与“帮”相反，指使事情受阻、不能顺利进行。", "研究": "与“帮”没有反义关系，研究指深入探讨问题。", "散步": "与“帮”没有反义关系，散步指随意地走一走。", "唱歌": "与“帮”没有反义关系，唱歌指用声音表达乐曲。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "妨碍", "is_correct": true, "explanation": "妨碍与“帮”相反，指使事情受阻、不能顺利进行。"}, {"text": "思考", "is_correct": false, "explanation": "与“帮”没有反义关系，思考指用脑子考虑问题。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“帮”没有反义关系，跳舞指随着音乐做动作。"}, {"text": "写作", "is_correct": false, "explanation": "与“帮”没有反义关系，写作指用文字表达思想。"}], "correct_answer": "妨碍", "explanations": {"妨碍": "妨碍与“帮”相反，指使事情受阻、不能顺利进行。", "思考": "与“帮”没有反义关系，思考指用脑子考虑问题。", "跳舞": "与“帮”没有反义关系，跳舞指随着音乐做动作。", "写作": "与“帮”没有反义关系，写作指用文字表达思想。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮就是帮助别人。", "primary_collocate": null, "pronunciation": "bāng", "ipa": "paŋ˥", "syllable_count": 1, "sentences": [{"text": "请你帮我拿一下这个包。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在做饭，我去帮她。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常帮同学补习数学。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能帮我看看这个字怎么读吗？", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑坏了，朋友帮我修好了。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，邻居帮我把衣服收进来。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你帮了我这么多。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮我改了作业里的错字。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮我找到了手机。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明帮奶奶提着很重的菜。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帮了", "label": "体标（了）"}, {"form": "帮过", "label": "体标（过）"}, {"form": "帮帮", "label": "重叠"}, {"form": "帮助", "label": "复合"}], "register": "中性", "sense_fingerprint": "给别人出力、提供帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd4466d2-ac6f-4a40-a8e9-8cb0ae81f61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帮", "is_correct": true, "explanation": "正确答案，指给别人出力、提供帮助。"}, {"text": "棒", "is_correct": false, "explanation": "声调不同（bàng 第四声，bāng 第一声），意思是好、厉害。"}, {"text": "搬", "is_correct": false, "explanation": "韵母不同（ān 与 āng），意思是搬运。"}, {"text": "方", "is_correct": false, "explanation": "声母不同（f 与 b），意思是方向、方形。"}, {"text": "班", "is_correct": false, "explanation": "韵母不同（ān 与 āng），意思是班级。"}], "explanations": {"帮": "正确答案，指给别人出力、提供帮助。", "棒": "声调不同（bàng 第四声，bāng 第一声），意思是好、厉害。", "搬": "韵母不同（ān 与 āng），意思是搬运。", "方": "声母不同（f 与 b），意思是方向、方形。", "班": "韵母不同（ān 与 āng），意思是班级。"}, "sentence_index": null, "correct_answer": "帮"}, "level_3": {"options": [{"text": "告诉", "is_correct": false, "explanation": "配价：“告诉”后面要接说话的内容，不能直接接“拿一下这个包”。"}, {"text": "帮", "is_correct": true, "explanation": "帮表示给予协助，符合请求别人帮忙拿东西的语境。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰”表示妨碍别人，与请求帮忙的语境相反。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，与请求帮忙的语境不合。"}], "explanations": {"告诉": "配价：“告诉”后面要接说话的内容，不能直接接“拿一下这个包”。", "帮": "帮表示给予协助，符合请求别人帮忙拿东西的语境。", "打扰": "语义：“打扰”表示妨碍别人，与请求帮忙的语境相反。", "批评": "语义：“批评”是指出错误，与请求帮忙的语境不合。"}, "sentence_index": 0, "correct_answer": "帮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他睡过头，帮我迟到了。", "explanation": "这里应该用〈害〉。使别人受到坏的结果要用〈害〉，如「他害我迟到了」；「帮」表示给予协助。"}, {"text": "妈妈帮孩子吓了一跳。", "explanation": "这里应该用〈吓〉。使人受惊要用〈吓〉，「帮」表示给予协助，不能说“帮孩子吓了一跳”。"}, {"text": "这场大雨帮我感冒了。", "explanation": "这里应该用〈让〉。造成某种不好的结果要说〈让〉，如「这场大雨让我感冒了」；「帮」表示给予协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帮", "is_correct": true, "explanation": "正确答案，指给别人出力、提供帮助。"}, {"text": "包", "is_correct": false, "explanation": "韵母不同（āo 与 āng），意思是包裹。"}, {"text": "斑", "is_correct": false, "explanation": "韵母不同（ān 与 āng），意思是斑点。"}, {"text": "刚", "is_correct": false, "explanation": "声母不同（g 与 b），意思是刚刚。"}, {"text": "绑", "is_correct": false, "explanation": "声调不同（bǎng 第三声，bāng 第一声），意思是捆绑。"}], "explanations": {"帮": "正确答案，指给别人出力、提供帮助。", "包": "韵母不同（āo 与 āng），意思是包裹。", "斑": "韵母不同（ān 与 āng），意思是斑点。", "刚": "声母不同（g 与 b），意思是刚刚。", "绑": "声调不同（bǎng 第三声，bāng 第一声），意思是捆绑。"}, "sentence_index": null, "correct_answer": "帮"}, "level_3": {"options": [{"text": "忘", "is_correct": false, "explanation": "语义：“忘”表示记不住，与感谢对方的语境相矛盾。"}, {"text": "帮", "is_correct": true, "explanation": "帮表示给予帮助，与“谢谢你……了我这么多”的语境相符。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”表示避开，与感谢对方的语境不合。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”不能带“我”作宾语来表示给予帮助。"}], "explanations": {"忘": "语义：“忘”表示记不住，与感谢对方的语境相矛盾。", "帮": "帮表示给予帮助，与“谢谢你……了我这么多”的语境相符。", "躲": "语义：“躲”表示避开，与感谢对方的语境不合。", "坐": "配价：“坐”不能带“我”作宾语来表示给予帮助。"}, "sentence_index": 6, "correct_answer": "帮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮我笑了一下。", "explanation": "这里应该用〈逗〉。使人发笑要用〈逗〉，「帮」是给予协助，不能让人笑。"}, {"text": "他帮我哭了一场。", "explanation": "这里应该用〈陪〉。陪别人一起哭要用〈陪〉，「帮」是出力协助，不能替人哭。"}, {"text": "妈妈帮我生气了。", "explanation": "这里应该用〈惹〉。使人生气要用〈惹〉，「帮」表示给予协助，不能说“帮我生气”，如“妈妈惹我生气了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他帮我了很多忙。", "corrected_sentence": "他帮了我很多忙。", "error_description": "错误：动态助词“了”放在了宾语“我”之后。正确：“帮了我很多忙”，“了”紧跟动词“帮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他帮忙了我很多。", "corrected_sentence": "他帮了我很多。", "error_description": "离合词错误：“帮忙”是离合词，后面不能直接带宾语“我”。正确：“帮了我很多”或“帮了我很多忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
