INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "去一个地方要走的路。", "primary_collocate": null, "pronunciation": "lù xiàn", "ipa": "lu˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "请把你回家的路线画给我看。", "target_word": "路线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的旅行路线是从北京到上海。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共汽车的路线有变化，你要看清楚。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次来这座城市，不熟悉路线，一直在看地图。", "target_word": "路线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条跑步路线很安静，风景也好。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游告诉大家明天的路线。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的路线太难走，我们决定换一条。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机上有三条去机场的路线。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我记错了路线，所以迟到了。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机选了一条最近的路线。", "target_word": "路线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "路线图", "label": "复合"}], "register": "通用", "sense_fingerprint": "名词，去某地所走的具体道路，如旅行、公交、跑步路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路线", "is_correct": true, "explanation": "路线：回家所走的道路，可以在纸上画出来，与“画给我看”相符。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“地址”是文字信息，不能用“画”来表示，应说“写”。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不能用“画”来表达，“画时间”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的色彩，不是回家的路径，与“回家的”搭配不通。"}], "explanations": {"路线": "路线：回家所走的道路，可以在纸上画出来，与“画给我看”相符。", "地址": "搭配：“地址”是文字信息，不能用“画”来表示，应说“写”。", "时间": "搭配：“时间”不能用“画”来表达，“画时间”不成立。", "颜色": "语义：“颜色”是事物的色彩，不是回家的路径，与“回家的”搭配不通。"}, "sentence_index": 0, "correct_answer": "路线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手里拿着一本路线，却还是找不到路。", "explanation": "这里应该用〈条〉。路线的量词是“条”，“本”用于书册，不能用来数路线。"}, {"text": "今天的路线很滑，开车要小心。", "explanation": "这里应该用〈路况〉。路线指行走的路径，不能用来描述路面是否湿滑。"}, {"text": "今天路线很严重，我们迟到了。", "explanation": "这里应该用〈堵车〉。路线指走过的道路，不能说“严重”。描述路上交通拥挤要用〈堵车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路线", "is_correct": true, "explanation": "路线：山里走的道路，“太难走”说的是路难走，与之相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以行走的对象，“天气太难走”说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”是人的动作，不能说“太难走”，这个搭配不成立。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”是时间段，不是可以行走的地方，与“难走”不相容。"}], "explanations": {"路线": "路线：山里走的道路，“太难走”说的是路难走，与之相符。", "天气": "语义：“天气”不是可以行走的对象，“天气太难走”说不通。", "脚步": "搭配：“脚步”是人的动作，不能说“太难走”，这个搭配不成立。", "季节": "语义：“季节”是时间段，不是可以行走的地方，与“难走”不相容。"}, "sentence_index": 6, "correct_answer": "路线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的路线很高，需要马上去医院。", "explanation": "这里应该用〈体温〉。路线不能用来说人的体温高低。"}, {"text": "这首歌的路线很感人，我听哭了。", "explanation": "这里应该用〈歌词〉。路线不能用来评价歌词的感人程度。"}, {"text": "这场比赛的路线是二比一。", "explanation": "这里应该用〈比分〉。路线不能用来表示比赛的分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本路线很近，我们走路就能到。", "corrected_sentence": "这条路线很近，我们走路就能到。", "error_description": "量词错误。“路线”的量词应为“条”，“本”用于书册，不能用来数路线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机换了一根路线，避开了堵车。", "corrected_sentence": "司机换了一条路线，避开了堵车。", "error_description": "量词错误。“路线”的量词应为“条”，“根”用于细长的物件，不能用来数路线。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
