INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用棉花做的。", "primary_collocate": null, "pronunciation": "mián zhì", "ipa": "mi̯ɛn˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这条毛巾是棉质的。", "target_word": "棉质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天我爱穿棉质衬衫。", "target_word": "棉质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的睡衣是棉质的，很软。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棉质袜子吸汗，脚不会太热。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一件棉质的外套。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个枕头套是棉质的，可以放进洗衣机。", "target_word": "棉质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢棉质裤子，因为穿着舒服。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双手套不是棉质的，是羊毛的。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩的衣服最好是棉质的。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买了一块棉质的桌布。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棉質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "棉质·用棉花做成的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "棉质", "is_correct": true, "explanation": "正确答案：棉质（mián zhì），指用棉花做的。"}, {"text": "免职", "is_correct": false, "explanation": "免职（miǎn zhí）与棉质（mián zhì）声调不同，意思是解除职务。"}, {"text": "闲置", "is_correct": false, "explanation": "xián 与 mián 声调相同，只差声母（x 与 m），闲置指没有被利用。"}, {"text": "棉纸", "is_correct": false, "explanation": "棉纸（mián zhǐ）第二音节 zhǐ（第三声）与 zhì（第四声）声调不同，意思是用棉纤维制成的纸。"}, {"text": "面值", "is_correct": false, "explanation": "面值（miàn zhí）两个音节的声调都与棉质不同，意思是票面价值。"}], "explanations": {"棉质": "正确答案：棉质（mián zhì），指用棉花做的。", "免职": "免职（miǎn zhí）与棉质（mián zhì）声调不同，意思是解除职务。", "闲置": "xián 与 mián 声调相同，只差声母（x 与 m），闲置指没有被利用。", "棉纸": "棉纸（mián zhǐ）第二音节 zhǐ（第三声）与 zhì（第四声）声调不同，意思是用棉纤维制成的纸。", "面值": "面值（miàn zhí）两个音节的声调都与棉质不同，意思是票面价值。"}, "sentence_index": null, "correct_answer": "棉质"}, "level_3": {"options": [{"text": "棉质", "is_correct": true, "explanation": "正确：毛巾是用棉花做的，与句意相符。"}, {"text": "木质", "is_correct": false, "explanation": "语义：毛巾不是木头做的，木质与句中的材料不符。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：毛巾不用塑料制成，与句中的材料不符。"}, {"text": "陶瓷", "is_correct": false, "explanation": "搭配：陶瓷多用于器皿，不说“毛巾是陶瓷的”。"}], "explanations": {"棉质": "正确：毛巾是用棉花做的，与句意相符。", "木质": "语义：毛巾不是木头做的，木质与句中的材料不符。", "塑料": "语义：毛巾不用塑料制成，与句中的材料不符。", "陶瓷": "搭配：陶瓷多用于器皿，不说“毛巾是陶瓷的”。"}, "sentence_index": 0, "correct_answer": "棉质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张铁桌子是棉质的，很结实。", "explanation": "棉质指用棉花做的，铁桌子不是棉制品，这里应说“铁制”或“钢制”。"}, {"text": "这部棉质手机很薄，很好用。", "explanation": "这里应该用〈塑料〉。棉质指用棉花做的，手机外壳多为塑料或金属，不是棉制品。"}, {"text": "这座房子是棉质的，住起来很暖和。", "explanation": "这里应该用〈砖〉。棉质指用棉花做的，房子主要用砖、混凝土等建成，不是棉制品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棉质", "is_correct": true, "explanation": "正确：棉质裤子穿着舒服，与“爸爸喜欢……因为穿着舒服”相符。"}, {"text": "石质", "is_correct": false, "explanation": "语义：石头做的裤子穿着不舒服，与后半句矛盾。"}, {"text": "金属", "is_correct": false, "explanation": "语义：金属裤子硬且不透气，与“穿着舒服”相矛盾。"}, {"text": "陶瓷", "is_correct": false, "explanation": "搭配：陶瓷不用于制作裤子，不说“陶瓷裤子”。"}], "explanations": {"棉质": "正确：棉质裤子穿着舒服，与“爸爸喜欢……因为穿着舒服”相符。", "石质": "语义：石头做的裤子穿着不舒服，与后半句矛盾。", "金属": "语义：金属裤子硬且不透气，与“穿着舒服”相矛盾。", "陶瓷": "搭配：陶瓷不用于制作裤子，不说“陶瓷裤子”。"}, "sentence_index": 6, "correct_answer": "棉质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子是棉质的，很便宜。", "explanation": "这里应该用〈塑料〉。棉质指用棉花做的，尺子多为塑料或木头，不是棉制品。"}, {"text": "这双皮鞋是棉质的，很耐穿。", "explanation": "这里应该用〈皮革〉。棉质指用棉花做的，皮鞋多为皮革制成，不是棉制品。"}, {"text": "这块木板是棉质的，可以拿来钉墙。", "explanation": "这里应该用〈木质〉。棉质指用棉花做的，木板是木质的，不是棉制品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条围巾不棉质的，颜色很好看。", "corrected_sentence": "这条围巾是棉质的，颜色很好看。", "error_description": "判断“棉质”的属性要用“是……的”；“不棉质的”把“不”放在了“是”的位置，应说“这条围巾是棉质的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我买了一件很棉质外套。", "corrected_sentence": "妈妈给我买了一件棉质外套。", "error_description": "“棉质”是表示质地的属性词，不能受“很”修饰；应说“棉质外套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
