INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种短袖衣服。", "primary_collocate": null, "pronunciation": "tī xù", "ipa": "tʰi˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "天气热，大家都穿T恤。", "target_word": "T恤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的T恤是黑色的。", "target_word": "T恤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想买一件新T恤。", "target_word": "T恤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件T恤上有一只大熊。", "target_word": "T恤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟每天都穿同一件T恤。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完以后，T恤变小了。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把T恤放在床上了。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件T恤穿着很舒服。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的T恤很好看，在哪儿买的？", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班的同学都有一件白T恤。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "短袖T恤", "label": "复合"}], "register": "中性", "sense_fingerprint": "T恤·一种短袖衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "T恤", "is_correct": true, "explanation": "正确：T恤是夏天常穿的短袖衣服，与“天气热”相符。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：天气热，大家不会穿大衣，与“天气热”矛盾。"}, {"text": "毛衣", "is_correct": false, "explanation": "语义：天气热，大家不会穿毛衣，与“天气热”矛盾。"}, {"text": "空调", "is_correct": false, "explanation": "配价：“穿”不接电器，不能说“穿空调”。"}], "explanations": {"T恤": "正确：T恤是夏天常穿的短袖衣服，与“天气热”相符。", "大衣": "语义：天气热，大家不会穿大衣，与“天气热”矛盾。", "毛衣": "语义：天气热，大家不会穿毛衣，与“天气热”矛盾。", "空调": "配价：“穿”不接电器，不能说“穿空调”。"}, "sentence_index": 0, "correct_answer": "T恤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一条T恤，穿着很合身。", "explanation": "这里应该用〈件〉。T恤是上衣，量词用“件”；“条”一般用于裤子、裙子、毛巾等。"}, {"text": "他用一件T恤做了一张桌子。", "explanation": "这里应该用〈木头〉。T恤是衣服，不能用来做桌子；做桌子要用木头。"}, {"text": "他拿着T恤打电话。", "explanation": "这里应该用〈手机〉。T恤是衣服，不能用来打电话；打电话要用手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "T恤", "is_correct": true, "explanation": "正确：T恤是可以放在床上的衣物，与句意相符。"}, {"text": "太阳", "is_correct": false, "explanation": "配价：“放”要求可以移动的物体，太阳不能放在床上。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能放在床上，与句中的物品不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被放在床上，与句意不符。"}], "explanations": {"T恤": "正确：T恤是可以放在床上的衣物，与句意相符。", "太阳": "配价：“放”要求可以移动的物体，太阳不能放在床上。", "河流": "语义：河流不能放在床上，与句中的物品不符。", "空气": "语义：空气不能被放在床上，与句意不符。"}, "sentence_index": 6, "correct_answer": "T恤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "数学课上，他在黑板上写了T恤。", "explanation": "这里应该用〈字〉。T恤是衣服，不能被写，“写”的对象应是字。"}, {"text": "他给T恤写了一封信。", "explanation": "这里应该用〈朋友〉。T恤是衣服，没有生命，不能收信；写信要写给人，比如朋友。"}, {"text": "我们每天在T恤上吃饭。", "explanation": "这里应该用〈桌子〉。T恤是衣服，不能作为吃饭的地方；吃饭要在桌子上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的衣柜里有一只T恤。", "corrected_sentence": "我的衣柜里有一件T恤。", "error_description": "错误：“一只T恤”，应为“一件T恤”。“只”用于动物，衣服用量词“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他戴着一件新T恤去上学。", "corrected_sentence": "他穿着一件新T恤去上学。", "error_description": "错误：动词“戴”用错。T恤是上衣，应该用“穿”；“戴”用于帽子、眼镜等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
