INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26160, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看到了想找的人或东西。", "primary_collocate": null, "pronunciation": "zhǎo dào", "ipa": "ʈʂɑʊ˨˩˦ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我终于找到了我的钥匙。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在哪儿找到这本书的？", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了很久，还是没找到手机。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在桌子下面找到了小猫。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们找到一家很好吃的饭馆。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找到工作了吗？", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在公园里找到了他的球。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没找到回家的路。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找到过一块很大的石头。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察很快找到了那个人。", "target_word": "找到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找到了", "label": "体标"}, {"form": "找到过", "label": "体标"}, {"form": "没找到", "label": "否定"}], "register": "中性", "sense_fingerprint": "经过寻找，发现了想找的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找到", "is_correct": true, "explanation": "正确答案。找到指经过寻找，看到了想找的人或东西。"}, {"text": "早到", "is_correct": false, "explanation": "zǎo dào 与 zhǎo dào 只有声母不同（z 与 zh），意思是提前到达。"}, {"text": "照到", "is_correct": false, "explanation": "zhào dào 与 zhǎo dào 第一个音节声调不同（第四声与第三声），意思是光线照射到某处。"}, {"text": "吵到", "is_correct": false, "explanation": "chǎo dào 与 zhǎo dào 声母不同（ch 与 zh），意思是声音打扰到别人。"}], "explanations": {"找到": "正确答案。找到指经过寻找，看到了想找的人或东西。", "早到": "zǎo dào 与 zhǎo dào 只有声母不同（z 与 zh），意思是提前到达。", "照到": "zhào dào 与 zhǎo dào 第一个音节声调不同（第四声与第三声），意思是光线照射到某处。", "吵到": "chǎo dào 与 zhǎo dào 声母不同（ch 与 zh），意思是声音打扰到别人。"}, "sentence_index": null, "correct_answer": "找到"}, "level_3": {"options": [{"text": "找到", "is_correct": true, "explanation": "正确答案。「终于」表示经过努力后达成，与「找到」相符。"}, {"text": "失去", "is_correct": false, "explanation": "语义：「终于」表示经过努力后得到结果，「失去」与之相反，句意矛盾。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：「打开」多接门、箱子等，不能接「钥匙」。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」指想不起来，与「终于」所表示的得到结果相冲突。"}], "explanations": {"找到": "正确答案。「终于」表示经过努力后达成，与「找到」相符。", "失去": "语义：「终于」表示经过努力后得到结果，「失去」与之相反，句意矛盾。", "打开": "搭配：「打开」多接门、箱子等，不能接「钥匙」。", "忘记": "语义：「忘记」指想不起来，与「终于」所表示的得到结果相冲突。"}, "sentence_index": 0, "correct_answer": "找到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我没有去找，却在超市门口找到了多年没见的老同学。", "explanation": "这里应该用〈遇到〉。找到强调经过寻找后找着，句中说“没有去找”，前后矛盾；偶然碰见要用遇到。"}, {"text": "他靠努力找到了好成绩。", "explanation": "这里应该用〈取得〉。找到指找出已经存在的人或东西，成绩要靠努力取得，不能说找到。"}, {"text": "他在比赛中找到了第一名。", "explanation": "这里应该用〈赢得〉。找到不能表示凭比赛取胜而获得名次，这里要用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找到", "is_correct": true, "explanation": "正确答案。句子说孩子找回了自己的球，「找到」表示找着了失去的东西。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：「吃掉」的宾语须是食物，球不能吃。"}, {"text": "参观", "is_correct": false, "explanation": "配价：「参观」的宾语是场所或展览，不能接「球」。"}, {"text": "叼走", "is_correct": false, "explanation": "语义：「叼走」指动物用嘴拿走东西，句子主语是孩子，不合。"}], "explanations": {"找到": "正确答案。句子说孩子找回了自己的球，「找到」表示找着了失去的东西。", "吃掉": "搭配：「吃掉」的宾语须是食物，球不能吃。", "参观": "配价：「参观」的宾语是场所或展览，不能接「球」。", "叼走": "语义：「叼走」指动物用嘴拿走东西，句子主语是孩子，不合。"}, "sentence_index": 6, "correct_answer": "找到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说找到了大家的注意。", "explanation": "这里应该用〈引起〉。找到用于找出已经存在的人或东西，注意是由事情引起的，不能说找到。"}, {"text": "他的笑话找到了大家的笑声。", "explanation": "这里应该用〈招来〉。笑声是笑话招来的反应，找到不能用于这种反应。"}, {"text": "这个方法找到了很大的作用。", "explanation": "这里应该用〈发挥〉。作用要靠发挥出来，找到只用于找出已有的人或东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在图书馆找到不那本书。", "corrected_sentence": "我在图书馆找不到那本书。", "error_description": "错误：找到不。正确：找不到。表示没有能力找着时，“不”要放在“找”和“到”中间，说成“找不到”，不能放在“找到”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直在找到护照，终于找到了。", "corrected_sentence": "我一直在找护照，终于找到了。", "error_description": "「在找到护照」错误，正确是「在找护照」。「找到」表示结果，不能用于进行中；「在」之后只能接「找」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减轻", "is_correct": true, "explanation": "减轻：与“加重”互为反义词，指使负担或程度变轻。"}, {"text": "说明", "is_correct": false, "explanation": "说明：指讲清楚道理，与“加重”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集：指把物品聚到一起，与“加重”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指出外游览，与“加重”没有反义关系。"}], "correct_answer": "减轻", "explanations": {"减轻": "减轻：与“加重”互为反义词，指使负担或程度变轻。", "说明": "说明：指讲清楚道理，与“加重”没有反义关系。", "收集": "收集：指把物品聚到一起，与“加重”没有反义关系。", "旅行": "旅行：指出外游览，与“加重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减轻", "is_correct": true, "explanation": "减轻：与“加重”互为反义词，指使负担或程度变轻。"}, {"text": "研究", "is_correct": false, "explanation": "研究：指深入探讨，与“加重”没有反义关系。"}, {"text": "安排", "is_correct": false, "explanation": "安排：指预先布置，与“加重”没有反义关系。"}, {"text": "解释", "is_correct": false, "explanation": "解释：指说明道理，与“加重”没有反义关系。"}], "correct_answer": "减轻", "explanations": {"减轻": "减轻：与“加重”互为反义词，指使负担或程度变轻。", "研究": "研究：指深入探讨，与“加重”没有反义关系。", "安排": "安排：指预先布置，与“加重”没有反义关系。", "解释": "解释：指说明道理，与“加重”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更重或让问题变得更严重。", "primary_collocate": null, "pronunciation": "jiā zhòng", "ipa": "tɕia˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他往包里多放了几块石头，加重了背包的负担。", "target_word": "加重", "complexity_tier": "T3", "furigana": "tā wǎng bāo lǐ duō fàng le jǐ kuài shítou, jiāzhòng le bēibāo de fùdān.", "sentence_source": "generated"}, {"text": "熬夜会加重你的黑眼圈。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷了，奶奶的腿疼加重了。", "target_word": "加重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次失败加重了他心里的压力。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不吃药只会加重病情。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要再加重我的负担了。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物太多，加重了卡车的负担。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪加重了山区的交通困难。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架只会加重两个人的矛盾。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的批评加重了他的紧张。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加重了", "label": "体标"}, {"form": "加重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "让东西更重，或让问题、病情更严重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重 jiāzhòng，意思是让东西更重，或让问题、病情更严重。"}, {"text": "家中", "is_correct": false, "explanation": "第二个音节的声调不同：zhōng（第一声）与 zhòng（第四声）不同，家中意思是在家里。"}, {"text": "家政", "is_correct": false, "explanation": "第二个音节的韵母不同：zhèng 与 zhòng 的韵母是 eng 与 ong，家政意思是家务管理。"}, {"text": "甲种", "is_correct": false, "explanation": "两个音节的声调都不同：jiǎzhǒng（第三声）与 jiāzhòng 不同，甲种意思是甲类。"}], "explanations": {"加重": "加重 jiāzhòng，意思是让东西更重，或让问题、病情更严重。", "家中": "第二个音节的声调不同：zhōng（第一声）与 zhòng（第四声）不同，家中意思是在家里。", "家政": "第二个音节的韵母不同：zhèng 与 zhòng 的韵母是 eng 与 ong，家政意思是家务管理。", "甲种": "两个音节的声调都不同：jiǎzhǒng（第三声）与 jiāzhòng 不同，甲种意思是甲类。"}, "sentence_index": null, "correct_answer": "加重"}, "level_3": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重：说多放石头使背包更重，与语境一致。"}, {"text": "减轻", "is_correct": false, "explanation": "语义：往包里多放石头只会使负担变重，“减轻”与语境相反。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”不接“负担”作宾语，不能说保护“背包的负担”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语须是活动，不能接“背包的负担”。"}], "explanations": {"加重": "加重：说多放石头使背包更重，与语境一致。", "减轻": "语义：往包里多放石头只会使负担变重，“减轻”与语境相反。", "保护": "搭配：“保护”不接“负担”作宾语，不能说保护“背包的负担”。", "参加": "配价：“参加”的宾语须是活动，不能接“背包的负担”。"}, "sentence_index": 0, "correct_answer": "加重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司去年的利润加重了两成。", "explanation": "这里应该用〈增加〉。加重说重量或负担变重，利润、数量要用增加。"}, {"text": "这次谈话后，我对他的了解加重了。", "explanation": "这里应该用〈加深〉。加重指重量或负担变重，抽象的了解要用加深。"}, {"text": "这个月，工厂的生产速度加重了。", "explanation": "这里应该用〈加快〉。加重说重量或负担变重，速度的变化要用加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重：说货物使卡车负担更重，与“货物太多”的因果一致。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品的外观，不能说装饰“负担”。"}, {"text": "调查", "is_correct": false, "explanation": "配价：“调查”需要人作主语，“货物太多”不能调查。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：货物太多会使负担变重，“消灭负担”与这一语境相反。"}], "explanations": {"加重": "加重：说货物使卡车负担更重，与“货物太多”的因果一致。", "装饰": "搭配：“装饰”的对象是物品的外观，不能说装饰“负担”。", "调查": "配价：“调查”需要人作主语，“货物太多”不能调查。", "消灭": "语义：货物太多会使负担变重，“消灭负担”与这一语境相反。"}, "sentence_index": 6, "correct_answer": "加重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的英语水平加重了很多。", "explanation": "这里应该用〈提高〉。加重用于重量、负担或病情，水平、质量要用提高。"}, {"text": "这次改革后，学校的规模加重了。", "explanation": "这里应该用〈扩大〉。加重指重量、负担或病情变得更重，规模、范围要用扩大。"}, {"text": "他的记忆力加重了不少。", "explanation": "这里应该用〈增强〉。加重用于重量、负担或病情，记忆力、能力要用增强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他往行李箱里放了很多书，行李箱很加重了。", "corrected_sentence": "他往行李箱里放了很多书，行李箱加重了。", "error_description": "副词“很”不能直接修饰动词“加重”，应去掉“很”，说“行李箱加重了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长期加班加重得他的身体负担。", "corrected_sentence": "长期加班加重了他的身体负担。", "error_description": "“加重”后表示完成的“了”不能换成“得”（“得”引出补语）。应说“加重了他的身体负担”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
