INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用过的、脏了的水。", "primary_collocate": null, "pronunciation": "fèi shuǐ", "ipa": "feɪ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "洗完衣服的废水可以用来冲厕所。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的废水要流到下水道。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条小河里全是工厂排出的废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废水又脏又臭，不能喝。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能把废水倒进河里。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厂专门处理城市的废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着黑色的废水流进大河。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用过的废水不要乱倒，要收集起来。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有一个池子，专门存放实验室的废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗车店的废水常常带着很多泡沫。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业废水", "label": "复合"}, {"form": "生活废水", "label": "复合"}], "register": "中性", "sense_fingerprint": "用过之后变脏、不能再用的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废水", "is_correct": true, "explanation": "废水：符合句意，指洗完衣服后用过、变脏的水。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是食品，洗完衣服不会产生牛奶，也不能用来冲厕所。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是饮料，不是洗衣后的水，与“冲厕所”的用途冲突。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：洗衣服后的水才说“用来冲厕所”，汽油是危险液体，不能这样使用。"}], "explanations": {"废水": "废水：符合句意，指洗完衣服后用过、变脏的水。", "牛奶": "语义：牛奶是食品，洗完衣服不会产生牛奶，也不能用来冲厕所。", "果汁": "语义：果汁是饮料，不是洗衣后的水，与“冲厕所”的用途冲突。", "汽油": "搭配：洗衣服后的水才说“用来冲厕所”，汽油是危险液体，不能这样使用。"}, "sentence_index": 0, "correct_answer": "废水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这桶废水清澈透明，很干净。", "explanation": "这里应该用〈清水〉。废水是用过、受污染的水，不会清澈透明，清水才干净。"}, {"text": "早上他用废水刷牙。", "explanation": "这里应该用〈自来水〉。废水受污染，刷牙要用干净的自来水。"}, {"text": "清晨，草叶上挂满了废水。", "explanation": "这里应该用〈露水〉。废水是用过、受污染的水，清晨草叶上的水珠应是露水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废水", "is_correct": true, "explanation": "废水：符合句意，指黑色的、受污染的水流进大河。"}, {"text": "青草", "is_correct": false, "explanation": "体貌：青草是绿色的，与句中“黑色”的外观相冲突。"}, {"text": "白雪", "is_correct": false, "explanation": "体貌：白雪是白色的，与句中“黑色”的外观相冲突。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水通常清澈，不会是黑色的，与句意冲突。"}], "explanations": {"废水": "废水：符合句意，指黑色的、受污染的水流进大河。", "青草": "体貌：青草是绿色的，与句中“黑色”的外观相冲突。", "白雪": "体貌：白雪是白色的，与句中“黑色”的外观相冲突。", "饮用水": "语义：饮用水通常清澈，不会是黑色的，与句意冲突。"}, "sentence_index": 6, "correct_answer": "废水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她哭得满脸都是废水。", "explanation": "这里应该用〈泪水〉。废水是用过、受污染的水，哭出来的眼泪应说泪水。"}, {"text": "运动后，他的脸上全是废水。", "explanation": "这里应该用〈汗水〉。废水指用过、受污染的水，运动后脸上的水应是汗水。"}, {"text": "山坡上流着融化的废水。", "explanation": "这里应该用〈雪水〉。废水是用过、受污染的水，融化的雪水应说雪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把用过的一块废水装进桶里，拿去浇花。", "corrected_sentence": "他把用过的废水装进桶里，拿去浇花。", "error_description": "量词错误：“块”用于块状的固体，废水是液体，且此处泛指，不应加“一块”，应说“用过的废水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些废水我们处理着很多次。", "corrected_sentence": "这些废水我们处理过很多次。", "error_description": "体标错误：“着”表示动作正在进行，不能用于“很多次”这类已发生的经历，应用“过”，说“处理过很多次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贴水", "is_correct": true, "explanation": "正确：金融术语，与“升水”构成标准的反义关系，指一种钱比另一种钱便宜。"}, {"text": "保持", "is_correct": false, "explanation": "与“升水”无反义关系，“保持”指维持原状。"}, {"text": "结算", "is_correct": false, "explanation": "与“升水”无反义关系，“结算”指计算并支付款项。"}, {"text": "报价", "is_correct": false, "explanation": "与“升水”无反义关系，“报价”指给出价格，不表示价格的升降方向。"}], "correct_answer": "贴水", "explanations": {"贴水": "正确：金融术语，与“升水”构成标准的反义关系，指一种钱比另一种钱便宜。", "保持": "与“升水”无反义关系，“保持”指维持原状。", "结算": "与“升水”无反义关系，“结算”指计算并支付款项。", "报价": "与“升水”无反义关系，“报价”指给出价格，不表示价格的升降方向。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贴水", "is_correct": true, "explanation": "正确：金融术语，与“升水”构成标准的反义关系。"}, {"text": "持平", "is_correct": false, "explanation": "与“升水”无反义关系，“持平”指价格不变。"}, {"text": "汇兑", "is_correct": false, "explanation": "与“升水”无反义关系，“汇兑”指货币兑换行为。"}, {"text": "支付", "is_correct": false, "explanation": "与“升水”无反义关系，“支付”指付款行为，不表示价格方向。"}], "correct_answer": "贴水", "explanations": {"贴水": "正确：金融术语，与“升水”构成标准的反义关系。", "持平": "与“升水”无反义关系，“持平”指价格不变。", "汇兑": "与“升水”无反义关系，“汇兑”指货币兑换行为。", "支付": "与“升水”无反义关系，“支付”指付款行为，不表示价格方向。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "升水就是换钱的时候，一种钱比另一种钱更值钱，要多给一点。", "primary_collocate": null, "pronunciation": "shēng shuǐ", "ipa": "ʂɤŋ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "换钱的时候，这种钱升水，要多给一点。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美元对人民币升水，换钱更贵。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问银行：“今天欧元升水吗？”", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远期日元升水，所以明年换钱要多给钱。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民币对英镑最近一直在升水，换钱要多给一点。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行告诉我，英镑现在升水了。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为美元升水，我换钱多花了一百块。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问银行，美元是不是还在升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港币升水，去香港旅行要多带钱。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行说，下个月欧元会升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升水了", "label": "体标"}, {"form": "升水率", "label": "复合"}], "register": "专业", "sense_fingerprint": "换钱时一种钱更值钱·要多给一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升水", "is_correct": true, "explanation": "正确：shēng shuǐ，换钱时一种钱更值钱，需要多给一点。"}, {"text": "省水", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约用水。"}, {"text": "圣水", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是宗教中的神圣的水。"}, {"text": "山水", "is_correct": false, "explanation": "shān 与 shēng 韵母不同，意思是山和水、风景。"}, {"text": "深水", "is_correct": false, "explanation": "shēn 与 shēng 的韵尾不同（n 与 ng），意思是水很深。"}], "explanations": {"升水": "正确：shēng shuǐ，换钱时一种钱更值钱，需要多给一点。", "省水": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约用水。", "圣水": "shèng（第四声）与 shēng（第一声）声调不同，意思是宗教中的神圣的水。", "山水": "shān 与 shēng 韵母不同，意思是山和水、风景。", "深水": "shēn 与 shēng 的韵尾不同（n 与 ng），意思是水很深。"}, "sentence_index": null, "correct_answer": "升水"}, "level_3": {"options": [{"text": "升水", "is_correct": true, "explanation": "正确：换钱时一种钱更值钱，要多给一点。"}, {"text": "贴水", "is_correct": false, "explanation": "语义：贴水指价格低于标准，换钱时会少给，与“要多给一点”矛盾。"}, {"text": "出汗", "is_correct": false, "explanation": "语义：“出汗”与换钱的价格变化无关，语义不合。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”不能用来描述钱的价值变化，搭配不成立。"}], "explanations": {"升水": "正确：换钱时一种钱更值钱，要多给一点。", "贴水": "语义：贴水指价格低于标准，换钱时会少给，与“要多给一点”矛盾。", "出汗": "语义：“出汗”与换钱的价格变化无关，语义不合。", "洗澡": "搭配：“洗澡”不能用来描述钱的价值变化，搭配不成立。"}, "sentence_index": 0, "correct_answer": "升水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市的牛奶今年升水了。", "explanation": "这里应该用〈涨价〉。升水是金融术语，商品涨价不用“升水”。"}, {"text": "河里的水升水了，我们要赶快撤离。", "explanation": "这里应该用〈涨水〉。“升水”不指水位上升，用于水位语义不合。"}, {"text": "我买的股票今天升水了。", "explanation": "这里应该用〈上涨〉。股价上涨不用“升水”，升水是金融术语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升水", "is_correct": true, "explanation": "正确：美元升水，换钱时要多花钱，符合“多花了一百块”的语境。"}, {"text": "贴水", "is_correct": false, "explanation": "语义：贴水会让换钱更便宜，与“多花了一百块”矛盾。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与换钱的价格无关，无法作为“因为”的原因。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“美元感冒”不能构成搭配，语义也不合。"}], "explanations": {"升水": "正确：美元升水，换钱时要多花钱，符合“多花了一百块”的语境。", "贴水": "语义：贴水会让换钱更便宜，与“多花了一百块”矛盾。", "下雨": "语义：“下雨”与换钱的价格无关，无法作为“因为”的原因。", "感冒": "搭配：“美元感冒”不能构成搭配，语义也不合。"}, "sentence_index": 6, "correct_answer": "升水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的孩子这次考试升水了。", "explanation": "这里应该用〈进步〉。升水是金融术语，成绩提高不用“升水”。"}, {"text": "妈妈的工资今年升水了。", "explanation": "这里应该用〈涨工资〉。升水是金融术语，工资增加不用“升水”。"}, {"text": "这座山的高度下周会升水。", "explanation": "这里应该用〈增高〉。山体高度变化不用“升水”，升水是金融术语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天英镑很升水，换钱要多给一点。", "corrected_sentence": "今天英镑升水，换钱要多给一点。", "error_description": "“升水”是动词，前面不能直接加程度副词“很”。错误形式“英镑很升水”，正确形式“英镑升水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个月美元可能被升水。", "corrected_sentence": "下个月美元可能升水。", "error_description": "“升水”表示价格自行上升，不能用“被”字句。错误形式“可能被升水”，正确形式“可能升水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
