INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物内部包含某种成分或意思。", "primary_collocate": null, "pronunciation": "hán yǒu", "ipa": "xan˧˥ i̯oʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "牛奶含有很多蛋白质。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果含有丰富的维生素。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶饮料含有很多糖，少喝一点。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水里含有盐。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话含有很深的意思。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿茶含有很多对身体有益的成分。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药含有酒精，孩子不能吃。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋含有人需要的营养。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书含有很多有用的知识。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种咖啡含有一定量的咖啡因。", "target_word": "含有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物内部包含某种成分或意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含有", "is_correct": true, "explanation": "“含有”表示物质内部包含某种成分，与“牛奶……很多蛋白质”相合。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”的宾语多是话语，不能接“蛋白质”。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌落，与物质的成分无关，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，不能表示物质包含成分。"}], "explanations": {"含有": "“含有”表示物质内部包含某种成分，与“牛奶……很多蛋白质”相合。", "讲": "搭配：“讲”的宾语多是话语，不能接“蛋白质”。", "摔": "语义：“摔”指跌落，与物质的成分无关，句子说不通。", "唱": "语义：“唱”指发出歌声，不能表示物质包含成分。"}, "sentence_index": 0, "correct_answer": "含有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家含有三口人。", "explanation": "这里应该用〈有〉。有可用于拥有或存在人、物，含有指事物内部包含成分，家里的人不说含有。"}, {"text": "他含有很多行李。", "explanation": "这里应该用〈携带〉。携带指随身拿着或带着东西，含有指事物内部包含成分，人不说含有行李。"}, {"text": "这间教室含有三十个学生。", "explanation": "这里应该用〈容纳〉。容纳指空间能装下人或物，含有指物质或成分内部包含，教室不说含有学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含有", "is_correct": true, "explanation": "“含有”表示药物里包含酒精，与“孩子不能吃”的提醒相合。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“酒精”作宾语。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，与药物的成分无关。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掷，不能表示药物里包含酒精。"}], "explanations": {"含有": "“含有”表示药物里包含酒精，与“孩子不能吃”的提醒相合。", "跑": "配价：“跑”是不及物动词，不能带“酒精”作宾语。", "踢": "语义：“踢”是用脚击打，与药物的成分无关。", "扔": "语义：“扔”指抛掷，不能表示药物里包含酒精。"}, "sentence_index": 6, "correct_answer": "含有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他含有一座大房子。", "explanation": "这里应该用〈拥有〉。拥有指占有财物，含有指事物内部包含成分，人不说含有房子。"}, {"text": "他含有很多工作。", "explanation": "这里应该用〈承担〉。承担指接受并负责某项任务，含有指包含成分，不能说含有工作。"}, {"text": "这位老师含有丰富的经验。", "explanation": "这里应该用〈具有〉。具有指具备某种特点或能力，含有指物质内部包含，人的经验不用含有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯牛奶含有有一种重要的营养。", "corrected_sentence": "这杯牛奶含有一种重要的营养。", "error_description": "重复错误：“含有”是固定的双音节动词，其中的“有”不能重复，多出的“有”应删去，说“这杯牛奶含有一种重要的营养”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种饮料很含有一种天然的甜味。", "corrected_sentence": "这种饮料含有一种天然的甜味。", "error_description": "副词误用：程度副词「很」不能修饰「含有」，应删去「很」，说「这种饮料含有一种天然的甜味」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
