INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26172, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把身体里面不需要的东西送到外面。", "primary_collocate": null, "pronunciation": "pái chū", "ipa": "pʰai˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "多吃蔬菜有助于排出肠道里的废物。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动出汗能排出身体里的水分。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，小结石会自己排出体外。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水能让身体更快排出毒素。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肾脏会把血液里的废物排出。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他咳了几下，把喉咙里的痰排出来了。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气热的时候，人体会通过皮肤排出汗液。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出汗是身体排出热量的方法。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大量喝水后，他不断排出尿液。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，她排出了很多废物。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排出了", "label": "体标"}, {"form": "排出过", "label": "体标"}, {"form": "排出物", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体把废物、水分、毒素等不需要的东西送出体外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排出", "is_correct": true, "explanation": "排出 pái chū：把身体里不需要的东西送到体外，是本题的目标词。"}, {"text": "排除", "is_correct": false, "explanation": "排除 páichú：与“排出”仅第二音节声调不同（chú 为第二声），意思是消除。"}, {"text": "派出", "is_correct": false, "explanation": "派出 pàichū：与“排出”仅第一音节声调不同（pài 为第四声），意思是派遣。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出 pāichū：与“排出”仅第一音节声调不同（pāi 为第一声），意思是拍摄得到。"}], "explanations": {"排出": "排出 pái chū：把身体里不需要的东西送到体外，是本题的目标词。", "排除": "排除 páichú：与“排出”仅第二音节声调不同（chú 为第二声），意思是消除。", "派出": "派出 pàichū：与“排出”仅第一音节声调不同（pài 为第四声），意思是派遣。", "拍出": "拍出 pāichū：与“排出”仅第一音节声调不同（pāi 为第一声），意思是拍摄得到。"}, "sentence_index": null, "correct_answer": "排出"}, "level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "排出：符合句意，表示肠道里的废物被送出体外。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：咀嚼针对食物，废物不能被咀嚼，与句意冲突。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：“吸收”指吸取有益物质，不说吸收废物。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：吞下肠道里的废物与“有助于”身体健康的语义相悖。"}], "explanations": {"排出": "排出：符合句意，表示肠道里的废物被送出体外。", "咀嚼": "语义：咀嚼针对食物，废物不能被咀嚼，与句意冲突。", "吸收": "搭配：“吸收”指吸取有益物质，不说吸收废物。", "吞下": "语义：吞下肠道里的废物与“有助于”身体健康的语义相悖。"}, "sentence_index": 0, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种可能性已经排出了，我们可以放心。", "explanation": "这里应该用〈排除〉。排出用于废物、水分等送出体外，可能性要用排除。"}, {"text": "吃了这个药，他很快就排出了感冒。", "explanation": "这里应该用〈治愈〉。排出指把废物送出体外，疾病要用治愈。"}, {"text": "妈妈终于排出了家里的矛盾。", "explanation": "这里应该用〈解决〉。排出指把废物送出体外，矛盾要用解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "排出：符合句意，表示汗液通过皮肤被送出体外。"}, {"text": "吸入", "is_correct": false, "explanation": "搭配：“吸入”说气体进入呼吸道，皮肤不吸入汗液。"}, {"text": "喝", "is_correct": false, "explanation": "语义：皮肤不能“喝”，与“通过皮肤”的语义冲突。"}, {"text": "饮用", "is_correct": false, "explanation": "语义：汗液不能“饮用”，与句意冲突。"}], "explanations": {"排出": "排出：符合句意，表示汗液通过皮肤被送出体外。", "吸入": "搭配：“吸入”说气体进入呼吸道，皮肤不吸入汗液。", "喝": "语义：皮肤不能“喝”，与“通过皮肤”的语义冲突。", "饮用": "语义：汗液不能“饮用”，与句意冲突。"}, "sentence_index": 6, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "肠道会把食物里的营养排出。", "explanation": "这里应该用〈吸收〉。排出指把体内不需要的东西送到体外，营养要被身体吸收。"}, {"text": "这个磁铁排出了很多铁钉。", "explanation": "这里应该用〈吸引〉。排出指把体内废物送到体外，铁钉被磁铁吸过来要用吸引。"}, {"text": "伤口慢慢排出了新肉。", "explanation": "这里应该用〈长出〉。排出指把体内不需要的东西送到体外，新肉是从伤口长出来的，要用长出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喝水后，身体会把毒素排出了去。", "corrected_sentence": "喝水后，身体会把毒素排出去。", "error_description": "了的位置错误：“了”插在补语“出”和“去”之间不成立。句中有“会”表示一般情况，“排出去”后不加“了”，应说“身体会把毒素排出去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服药后，身体排出了过不少毒素。", "corrected_sentence": "服药后，身体排出了不少毒素。", "error_description": "体标重复：“了”和“过”不能同时用在“排出”后，应说“排出了不少毒素”，去掉多余的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亮", "is_correct": true, "explanation": "亮：与“黑”（表示天色暗）相对，如“天黑”与“天亮”相对，是反义词。"}, {"text": "软", "is_correct": false, "explanation": "与“黑”无反义关系，“软”说质地，与光线无关。"}, {"text": "轻", "is_correct": false, "explanation": "与“黑”无反义关系，“轻”说重量，与光线无关。"}, {"text": "快", "is_correct": false, "explanation": "与“黑”无反义关系，“快”说速度，与光线无关。"}], "correct_answer": "亮", "explanations": {"亮": "亮：与“黑”（表示天色暗）相对，如“天黑”与“天亮”相对，是反义词。", "软": "与“黑”无反义关系，“软”说质地，与光线无关。", "轻": "与“黑”无反义关系，“轻”说重量，与光线无关。", "快": "与“黑”无反义关系，“快”说速度，与光线无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亮", "is_correct": true, "explanation": "亮：与“黑”（表示天色暗）相对，如“天黑”与“天亮”相对，是反义词。"}, {"text": "硬", "is_correct": false, "explanation": "与“黑”无反义关系，“硬”说质地，与光线无关。"}, {"text": "远", "is_correct": false, "explanation": "与“黑”无反义关系，“远”说距离，与光线无关。"}, {"text": "重", "is_correct": false, "explanation": "与“黑”无反义关系，“重”说重量，与光线无关。"}], "correct_answer": "亮", "explanations": {"亮": "亮：与“黑”（表示天色暗）相对，如“天黑”与“天亮”相对，是反义词。", "硬": "与“黑”无反义关系，“硬”说质地，与光线无关。", "远": "与“黑”无反义关系，“远”说距离，与光线无关。", "重": "与“黑”无反义关系，“重”说重量，与光线无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有光亮，光线昏暗，像夜晚的天空那样。", "primary_collocate": null, "pronunciation": "hēi", "ipa": "xei̯˥", "syllable_count": 1, "sentences": [{"text": "夜晚的天空黑得像一块大布。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚没有月亮，天空特别黑。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，路上的灯都亮了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电以后，房间里一下子变黑了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜很黑，我们只好打开手电。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的晚上，不到六点天就黑了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云越来越厚，天空黑得像要下雨。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太黑了，你一个人别出去。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山以后，海面慢慢变黑了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的海很黑，船上要开着灯。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黑黑的", "label": "重叠"}, {"form": "漆黑", "label": "复合"}, {"form": "黑暗", "label": "复合"}], "register": "中性", "sense_fingerprint": "黑：像夜空一样暗，没有光亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确答案。黑 hēi（第一声），意思是没有光亮、像夜空一样暗。"}, {"text": "非", "is_correct": false, "explanation": "fēi（第一声）与 hēi 声母不同（f／h），意思是不是。"}, {"text": "嗨", "is_correct": false, "explanation": "hāi（第一声）与 hēi 韵母不同（ai／ei），意思是打招呼时说的“嗨”。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 hēi 声母不同（b／h），意思是悲伤。"}, {"text": "哼", "is_correct": false, "explanation": "hēng（第一声）与 hēi 韵母不同（eng／ei），意思是哼唱。"}], "explanations": {"黑": "正确答案。黑 hēi（第一声），意思是没有光亮、像夜空一样暗。", "非": "fēi（第一声）与 hēi 声母不同（f／h），意思是不是。", "嗨": "hāi（第一声）与 hēi 韵母不同（ai／ei），意思是打招呼时说的“嗨”。", "悲": "bēi（第一声）与 hēi 声母不同（b／h），意思是悲伤。", "哼": "hēng（第一声）与 hēi 韵母不同（eng／ei），意思是哼唱。"}, "sentence_index": null, "correct_answer": "黑"}, "level_3": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确。黑：夜空无光、颜色深暗，与“像一块大布”的比喻相符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容夜空。"}, {"text": "白", "is_correct": false, "explanation": "语义：夜空不是白色的，“白”与“夜晚”的语义相矛盾。"}, {"text": "尖", "is_correct": false, "explanation": "搭配：“尖”形容末端细而锐利，不用来形容夜空。"}], "explanations": {"黑": "正确。黑：夜空无光、颜色深暗，与“像一块大布”的比喻相符。", "甜": "搭配：“甜”形容味道，不用来形容夜空。", "白": "语义：夜空不是白色的，“白”与“夜晚”的语义相矛盾。", "尖": "搭配：“尖”形容末端细而锐利，不用来形容夜空。"}, "sentence_index": 0, "correct_answer": "黑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上的星星很黑，照得夜空一闪一闪的。", "explanation": "这里应该用〈亮〉。星星发光时形容光亮用“亮”，“黑”表示没有光亮的颜色，不能用来说发光的星星。"}, {"text": "月光很黑，照在湖面上。", "explanation": "这里应该用〈淡〉。月光柔和时用“淡”，“黑”说物体的颜色，月光不能说是黑的。"}, {"text": "屏幕的光很黑，看久了眼睛会累。", "explanation": "这里应该用〈暗〉。说光线的明暗用“暗”，“黑”不用来形容光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确答案。黑 hēi（第一声），意思是没有光亮、像夜空一样暗。"}, {"text": "威", "is_correct": false, "explanation": "wēi（第一声）与 hēi 声母不同（w／h），意思是威严。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 hēi 声母不同（b／h），意思是杯子。"}, {"text": "灰", "is_correct": false, "explanation": "huī（第一声）与 hēi 韵母不同（ui／ei），意思是灰色或灰尘。"}], "explanations": {"黑": "正确答案。黑 hēi（第一声），意思是没有光亮、像夜空一样暗。", "威": "wēi（第一声）与 hēi 声母不同（w／h），意思是威严。", "杯": "bēi（第一声）与 hēi 声母不同（b／h），意思是杯子。", "灰": "huī（第一声）与 hēi 韵母不同（ui／ei），意思是灰色或灰尘。"}, "sentence_index": null, "correct_answer": "黑"}, "level_3": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确。黑：云层厚、天色暗，与“像要下雨”相符。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：要下雨时天空不是蓝色的，“蓝”与“像要下雨”的语义相矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，天空不说甜，“天空甜得像要下雨”搭配不当。"}, {"text": "干", "is_correct": false, "explanation": "语义：“干”指干燥，与“要下雨”的潮湿景象相矛盾。"}], "explanations": {"黑": "正确。黑：云层厚、天色暗，与“像要下雨”相符。", "蓝": "语义：要下雨时天空不是蓝色的，“蓝”与“像要下雨”的语义相矛盾。", "甜": "搭配：“甜”说味道，天空不说甜，“天空甜得像要下雨”搭配不当。", "干": "语义：“干”指干燥，与“要下雨”的潮湿景象相矛盾。"}, "sentence_index": 6, "correct_answer": "黑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心很黑，常常骗朋友的钱。", "explanation": "这里“黑”表示心狠、不讲良心，是另一个义项。本词指没有光亮，不用来形容人的心肠。"}, {"text": "他做黑生意，已经被查过两次。", "explanation": "这里“黑”表示非法、不正当，是另一个义项。本词指没有光亮，不表示违法。"}, {"text": "一听到这个消息，我眼前一黑。", "explanation": "这里“黑”表示眼前发晕、看不清，是另一个义项。本词指环境没有光亮，不表示身体感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里的山路黑吓人。", "corrected_sentence": "夜里的山路黑得吓人。", "error_description": "应为“黑得吓人”。“黑”是谓语，后面要用“得”引出补语“吓人”说明程度，不能直接说“黑吓人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海面渐渐黑出来了。", "corrected_sentence": "海面渐渐黑下来了。", "error_description": "错误：“黑出来”，正确：“黑下来”。表示光线逐渐变暗，应用趋向补语“下来”，不能用“出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
