INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "化学物质是构成各种东西的物质，比如水和盐。", "primary_collocate": null, "pronunciation": "huà xué wù zhì", "ipa": "xwa˥˩ ɕɥe˧˥ u˥˩ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "水和盐都是化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上的东西都由化学物质组成。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了几种化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖是我们每天都吃的化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里也有很多化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，我们学习了各种化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐和水混在一起，是两种化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里的化学物质是白色的。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验时，我把两种化学物质放在一起。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的玩具里也有化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种化学物质", "label": "量词"}, {"form": "有害化学物质", "label": "复合"}], "register": "中性", "sense_fingerprint": "组成各种东西的基本物质，如水和盐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：水和盐不是颜色，句子说的是它们属于哪一类东西。"}, {"text": "化学物质", "is_correct": true, "explanation": "正确。水和盐都是构成各种东西的物质，即化学物质。"}, {"text": "动物", "is_correct": false, "explanation": "语义：水和盐不是动物，不能归入动物类。"}, {"text": "金属", "is_correct": false, "explanation": "语义：水和盐不是金属，不能归入金属类。"}], "explanations": {"颜色": "语义：水和盐不是颜色，句子说的是它们属于哪一类东西。", "化学物质": "正确。水和盐都是构成各种东西的物质，即化学物质。", "动物": "语义：水和盐不是动物，不能归入动物类。", "金属": "语义：水和盐不是金属，不能归入金属类。"}, "sentence_index": 0, "correct_answer": "化学物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，化学物质考得很好。", "explanation": "这里应该用〈化学〉。“化学”是学科名称，可以说考得好；“化学物质”指物质，不能作为科目。"}, {"text": "我的叔叔是一位化学物质。", "explanation": "这里应该用〈化学家〉。“化学物质”指物质，不指人；说人应该用“化学家”。"}, {"text": "桌上放着一根化学物质。", "explanation": "这里应该用〈种〉。“根”用于细长的东西，化学物质不用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是物质，盐和水不能说成“两种歌曲”。"}, {"text": "星星", "is_correct": false, "explanation": "语义：盐和水不是天体，不能说成“两种星星”。"}, {"text": "化学物质", "is_correct": true, "explanation": "正确。盐和水都是化学物质，句中说的正是这一类别。"}, {"text": "植物", "is_correct": false, "explanation": "语义：水和盐不是植物，不能归入植物类。"}], "explanations": {"歌曲": "语义：歌曲不是物质，盐和水不能说成“两种歌曲”。", "星星": "语义：盐和水不是天体，不能说成“两种星星”。", "化学物质": "正确。盐和水都是化学物质，句中说的正是这一类别。", "植物": "语义：水和盐不是植物，不能归入植物类。"}, "sentence_index": 6, "correct_answer": "化学物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两种药水一混合就发生了化学物质。", "explanation": "这里应该用〈化学反应〉。发生的是反应，“化学物质”是物质，不能说“发生化学物质”。"}, {"text": "厨房里停着一辆化学物质。", "explanation": "这里应该用〈种〉。“辆”用于车辆，化学物质不能用“辆”计量。"}, {"text": "工人把一只化学物质倒进了水池。", "explanation": "这里应该用〈种〉。“只”用于动物或成对、成个的东西，化学物质不用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把一只化学物质放在桌上。", "corrected_sentence": "老师把一种化学物质放在桌上。", "error_description": "量词错误：“化学物质”前应用“种”，“只”用于动物或成对、成个的东西，不能用于物质名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张有毒的化学物质要分开存放。", "corrected_sentence": "这种有毒的化学物质要分开存放。", "error_description": "量词错误：“化学物质”前应用“种”，“张”用于纸、桌子等扁平的东西，不能用于物质名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
