INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被弄脏、不能饮用的水。", "primary_collocate": null, "pronunciation": "wū shuǐ", "ipa": "u˨˩˦ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条小河里全是污水，千万别喝。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子踩进了路边的污水里。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河的污水发黑，我们不能用它洗菜。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的污水从管子里流出去了。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鞋掉进污水里，湿透了。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，那里有一滩污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用桶把污水倒进了下水道。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水的颜色是黑的，还有臭味。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说不要玩路上的污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完车后，地上留下了污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一滩污水", "label": "量词"}, {"form": "工业污水", "label": "复合"}, {"form": "污水处理", "label": "复合"}], "register": "中性", "sense_fingerprint": "很脏、不能喝的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污水", "is_correct": true, "explanation": "正确。“全是污水，千万别喝”前后一致，污水不能喝。"}, {"text": "矿泉水", "is_correct": false, "explanation": "语义：矿泉水可以喝，与“千万别喝”矛盾。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是可以喝的饮品，与“千万别喝”矛盾，而且河里不会全是牛奶。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：河里不说“全是空气”，“全是”一般不用来形容空气。"}], "explanations": {"污水": "正确。“全是污水，千万别喝”前后一致，污水不能喝。", "矿泉水": "语义：矿泉水可以喝，与“千万别喝”矛盾。", "牛奶": "语义：牛奶是可以喝的饮品，与“千万别喝”矛盾，而且河里不会全是牛奶。", "空气": "搭配：河里不说“全是空气”，“全是”一般不用来形容空气。"}, "sentence_index": 0, "correct_answer": "污水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶污水很干净，你可以放心喝。", "explanation": "这里应该用〈矿泉水〉。污水很脏、不能喝，干净可以喝的水要说“矿泉水”。"}, {"text": "厨房里有一块污水。", "explanation": "这里应该用量词〈滩〉。污水成片积在地上要说“一滩”，不说“一块”。"}, {"text": "这条小河的污水干干净净，鱼儿都能看清。", "explanation": "这里应该用〈清水〉。“污水”指脏脏的水，干净透明的水要说“清水”，不说“污水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污水", "is_correct": true, "explanation": "正确。“用桶把污水倒进了下水道”符合污水被排掉的情境。"}, {"text": "砖头", "is_correct": false, "explanation": "搭配：砖头是固体，不能用桶“倒”，“把……倒进下水道”不能搭配固体砖头。"}, {"text": "火焰", "is_correct": false, "explanation": "搭配：火焰不能用桶盛装和倒出，“用桶把火焰倒进下水道”不通。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云悬在天上，不能装进桶里倒进下水道。"}], "explanations": {"污水": "正确。“用桶把污水倒进了下水道”符合污水被排掉的情境。", "砖头": "搭配：砖头是固体，不能用桶“倒”，“把……倒进下水道”不能搭配固体砖头。", "火焰": "搭配：火焰不能用桶盛装和倒出，“用桶把火焰倒进下水道”不通。", "白云": "语义：白云悬在天上，不能装进桶里倒进下水道。"}, "sentence_index": 6, "correct_answer": "污水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地上留下了很多美味的污水。", "explanation": "这里应该用〈汤〉。“污水”指脏水、不能喝，不能说成美味的食物，美味的应该是“汤”等食物。"}, {"text": "厨房里飘来一阵香甜的污水味，闻着让人很有食欲。", "explanation": "这里应该用〈饭菜〉。“污水”指脏水，不会香甜；有香味、让人有食欲的要说“饭菜的香味”。"}, {"text": "我口渴了，妈妈给我倒了一杯甜甜的污水。", "explanation": "这里应该用〈果汁〉。“污水”指脏水、不能喝，甜甜的、可以喝的饮料要说“果汁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边的一块污水有点臭。", "corrected_sentence": "路边的一滩污水有点臭。", "error_description": "错误：“一块污水”，正确：“一滩污水”。污水成片积在地上应该用量词“滩”，不用“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桶里装着一个污水，别碰。", "corrected_sentence": "桶里装着一桶污水，别碰。", "error_description": "错误：「一个污水」，正确：「一桶污水」。污水是不可数的液体，不能用「个」计量，应用「桶」等容器量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
