INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "告诉大家一种商品或事情，让更多人知道。", "primary_collocate": null, "pronunciation": "guǎng gào", "ipa": "kwɑŋ˨˩˦ kɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "电视里正在放一个新广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的大楼挂着很大的广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站看到了一张广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢看牛奶的广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告让大家知道了新电影。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上总是跳出广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在门口贴了一张广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告上说，这家店明天开门。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告很短，也很好笑。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看了广告，就去超市买了。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一则广告", "label": "量词"}, {"form": "广告牌", "label": "复合"}, {"form": "广告词", "label": "复合"}], "register": "中性", "sense_fingerprint": "告诉大家某商品或事情，让更多人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广告", "is_correct": true, "explanation": "广告：可以放映的宣传内容，与“放”搭配，符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“放”通常用于节目、影片、广告等，面包不能放映。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以播放的内容，句子说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不能在电视里放映。"}], "explanations": {"广告": "广告：可以放映的宣传内容，与“放”搭配，符合句意。", "面包": "搭配：“放”通常用于节目、影片、广告等，面包不能放映。", "石头": "语义：石头不是可以播放的内容，句子说不通。", "河流": "语义：河流是自然景物，不能在电视里放映。"}, "sentence_index": 0, "correct_answer": "广告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上写了一个广告：明天放假。", "explanation": "这里应该用〈通知〉。广告是宣传商品或活动的，告诉学生明天放假要用通知。"}, {"text": "爸爸每天晚上看电视里的广告，了解国家大事。", "explanation": "这里应该用〈新闻〉。了解国家大事要看新闻，广告是宣传商品的。"}, {"text": "这台洗衣机的广告写着怎么一步一步使用它。", "explanation": "这里应该用〈说明书〉。介绍使用方法的是说明书，广告是让人知道并购买商品的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广告", "is_correct": true, "explanation": "广告：可以贴出来的宣传材料，与“贴了一张”搭配，符合句意。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“地毯”通常是铺的，不说贴。"}, {"text": "床", "is_correct": false, "explanation": "语义：床是卧具，贴在门口说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是立体的家具，不是可以贴上去的平面物品。"}], "explanations": {"广告": "广告：可以贴出来的宣传材料，与“贴了一张”搭配，符合句意。", "地毯": "搭配：“地毯”通常是铺的，不说贴。", "床": "语义：床是卧具，贴在门口说不通。", "桌子": "语义：桌子是立体的家具，不是可以贴上去的平面物品。"}, "sentence_index": 6, "correct_answer": "广告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭店送来一张广告，上面列着我们点的菜和总价。", "explanation": "这里应该用〈账单〉。广告是宣传商品的材料，不会列出顾客点的菜和总价，此处应换成账单。"}, {"text": "报纸上有一则广告，说昨晚发生了火灾。", "explanation": "这里应该用〈报道〉。广告是为了让人知道商品或活动，不用来客观报道已经发生的火灾。"}, {"text": "墙上贴了一则广告，宣布村里的老人去世了。", "explanation": "这里应该用〈讣告〉。广告用于推广商品或活动，不用来宣布去世。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公交车上贴了一只广告。", "corrected_sentence": "公交车上贴了一张广告。", "error_description": "错误：“一只广告”，正确：“一张广告”。“只”是用于动物的量词，贴出来的广告应该用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈以前看了过广告，觉得很好笑。", "corrected_sentence": "妈妈以前看过广告，觉得很好笑。", "error_description": "错误：“看了过广告”，正确：“看过广告”。“了”和“过”都是表示动作经历或完成的体标，不能同时用在同一个动词后面，去掉“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微弱", "is_correct": true, "explanation": "微弱指力量小、程度浅，与“强烈”意思相反，构成反义。"}, {"text": "美丽", "is_correct": false, "explanation": "美丽形容外表或景色好看，与“强烈”的程度意义无关，不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容头脑反应快，与“强烈”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污物，与“强烈”的程度意义无关，不构成反义。"}], "correct_answer": "微弱", "explanations": {"微弱": "微弱指力量小、程度浅，与“强烈”意思相反，构成反义。", "美丽": "美丽形容外表或景色好看，与“强烈”的程度意义无关，不构成反义。", "聪明": "聪明形容头脑反应快，与“强烈”没有反义关系。", "干净": "干净指没有污物，与“强烈”的程度意义无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻微", "is_correct": true, "explanation": "轻微指程度浅、很小，与“强烈”的程度深意思相反，构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指事情或结构头绪多，与“强烈”的程度意义无关，不构成反义。"}, {"text": "善良", "is_correct": false, "explanation": "善良形容品性好，与“强烈”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、分明，不是“强烈”的反义词。"}], "correct_answer": "轻微", "explanations": {"轻微": "轻微指程度浅、很小，与“强烈”的程度深意思相反，构成反义。", "复杂": "复杂指事情或结构头绪多，与“强烈”的程度意义无关，不构成反义。", "善良": "善良形容品性好，与“强烈”没有反义关系。", "清楚": "清楚指明白、分明，不是“强烈”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示力量大或程度深，比如风很大、感情很深。", "primary_collocate": null, "pronunciation": "qiáng liè", "ipa": "tɕʰjɑŋ˧˥ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "外面的风非常强烈，树都被吹弯了。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对家乡有强烈的感情。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光太强烈了，我睁不开眼睛。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她强烈希望能见到爸爸。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光很强烈，你要涂防晒霜。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一种强烈的感觉，今天会下雨。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的感情非常强烈。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到音乐，我心里有强烈的感动。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有一股强烈的香味。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种痛苦的感觉非常强烈。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强烈地", "label": "副词形式"}, {"form": "强烈反对", "label": "复合"}], "register": "中性", "sense_fingerprint": "力量大或程度深，如风大、感情深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强烈", "is_correct": true, "explanation": "强烈：形容风的力量大，与“非常”搭配，符合树被吹弯的语境。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容物体又大又重、不灵活，不能形容风。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指地方没有人、不热闹，不能说明风的力量。"}, {"text": "清淡", "is_correct": false, "explanation": "语义：“清淡”指味道或颜色淡，不能形容风大。"}], "explanations": {"强烈": "强烈：形容风的力量大，与“非常”搭配，符合树被吹弯的语境。", "笨重": "语义：“笨重”形容物体又大又重、不灵活，不能形容风。", "冷清": "语义：“冷清”指地方没有人、不热闹，不能说明风的力量。", "清淡": "语义：“清淡”指味道或颜色淡，不能形容风大。"}, "sentence_index": 0, "correct_answer": "强烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国是一个强烈的国家。", "explanation": "这里应该用〈强大〉。强烈只用于感受、光线、味道等程度深的事物，不用来形容国家的实力。"}, {"text": "这座桥很强烈，车辆都能安全通过。", "explanation": "这里应该用〈牢固〉。强烈说的是程度深，不用来形容桥梁结不结实。"}, {"text": "他犯的这个错误很强烈。", "explanation": "这里应该用〈严重〉。强烈形容感受或作用的程度，不用来说错误的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强烈", "is_correct": true, "explanation": "强烈：修饰“感情”，说明感情的程度深，与“非常”搭配，符合句意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描述身高或位置低，不能用来形容感情的程度。"}, {"text": "干燥", "is_correct": false, "explanation": "体貌：“干燥”多指空气、皮肤或土地，不用于形容感情。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”指质地不光滑或做事不细致，用来形容感情说不通。"}], "explanations": {"强烈": "强烈：修饰“感情”，说明感情的程度深，与“非常”搭配，符合句意。", "矮": "体貌：“矮”描述身高或位置低，不能用来形容感情的程度。", "干燥": "体貌：“干燥”多指空气、皮肤或土地，不用于形容感情。", "粗糙": "语义：“粗糙”指质地不光滑或做事不细致，用来形容感情说不通。"}, "sentence_index": 6, "correct_answer": "强烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次数学考试的成绩非常强烈。", "explanation": "强烈形容感受、感官或作用的程度深，不用来评价考试成绩；说成绩好要用“高”或“好”。"}, {"text": "我家到学校的距离很强烈。", "explanation": "距离有远近之分，不能用“强烈”来形容，应说“远”或“近”。"}, {"text": "这辆车的价格非常强烈。", "explanation": "价格有高低之分，不能用“强烈”来形容，应说“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到音乐后，她的感情强烈地起来了。", "corrected_sentence": "听到音乐后，她的感情强烈起来了。", "error_description": "错误：“强烈地起来”，正确：“强烈起来”。“强烈起来”是形容词加趋向补语，表示程度逐渐增强；“地”不能插在形容词和补语“起来”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗外的阳光很非常强烈，我们拉上了窗帘。", "corrected_sentence": "窗外的阳光非常强烈，我们拉上了窗帘。", "error_description": "错误：“很非常强烈”，正确：“非常强烈”。“很”和“非常”都是程度副词，不能同时修饰同一个形容词，只保留“非常”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
