INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物品的样子或样式。", "primary_collocate": null, "pronunciation": "kuǎn shì", "ipa": "kʰwan˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这张桌子的款式很简单，没有多余的花。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢简单的款式，不喜欢太复杂的。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家眼镜店有几十种款式可以选。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥买了一辆车，款式和我的一样。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包的颜色一样，可是款式不同。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子款式好看，我想买两个。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看看这些款式，选一个送给奶奶。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘的款式要和房间搭配。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种款式的帽子冬天戴很暖和。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个款式卖得最好。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "新款式", "label": "复合"}], "register": "中性", "sense_fingerprint": "物品的样子、样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff18899e-4ea4-436c-9109-7ad54f9ec2c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "款式", "is_correct": true, "explanation": "款式指物品的样子，“这张桌子的款式很简单”符合句意。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“简单”不能形容“体积”，不能说“体积很简单”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是桌子的外形，说“价格很简单”与句意不合。"}, {"text": "性格", "is_correct": false, "explanation": "语义：桌子没有性格，“性格很简单”与句意不合。"}], "explanations": {"款式": "款式指物品的样子，“这张桌子的款式很简单”符合句意。", "体积": "搭配：“简单”不能形容“体积”，不能说“体积很简单”。", "价格": "语义：价格不是桌子的外形，说“价格很简单”与句意不合。", "性格": "语义：桌子没有性格，“性格很简单”与句意不合。"}, "sentence_index": 0, "correct_answer": "款式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的款式很认真，从不偷懒。", "explanation": "这里应该用〈态度〉。款式指物品的样式，人对事情的态度要用〈态度〉。"}, {"text": "我弟弟的款式很好，大家都喜欢和他玩。", "explanation": "这里应该用〈脾气〉。款式指物品的样子，形容人的性情要用〈脾气〉。"}, {"text": "他的款式很高，在班里是第一名。", "explanation": "这里应该用〈水平〉。款式指物品的样式，人的能力高低要用〈水平〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "款式", "is_correct": true, "explanation": "款式指物品的样式，“请你看看这些款式”符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是可以挑选来送人的东西，与句意不合。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不是可以挑来送给奶奶的物品。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“送给奶奶”的宾语应是礼物，“作业”不能与“送”搭配。"}], "explanations": {"款式": "款式指物品的样式，“请你看看这些款式”符合句意。", "价格": "语义：价格不是可以挑选来送人的东西，与句意不合。", "作者": "语义：作者是人，不是可以挑来送给奶奶的物品。", "作业": "搭配：“送给奶奶”的宾语应是礼物，“作业”不能与“送”搭配。"}, "sentence_index": 6, "correct_answer": "款式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个菜的款式有点咸。", "explanation": "这里应该用〈味道〉。款式指物品的样子，食物的咸淡要说味道。"}, {"text": "他唱歌的款式很好听。", "explanation": "这里应该用〈声音〉。款式指物品的样式，不能说唱歌好不好听。"}, {"text": "明天的款式是晴天。", "explanation": "这里应该用〈天气〉。款式指物品的样子，不能用来说天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢这只款式，它很简单。", "corrected_sentence": "我喜欢这种款式，它很简单。", "error_description": "量词错误：“只”不能修饰款式，应改为“种”或“个”，如“这种款式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服得款式很新，大家都喜欢。", "corrected_sentence": "这件衣服的款式很新，大家都喜欢。", "error_description": "的字误用：“衣服”修饰名词“款式”要用“的”，“得”只用于补语，应说“衣服的款式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
