INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用火把东西变成灰。", "primary_collocate": null, "pronunciation": "shāo diào", "ipa": "ʂaʊ˥ tjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子玩火，把一张旧纸烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把没用的纸放进炉子烧掉。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些木头不能用了，只能烧掉。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把日记本烧掉，不想让别人看到。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火烧掉了他家所有的东西。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灰很多，因为纸都烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把田里的草烧掉，当作肥料。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着说，照片都烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别让火把帐篷烧掉。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把旧椅子拆开，在院子里烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烧掉了", "label": "体标"}, {"form": "烧掉过", "label": "体标"}, {"form": "烧不掉", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "用火把东西烧成灰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff18899e-4ea4-436c-9109-7ad54f9ec2c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烧掉", "is_correct": true, "explanation": "正确：烧掉（shāo diào），指用火把东西变成灰。"}, {"text": "少掉", "is_correct": false, "explanation": "shǎo（第三声）与 shāo（第一声）声调不同，意思是减少掉。"}, {"text": "烧到", "is_correct": false, "explanation": "dào 与 diào 的韵母不同（少了 i），意思是烧到、烧着。"}, {"text": "删掉", "is_correct": false, "explanation": "shān 与 shāo 韵母不同（an 与 ao），意思是删除。"}], "explanations": {"烧掉": "正确：烧掉（shāo diào），指用火把东西变成灰。", "少掉": "shǎo（第三声）与 shāo（第一声）声调不同，意思是减少掉。", "烧到": "dào 与 diào 的韵母不同（少了 i），意思是烧到、烧着。", "删掉": "shān 与 shāo 韵母不同（an 与 ao），意思是删除。"}, "sentence_index": null, "correct_answer": "烧掉"}, "level_3": {"options": [{"text": "烧掉", "is_correct": true, "explanation": "正确：烧掉表示把纸用火烧成灰，符合“孩子玩火”的语境。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”是留着不毁，与“玩火”导致纸被毁的语境不合。"}, {"text": "读完", "is_correct": false, "explanation": "语义：“读完”要求把内容看完，与“玩火”的语境不合。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”指把多页纸订成册，不能用于一张随手拿来玩火的旧纸。"}], "explanations": {"烧掉": "正确：烧掉表示把纸用火烧成灰，符合“孩子玩火”的语境。", "保存": "语义：“保存”是留着不毁，与“玩火”导致纸被毁的语境不合。", "读完": "语义：“读完”要求把内容看完，与“玩火”的语境不合。", "装订": "搭配：“装订”指把多页纸订成册，不能用于一张随手拿来玩火的旧纸。"}, "sentence_index": 0, "correct_answer": "烧掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把汤烧掉了，端给客人。", "explanation": "这里应该用〈烧热〉。烧掉指东西被烧成灰或消失，烧汤只是加热，要用烧热。"}, {"text": "妈妈把饺子烧掉了，盛在碗里。", "explanation": "这里应该用〈煮熟〉。烧掉指燃烧使东西毁坏，煮饺子是用水加热至熟，要用煮熟。"}, {"text": "他把铁丝烧掉了，用来弯成圈。", "explanation": "这里应该用〈烧红〉。烧掉指东西毁坏或消失，铁丝加热到发红要用烧红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烧掉", "is_correct": true, "explanation": "正确：烧掉表示用火把草烧成灰，作为肥料的来源。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是留着观赏或珍存，与“当作肥料”的用途相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是观看赞美，与用作肥料的做法不合。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”多用于房屋或物件，不能与“田里的草”搭配。"}], "explanations": {"烧掉": "正确：烧掉表示用火把草烧成灰，作为肥料的来源。", "收藏": "语义：“收藏”是留着观赏或珍存，与“当作肥料”的用途相反。", "欣赏": "语义：“欣赏”是观看赞美，与用作肥料的做法不合。", "装饰": "搭配：“装饰”多用于房屋或物件，不能与“田里的草”搭配。"}, "sentence_index": 6, "correct_answer": "烧掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸把壶里的水烧掉了，准备泡茶。", "explanation": "这里应该用〈烧开〉。烧掉指东西被烧成灰或消失，烧水只是加热到开，要用烧开。"}, {"text": "饼干烧掉了，黑乎乎的。", "explanation": "这里应该用〈烧焦〉。烧掉指完全变成灰或消失，饼干只是表面变黑，要用烧焦。"}, {"text": "这些砖是窑里烧掉的，很坚固。", "explanation": "这里应该用〈烧制〉。烧掉指东西被烧毁，烧制砖是使其定型，要用烧制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈没把那封旧信烧掉了。", "corrected_sentence": "妈妈没把那封旧信烧掉。", "error_description": "体标错误：“没”否定尚未发生的动作，动词后不能再加“了”。应说“没把那封旧信烧掉”，不能说“没把那封旧信烧掉了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在院子里把烧掉了旧床单。", "corrected_sentence": "妈妈在院子里烧掉了旧床单。", "error_description": "把字误用：“把”字句的“把”后必须有受事名词，“烧掉”前不能只加“把”而没有宾语。应去掉“把”，说“在院子里烧掉了旧床单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
