INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工业区是很多工厂在一起的地方。", "primary_collocate": null, "pronunciation": "gōng yè qū", "ipa": "kʊŋ˥ jɛ˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "工业区是工厂最多的地方。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我舅舅的工厂就在那个工业区里。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业区晚上很安静，白天很吵。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工业区有几十家工厂。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车经过了一个大工业区。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业区离市中心很远。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工业区的一家工厂工作。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业区里的卡车特别多。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离工业区太近，孩子们受影响。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说城东新建了一个工业区。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个工业区", "label": "量词"}, {"form": "工业园区", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多工厂集中在一起的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不是工厂最多的地方。"}, {"text": "工业区", "is_correct": true, "explanation": "正确。“工业区”就是很多工厂聚集在一起的地方，与句意一致。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人休闲的地方，不会是工厂最多的地方。"}, {"text": "厂子", "is_correct": false, "explanation": "语域：“厂子”是口语，指一家工厂，且与这句说明文的语域不合，不能指很多工厂聚集的地方。"}], "explanations": {"学校": "语义：学校是教育机构，不是工厂最多的地方。", "工业区": "正确。“工业区”就是很多工厂聚集在一起的地方，与句意一致。", "公园": "语义：公园是供人休闲的地方，不会是工厂最多的地方。", "厂子": "语域：“厂子”是口语，指一家工厂，且与这句说明文的语域不合，不能指很多工厂聚集的地方。"}, "sentence_index": 0, "correct_answer": "工业区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校旁边有一张工业区。", "explanation": "这里应该用〈个〉或〈片〉。“张”用于纸、桌子等扁平的东西，工业区不能用“张”计量。"}, {"text": "我家的小作坊很小，只是一个工业区。", "explanation": "这里应该用〈工厂〉。工业区指很多工厂聚集的地方，一家小作坊不能叫工业区。"}, {"text": "我们经过了一条工业区。", "explanation": "这里应该用〈个〉。“条”用于河流、道路等细长的东西，不用于区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室里没有工厂，不能说“他在教室的一家工厂工作”。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，不会有工厂，句子说不通。"}, {"text": "工业区", "is_correct": true, "explanation": "正确。“工业区”是很多工厂集中的地方，“他在……的一家工厂工作”指在这一区域中的工厂。"}, {"text": "老窝", "is_correct": false, "explanation": "语域：“老窝”是口语，多指坏人或动物的巢穴，与这句的书面语境不合。"}], "explanations": {"教室": "语义：教室里没有工厂，不能说“他在教室的一家工厂工作”。", "医院": "语义：医院是治病的地方，不会有工厂，句子说不通。", "工业区": "正确。“工业区”是很多工厂集中的地方，“他在……的一家工厂工作”指在这一区域中的工厂。", "老窝": "语域：“老窝”是口语，多指坏人或动物的巢穴，与这句的书面语境不合。"}, "sentence_index": 6, "correct_answer": "工业区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听说城东新建了一盏工业区。", "explanation": "这里应该用〈个〉。“盏”用于灯具，工业区不能用“盏”计量。"}, {"text": "听说城东新建了一辆工业区。", "explanation": "这里应该用〈个〉。“辆”用于车辆，工业区不能用“辆”计量。"}, {"text": "听说城东新建了一位工业区。", "explanation": "这里应该用〈个〉。“位”用于人，工业区不能用“位”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城东有一根新的工业区。", "corrected_sentence": "城东有一个新的工业区。", "error_description": "量词错误：“工业区”应用“个”，“根”用于细长的东西，不能用于计量区域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "南郊正在规划一只工业区。", "corrected_sentence": "南郊正在规划一个工业区。", "error_description": "量词错误：“工业区”应用“个”，“只”用于动物或成对、成个的东西，不能用于区域。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
