INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西用土或别的东西盖住。", "primary_collocate": null, "pronunciation": "mái", "ipa": "mai˧˥", "syllable_count": 1, "sentences": [{"text": "小松鼠把松果埋在树下过冬。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在花盆里埋了几颗豆子。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪把车轮埋住了一半。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在沙子里埋了一个玩具。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水管埋在地下一米深的地方。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗在草地上挖了一个洞，把球埋了起来。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片放进盒子，埋在了河边。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，人们把白菜埋在院子的土里。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些垃圾埋好，别让小动物找到。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的孩子喜欢把自己的腿埋在沙子里。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "埋了", "label": "体标（了）"}, {"form": "埋着", "label": "体标（着）"}, {"form": "埋过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "埋-把东西用土或别的东西盖住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '892e6a23-674a-4223-9c9c-54e9c0f9d361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26192, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋（mái，第二声）：把东西用土或别的东西盖住。"}, {"text": "买", "is_correct": false, "explanation": "买（mǎi，第三声）与埋（mái，第二声）声调不同，意思是购买。"}, {"text": "卖", "is_correct": false, "explanation": "卖（mài，第四声）与埋（mái，第二声）声调不同，意思是出售。"}, {"text": "煤", "is_correct": false, "explanation": "煤（méi）与埋（mái）韵母不同（ei 与 ai），意思是煤炭。"}], "explanations": {"埋": "埋（mái，第二声）：把东西用土或别的东西盖住。", "买": "买（mǎi，第三声）与埋（mái，第二声）声调不同，意思是购买。", "卖": "卖（mài，第四声）与埋（mái，第二声）声调不同，意思是出售。", "煤": "煤（méi）与埋（mái）韵母不同（ei 与 ai），意思是煤炭。"}, "sentence_index": null, "correct_answer": "埋"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“过冬储存”的意思不符。"}, {"text": "埋", "is_correct": true, "explanation": "“埋”指把松果盖入土中收藏，符合“过冬”的语境。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”是放在太阳下弄干，不是收藏过冬。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”是从树上取下，不说“摘在树下”。"}], "explanations": {"扔": "语义：“扔”是丢弃，与“过冬储存”的意思不符。", "埋": "“埋”指把松果盖入土中收藏，符合“过冬”的语境。", "晒": "语义：“晒”是放在太阳下弄干，不是收藏过冬。", "摘": "搭配：“摘”是从树上取下，不说“摘在树下”。"}, "sentence_index": 0, "correct_answer": "埋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙埋在了桌子上。", "explanation": "这里应该用〈放〉。埋指被盖住或藏入下方，钥匙放在桌面上只能说“放”。"}, {"text": "妈妈把饼干埋在了窗台上。", "explanation": "这里应该用〈摆〉。饼干摆在窗台表面，没有被盖住，不能说“埋”。"}, {"text": "他把被子埋在了阳光下。", "explanation": "这里应该用〈晒〉。埋要用土或东西盖住，把被子拿到阳光下只能说“晒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26192, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋（mái，第二声）：把东西用土或别的东西盖住。"}, {"text": "麦", "is_correct": false, "explanation": "麦（mài，第四声）与埋（mái，第二声）声调不同，意思是麦子。"}, {"text": "眉", "is_correct": false, "explanation": "眉（méi）与埋（mái）韵母不同（ei 与 ai），意思是眉毛。"}, {"text": "毛", "is_correct": false, "explanation": "毛（máo）与埋（mái）韵母不同（ao 与 ai），意思是毛发或羽毛。"}], "explanations": {"埋": "埋（mái，第二声）：把东西用土或别的东西盖住。", "麦": "麦（mài，第四声）与埋（mái，第二声）声调不同，意思是麦子。", "眉": "眉（méi）与埋（mái）韵母不同（ei 与 ai），意思是眉毛。", "毛": "毛（máo）与埋（mái）韵母不同（ao 与 ai），意思是毛发或羽毛。"}, "sentence_index": null, "correct_answer": "埋"}, "level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：“切”是割开，不能说“切在河边”，与句意不符。"}, {"text": "埋", "is_correct": true, "explanation": "“埋”指把东西盖入地下，与“放进盒子”后埋在河边的语境相符。"}, {"text": "泼", "is_correct": false, "explanation": "搭配：“泼”多用于水等液体，不能用于照片或盒子。"}, {"text": "晾", "is_correct": false, "explanation": "语义：“晾”是拿出来吹干，与“放进盒子”的收纳不符。"}], "explanations": {"切": "语义：“切”是割开，不能说“切在河边”，与句意不符。", "埋": "“埋”指把东西盖入地下，与“放进盒子”后埋在河边的语境相符。", "泼": "搭配：“泼”多用于水等液体，不能用于照片或盒子。", "晾": "语义：“晾”是拿出来吹干，与“放进盒子”的收纳不符。"}, "sentence_index": 6, "correct_answer": "埋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那幅画埋在墙上。", "explanation": "这里应该用〈挂〉。埋要把东西盖入土中或覆盖，挂在墙上只能说“挂”。"}, {"text": "她把邮票埋在信封上。", "explanation": "这里应该用〈贴〉。邮票贴在信封表面，不是埋入或盖住。"}, {"text": "他把外套埋在身上，走出了门。", "explanation": "这里应该用〈穿〉。埋是用土或东西盖住，把外套穿在身上要说“穿”，不能说“埋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钥匙埋了在沙子里。", "corrected_sentence": "他把钥匙埋在了沙子里。", "error_description": "“了”的位置错误。正确说法是“埋在了”，“了”放在“在”之后；“埋了在”的说法不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把一只种子埋在了田里。", "corrected_sentence": "农民把一粒种子埋在了田里。", "error_description": "量词用错。种子应用「粒」，「只」用于动物等，不能说「一只种子」，应说「一粒种子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
