INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26196, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "衣服很结实，可以穿很久。", "primary_collocate": null, "pronunciation": "nài chuān", "ipa": "naɪ˥˩ tʂʰwan˥", "syllable_count": 2, "sentences": [{"text": "这条裤子很结实，真耐穿。", "target_word": "耐穿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件毛衣穿了五年还没坏，非常耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买运动鞋要选耐穿的。", "target_word": "耐穿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的大衣是好布料做的，特别耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双袜子太薄，一点也不耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说旧衣服虽然不新，但是很耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种牛仔布又厚又硬，耐穿得很。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨靴要选厚一点的，才耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的羽绒服穿了好多年，一点没坏，很耐穿。", "target_word": "耐穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的衣服不便宜，但是很耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "耐穿：衣服很结实，可以穿很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff18899e-4ea4-436c-9109-7ad54f9ec2c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐穿", "is_correct": true, "explanation": "耐穿：衣服结实、经穿，与“很结实”一致，句意通顺。"}, {"text": "脆", "is_correct": false, "explanation": "语义：“脆”指易碎，与“很结实”相矛盾。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指坏了，与“很结实”相矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”指温度低，不能用来说裤子的结实程度。"}], "explanations": {"耐穿": "耐穿：衣服结实、经穿，与“很结实”一致，句意通顺。", "脆": "语义：“脆”指易碎，与“很结实”相矛盾。", "烂": "语义：“烂”指坏了，与“很结实”相矛盾。", "冷": "搭配：“冷”指温度低，不能用来说裤子的结实程度。"}, "sentence_index": 0, "correct_answer": "耐穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗很耐穿。", "explanation": "这里应该用〈耐看〉。耐穿只用于衣物鞋袜，诗词要说耐看。"}, {"text": "这台冰箱很耐穿。", "explanation": "这里应该用〈耐用〉。耐穿只说衣物鞋袜经穿，冰箱等家电要说耐用。"}, {"text": "这面墙很耐穿。", "explanation": "这里应该用〈结实〉。耐穿只用于衣物鞋袜，墙体要说结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐穿", "is_correct": true, "explanation": "耐穿：经穿不易坏，与“又厚又硬”的布料特点相合。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软”与前面的“又硬”相矛盾。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指已经坏了，与“又厚又硬”的描述不合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”只用于味道，不能用来形容布料。"}], "explanations": {"耐穿": "耐穿：经穿不易坏，与“又厚又硬”的布料特点相合。", "软": "语义：“软”与前面的“又硬”相矛盾。", "烂": "语义：“烂”指已经坏了，与“又厚又硬”的描述不合。", "甜": "搭配：“甜”只用于味道，不能用来形容布料。"}, "sentence_index": 6, "correct_answer": "耐穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种陶瓷很耐穿。", "explanation": "这里应该用〈耐热〉。耐穿只用于衣物鞋袜，陶瓷耐高温要说耐热。"}, {"text": "这种地砖很耐穿。", "explanation": "这里应该用〈耐磨〉。耐穿指衣物鞋袜经穿，地砖耐磨损要说耐磨。"}, {"text": "这棵树很耐穿。", "explanation": "这里应该用〈耐寒〉。耐穿只用于衣物鞋袜，树木耐低温要说耐寒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裤子被耐穿，洗了几十次也没坏。", "corrected_sentence": "这条裤子很耐穿，洗了几十次也没坏。", "error_description": "错在“很”改为“被”。“耐穿”是形容词，不能用“被”引出；应用程度副词“很”修饰，说“很耐穿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一双耐穿地雨靴，下雨天常穿。", "corrected_sentence": "我想买一双耐穿的雨靴，下雨天常穿。", "error_description": "错在“的”改为“地”。“耐穿”修饰名词“雨靴”，应用结构助词“的”；“地”用于状语修饰动词，不能用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26198, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "节约资源", "is_correct": true, "explanation": "正确：节约与浪费意义相反，指不白白用掉可以节省的东西。"}, {"text": "调查情况", "is_correct": false, "explanation": "调查情况与浪费没有反义关系，指了解实际状况。"}, {"text": "设计图纸", "is_correct": false, "explanation": "设计图纸与浪费没有反义关系，指画出方案的图样。"}, {"text": "参观展览", "is_correct": false, "explanation": "参观展览与浪费没有反义关系，指到现场观看展示的内容。"}], "correct_answer": "节约资源", "explanations": {"节约资源": "正确：节约与浪费意义相反，指不白白用掉可以节省的东西。", "调查情况": "调查情况与浪费没有反义关系，指了解实际状况。", "设计图纸": "设计图纸与浪费没有反义关系，指画出方案的图样。", "参观展览": "参观展览与浪费没有反义关系，指到现场观看展示的内容。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
