INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从低处往上升起，或者开始变得强大。", "primary_collocate": null, "pronunciation": "jué qǐ", "ipa": "tɕyɛ˧˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "平原上突然崛起一座高山。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过很多年的地壳运动，这里崛起了高山。", "target_word": "崛起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市东边崛起了一片新的高楼。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇靠旅游慢慢崛起了。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一支年轻的球队在联赛中崛起。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老牌企业慢慢衰落，新品牌开始崛起。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小职员崛起为公司的老板。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河对岸崛起一排高山，非常壮观。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的这个小国正在崛起，成为新的力量。", "target_word": "崛起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里原来是农田，现在崛起了一个工业区。", "target_word": "崛起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "崛起了", "label": "体标"}, {"form": "崛起过", "label": "体标"}], "register": "书面", "sense_fingerprint": "山峰、高楼等从低处突然升起，或人和势力开始变强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f4a8b1-54f9-4af0-bf82-5bf023832828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崛起", "is_correct": true, "explanation": "“突然崛起一座高山”指山从低处突然升起，与“平原上”的语境相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：高山不会在平原上“融化”，与“突然升起”的意思相反。"}, {"text": "游动", "is_correct": false, "explanation": "配价：“游动”要求以会游的生物作主语，不能以高山作主语。"}, {"text": "烤焦", "is_correct": false, "explanation": "语义：高山不会被“烤焦”，与“突然升起”的语境不符。"}], "explanations": {"崛起": "“突然崛起一座高山”指山从低处突然升起，与“平原上”的语境相符。", "融化": "语义：高山不会在平原上“融化”，与“突然升起”的意思相反。", "游动": "配价：“游动”要求以会游的生物作主语，不能以高山作主语。", "烤焦": "语义：高山不会被“烤焦”，与“突然升起”的语境不符。"}, "sentence_index": 0, "correct_answer": "崛起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物价慢慢崛起了。", "explanation": "这里应该用〈上涨〉。崛起指从低处升起或开始变强，物价的升高要用“上涨”，不能用“崛起”。"}, {"text": "气温慢慢崛起了。", "explanation": "这里应该用〈升高〉。崛起指从低处升起或开始变强，气温上升要用“升高”，不能用“崛起”。"}, {"text": "灯光慢慢崛起了。", "explanation": "这里应该用〈亮起〉。崛起指从低处升起或开始变强，灯光变亮要用“亮起”，不能用“崛起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崛起", "is_correct": true, "explanation": "“崛起为……”指由小职员升为老板，与句中的升职语境相符。"}, {"text": "贬", "is_correct": false, "explanation": "语义：“贬为”是降职，与“公司的老板”的升职语境相反。"}, {"text": "降", "is_correct": false, "explanation": "语义：“降为”是降级，与句中由小职员升为老板的意思冲突。"}, {"text": "跌", "is_correct": false, "explanation": "搭配：“跌”不用于描述职位升迁的变化。"}], "explanations": {"崛起": "“崛起为……”指由小职员升为老板，与句中的升职语境相符。", "贬": "语义：“贬为”是降职，与“公司的老板”的升职语境相反。", "降": "语义：“降为”是降级，与句中由小职员升为老板的意思冲突。", "跌": "搭配：“跌”不用于描述职位升迁的变化。"}, "sentence_index": 6, "correct_answer": "崛起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个孩子去年崛起了两厘米。", "explanation": "这里应该用〈长高〉。崛起指从低处升起或开始变强，孩子身高增加要用“长高”，不能用“崛起”。"}, {"text": "这个地区的工厂数量崛起了。", "explanation": "这里应该用〈增加〉。崛起指从低处升起或开始变强，工厂数量的增多要用“增加”，不能用“崛起”。"}, {"text": "这片花园的花朵崛起了。", "explanation": "这里应该用〈开放〉。崛起指从低处升起或开始变强，花朵绽放要用“开放”，不能用“崛起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇被旅游崛起了。", "corrected_sentence": "这个小镇靠旅游崛起了。", "error_description": "“崛起”是不及物动词，不能用“被”字句，应说“靠旅游崛起了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新区在几年里崛起的很快。", "corrected_sentence": "这个新区在几年里崛起得很快。", "error_description": "补语错误：表示程度的补语要用“得”引出，“崛起的很快”误用“的”，应说“崛起得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26202, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
