INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业就是人们做东西或做事情的行业。", "primary_collocate": null, "pronunciation": "chǎn yè", "ipa": "ʈʂʰan˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这里的主要产业是种茶。", "target_word": "产业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爸爸在玩具产业工作。", "target_word": "产业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小镇上的最大产业是做家具。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子靠养鱼这个产业过日子。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅游是这座海边小城的重要产业。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑产业让很多人有了新工作。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家人都在食品产业工作。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的纺织产业有一百多年的历史。", "target_word": "产业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多年轻人想去网络产业工作。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔业是这个岛上最老的产业，已经有几百年了。", "target_word": "产业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "产业链", "label": "复合"}, {"form": "产业园", "label": "复合"}, {"form": "產業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们做东西或做事情的行业，如种茶、做家具、旅游", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产业", "is_correct": true, "explanation": "产业指人们做东西或做事情的行业，“主要产业是种茶”成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是行业，不能说“主要天气是种茶”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”是人的特质，不能与“是种茶”构成“主要……”的判断。"}, {"text": "学科", "is_correct": false, "explanation": "语义：“学科”指知识门类，“这里的主要学科是种茶”不成立。"}], "explanations": {"产业": "产业指人们做东西或做事情的行业，“主要产业是种茶”成立。", "天气": "语义：“天气”不是行业，不能说“主要天气是种茶”。", "性格": "语义：“性格”是人的特质，不能与“是种茶”构成“主要……”的判断。", "学科": "语义：“学科”指知识门类，“这里的主要学科是种茶”不成立。"}, "sentence_index": 0, "correct_answer": "产业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天去产业上班。", "explanation": "这里应该用〈工厂〉。产业指行业，不是具体的工作单位，不能说“去产业上班”。"}, {"text": "他在一家产业上班。", "explanation": "这里应该用〈公司〉。产业指行业，不是具体的公司，不能用“一家”来计量。"}, {"text": "这所产业有很多老师。", "explanation": "这里应该用〈学校〉。产业是行业的统称，不能指拥有老师的学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产业", "is_correct": true, "explanation": "产业指同类企业的集合，“在食品产业工作”成立。"}, {"text": "课业", "is_correct": false, "explanation": "语义：“课业”指学习功课，与食品相关的工作场所不符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不是可以“工作”的领域，“在食品心情工作”不通。"}, {"text": "色调", "is_correct": false, "explanation": "搭配：“色调”指画面颜色的整体倾向，不能作为“在……工作”的领域。"}], "explanations": {"产业": "产业指同类企业的集合，“在食品产业工作”成立。", "课业": "语义：“课业”指学习功课，与食品相关的工作场所不符。", "心情": "语义：“心情”不是可以“工作”的领域，“在食品心情工作”不通。", "色调": "搭配：“色调”指画面颜色的整体倾向，不能作为“在……工作”的领域。"}, "sentence_index": 6, "correct_answer": "产业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是岛上最有名的产业。", "explanation": "这里应该用〈渔民〉。产业指行业，不指人，不能用来称呼一个人。"}, {"text": "这家店的产业很好吃。", "explanation": "这里应该用〈菜〉。产业指行业，不是可以吃的东西，不能这样说。"}, {"text": "妈妈去市场买了两斤产业。", "explanation": "这里应该用〈鱼〉。产业指行业，不是可以买的具体东西，不能论斤买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里有一只很大的产业。", "corrected_sentence": "这里有一个很大的产业。", "error_description": "量词错误：“产业”应搭配“个”或“种”，“只”用于动物，不能修饰“产业”。正确说法是“一个很大的产业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他纺织产业工作了很多年。", "corrected_sentence": "他在纺织产业工作了很多年。", "error_description": "介词缺失：“工作”的处所要用介词“在”引出，应说“在纺织产业工作”，不能省略“在”说“纺织产业工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
