INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西从高处落下来。", "primary_collocate": null, "pronunciation": "diào", "ipa": "tjɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "苹果从树上掉下来了。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书从桌上掉到了地上。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机不小心掉进了水里。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天到了，树叶一片一片往下掉。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，别让杯子掉在地上。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钥匙从口袋里掉出来了，他没发现。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的冰淇淋掉在地上，他哭了。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋顶的雪掉下来，差点砸到人。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的眼镜掉过一次，现在已经换新的了。", "target_word": "掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上的果子熟了，一碰就掉。", "target_word": "掉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掉了", "label": "体标"}, {"form": "掉过", "label": "体标"}, {"form": "掉落", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西从高处或原来的位置落下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26210, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "掉", "is_correct": true, "explanation": "正确答案。掉 diào：东西从高处或原来的位置落下。"}, {"text": "到", "is_correct": false, "explanation": "到 dào 比 掉 diào 少一个介音 i，意思是到达。"}, {"text": "跳", "is_correct": false, "explanation": "跳 tiào 与 掉 diào 声母不同（t 与 d），意思是跳跃。"}, {"text": "雕", "is_correct": false, "explanation": "雕 diāo 与 掉 diào 声调不同（第一声与第四声），意思是雕刻。"}, {"text": "叼", "is_correct": false, "explanation": "叼 diāo 与 掉 diào 声调不同（第一声与第四声），意思是用嘴衔住。"}], "explanations": {"掉": "正确答案。掉 diào：东西从高处或原来的位置落下。", "到": "到 dào 比 掉 diào 少一个介音 i，意思是到达。", "跳": "跳 tiào 与 掉 diào 声母不同（t 与 d），意思是跳跃。", "雕": "雕 diāo 与 掉 diào 声调不同（第一声与第四声），意思是雕刻。", "叼": "叼 diāo 与 掉 diào 声调不同（第一声与第四声），意思是用嘴衔住。"}, "sentence_index": null, "correct_answer": "掉"}, "level_3": {"options": [{"text": "爬", "is_correct": false, "explanation": "语义：“爬”指攀登或匍匐移动，苹果不会“爬下来”。"}, {"text": "掉", "is_correct": true, "explanation": "正确：“掉下来了”指苹果从树上落下，符合句意。"}, {"text": "脱", "is_correct": false, "explanation": "搭配：“脱下来”多用于衣物、鞋帽，不能用于苹果从树上落下。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与苹果落下的动作无关。"}], "explanations": {"爬": "语义：“爬”指攀登或匍匐移动，苹果不会“爬下来”。", "掉": "正确：“掉下来了”指苹果从树上落下，符合句意。", "脱": "搭配：“脱下来”多用于衣物、鞋帽，不能用于苹果从树上落下。", "唱": "语义：“唱”指发出歌声，与苹果落下的动作无关。"}, "sentence_index": 0, "correct_answer": "掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些钱很快就花掉了。", "explanation": "这里用的是“掉”的“花费、用尽”义（如“花掉”），与“东西从高处落下来”无关。"}, {"text": "小鱼一条一条被吃掉了。", "explanation": "这里用的是“掉”的“去除、消失”义（如“吃掉”），与“东西从高处落下来”无关。"}, {"text": "田里的杂草一棵一棵被拔掉了。", "explanation": "这里用的是“掉”的“去除”义（如“拔掉”），与“东西从高处落下来”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，冰淇淋不能“吃在地上”，句意不通。"}, {"text": "掉", "is_correct": true, "explanation": "正确：“掉在地上”指冰淇淋落到地面，与“他哭了”的情境相符。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”指腾跃，冰淇淋不会“跳在地上”，句意不通。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”指居住或停留，不能用于冰淇淋落在地上的情况。"}], "explanations": {"吃": "语义：“吃”指进食，冰淇淋不能“吃在地上”，句意不通。", "掉": "正确：“掉在地上”指冰淇淋落到地面，与“他哭了”的情境相符。", "跳": "语义：“跳”指腾跃，冰淇淋不会“跳在地上”，句意不通。", "住": "搭配：“住”指居住或停留，不能用于冰淇淋落在地上的情况。"}, "sentence_index": 6, "correct_answer": "掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫一碰就跑掉了。", "explanation": "这里的“掉”是“跑掉”中表示离开的补语，不是“东西失去支撑而落下”的义项。"}, {"text": "小偷一碰就逃掉了。", "explanation": "这里的“掉”是“逃掉”中表示离开的补语，不是“东西失去支撑而落下”的义项。"}, {"text": "士兵一碰就溜掉了。", "explanation": "这里的“掉”是“溜掉”中表示离开的补语，不是“东西失去支撑而落下”的义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一片叶子从窗台上掉下了去。", "corrected_sentence": "一片叶子从窗台上掉下去了。", "error_description": "趋向补语“下去”应紧接动词“掉”，“了”放在补语之后。“掉下了去”不成立；正确形式为“掉下去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树叶从树上掉来了。", "corrected_sentence": "树叶从树上掉下来了。", "error_description": "趋向补语应为“下来”，漏掉“下”后“掉来了”不成立。正确形式为“掉下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
