INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放好，让它们变得整齐。", "primary_collocate": null, "pronunciation": "zhěng lǐ", "ipa": "ʈʂɤŋ˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "周末我在家整理房间，把书放回书架。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在整理衣柜里的冬衣。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书包整理得很整齐。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡觉前都会整理书桌。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的玩具整理好，再去吃饭。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我们花了两天整理新房子里的箱子。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在车库里整理工具，每样都放回原位。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们把教室里的桌椅整理得整整齐齐。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“下课前，请大家整理自己的书包。”", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服太乱了，我想整理一下，分类放好。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整理了", "label": "体标"}, {"form": "整理过", "label": "体标"}, {"form": "整理整理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "整理：把房间、书桌、衣物等实物摆放整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "整理", "is_correct": true, "explanation": "整理（zhěng lǐ）：把东西放好，使它们变得整齐。"}, {"text": "正理", "is_correct": false, "explanation": "正理（zhèng lǐ）与整理（zhěng lǐ）只有声调不同（第四声/第三声），意思是正确的道理。"}, {"text": "争理", "is_correct": false, "explanation": "争理（zhēng lǐ）与整理（zhěng lǐ）只有声调不同（第一声/第三声），意思是争论道理。"}, {"text": "整体", "is_correct": false, "explanation": "整体（zhěng tǐ）与整理的第二个音节不同（tǐ 与 lǐ 声母不同），意思是整个、全体。"}], "explanations": {"整理": "整理（zhěng lǐ）：把东西放好，使它们变得整齐。", "正理": "正理（zhèng lǐ）与整理（zhěng lǐ）只有声调不同（第四声/第三声），意思是正确的道理。", "争理": "争理（zhēng lǐ）与整理（zhěng lǐ）只有声调不同（第一声/第三声），意思是争论道理。", "整体": "整体（zhěng tǐ）与整理的第二个音节不同（tǐ 与 lǐ 声母不同），意思是整个、全体。"}, "sentence_index": null, "correct_answer": "整理"}, "level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "正确：“整理房间，把书放回书架”，把物品摆放整齐，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量房间的尺寸与“把书放回书架”的动作不相干。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”针对供人观看的场所或展品，不用于在家里收拾房间的动作。"}, {"text": "出租", "is_correct": false, "explanation": "语义：出租房间与“把书放回书架”的动作和整理房间的意思都不符。"}], "explanations": {"整理": "正确：“整理房间，把书放回书架”，把物品摆放整齐，符合句意。", "测量": "语义：测量房间的尺寸与“把书放回书架”的动作不相干。", "参观": "搭配：“参观”针对供人观看的场所或展品，不用于在家里收拾房间的动作。", "出租": "语义：出租房间与“把书放回书架”的动作和整理房间的意思都不符。"}, "sentence_index": 0, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把坏了的电视整理了一下。", "explanation": "这里应该用〈修理〉。整理是把物品摆放有序，不能表示修好坏掉的电器，要用“修理”。"}, {"text": "妈妈正在厨房整理饭。", "explanation": "这里应该用〈煮〉。整理用于物品或资料，煮饭要用“煮”。"}, {"text": "医生在整理病人。", "explanation": "这里应该用〈治疗〉。整理不用于人，治疗病人要用“治疗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "正确：“整理工具，每样都放回原位”，使物品有序，符合句意。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售工具与“每样都放回原位”的结果相矛盾。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能用于工具。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”的对象是颜料、药膏等，与“工具”和“放回原位”都不搭配。"}], "explanations": {"整理": "正确：“整理工具，每样都放回原位”，使物品有序，符合句意。", "出售": "语义：出售工具与“每样都放回原位”的结果相矛盾。", "烹饪": "搭配：“烹饪”的对象是食物，不能用于工具。", "涂抹": "搭配：“涂抹”的对象是颜料、药膏等，与“工具”和“放回原位”都不搭配。"}, "sentence_index": 6, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在纸上整理了一只猫。", "explanation": "这里应该用〈画〉。整理不表示绘画，在纸上画猫要用“画”。"}, {"text": "他在比赛中整理了一个进球。", "explanation": "这里应该用〈踢进〉。整理用于摆放物品，不能表示得分；射门进球要说“踢进”。"}, {"text": "他整理了一杯水。", "explanation": "这里应该用〈喝〉。整理用于物品或资料，喝水要用“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把厨房的碗筷整理的井井有条。", "corrected_sentence": "妈妈把厨房的碗筷整理得井井有条。", "error_description": "错误：“整理的井井有条”。“整理”后接表示结果或程度的补语时要用助词“得”，不能用“的”。正确形式是“整理得井井有条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐正在整理过她的书架。", "corrected_sentence": "姐姐正在整理她的书架。", "error_description": "错误：“正在整理过”。“正在”表示动作正在进行，“过”表示曾经经历，二者矛盾。正确形式是“正在整理她的书架”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱衣", "is_correct": true, "explanation": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。"}, {"text": "洗碗", "is_correct": false, "explanation": "洗碗是家务动作，与穿衣没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是书写活动，与穿衣没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是运动方式，与穿衣没有反义关系。"}], "correct_answer": "脱衣", "explanations": {"脱衣": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。", "洗碗": "洗碗是家务动作，与穿衣没有反义关系。", "写字": "写字是书写活动，与穿衣没有反义关系。", "游泳": "游泳是运动方式，与穿衣没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
