INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把衣服穿到身上。", "primary_collocate": null, "pronunciation": "chuān yī", "ipa": "ʈʂʰwan˥ i˥", "syllable_count": 2, "sentences": [{"text": "弟弟自己穿衣，不要妈妈帮。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮了，他慢慢起床穿衣。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡，快点穿衣，别感冒。", "target_word": "穿衣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他穿衣的动作很快，三分钟就出门了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学穿衣，常常把左右弄错。", "target_word": "穿衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在冷房间里穿衣，手都冻红了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他闭着眼睛穿衣，还想再睡一会儿。", "target_word": "穿衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，穿衣要慢一点。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起床后，他很快穿衣，吃了早饭就走了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教孩子们怎样穿衣，怎样系鞋带。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿衣镜", "label": "复合"}, {"form": "穿衣打扮", "label": "复合"}], "register": "中性", "sense_fingerprint": "把衣服穿到身上的日常动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上。"}, {"text": "船医", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是船上的医生。"}, {"text": "传艺", "is_correct": false, "explanation": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是传授技艺。"}, {"text": "春衣", "is_correct": false, "explanation": "chūn 与 chuān 韵母不同（-un 与 -an），意思是春天穿的衣服。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上。", "船医": "chuán（第二声）与 chuān（第一声）声调不同，意思是船上的医生。", "传艺": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是传授技艺。", "春衣": "chūn 与 chuān 韵母不同（-un 与 -an），意思是春天穿的衣服。"}, "sentence_index": null, "correct_answer": "穿衣"}, "level_3": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上，“自己穿衣”符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：“桌子”是名词，“弟弟自己桌子”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "词性：“天气”是名词，不能放在“自己……”之后作动作，“自己天气”不通。"}, {"text": "书包", "is_correct": false, "explanation": "词性：“书包”是名词，“弟弟自己书包，不要妈妈帮”不成立。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上，“自己穿衣”符合语境。", "桌子": "词性：“桌子”是名词，“弟弟自己桌子”不成立。", "天气": "词性：“天气”是名词，不能放在“自己……”之后作动作，“自己天气”不通。", "书包": "词性：“书包”是名词，“弟弟自己书包，不要妈妈帮”不成立。"}, "sentence_index": 0, "correct_answer": "穿衣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游泳前他要先穿衣，再换上泳裤。", "explanation": "这里应该用〈脱衣〉。穿衣是把衣服穿到身上，游泳前要先脱衣，不能说“穿衣”。"}, {"text": "进屋后，他先穿衣，再坐下来。", "explanation": "这里应该用〈脱掉外套〉。穿衣是把衣服穿上，进屋后要先脱掉外套，不能说“穿衣”。"}, {"text": "他先穿衣，再洗了个热水澡。", "explanation": "这里应该用〈脱下衣服〉。穿衣是把衣服穿上，洗澡前要脱下衣服，不能说“穿衣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上，“闭着眼睛穿衣”符合语境。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“搬家”是大规模的搬迁，“闭着眼睛搬家”与早晨想再睡一会儿的情境不符。"}, {"text": "画画", "is_correct": false, "explanation": "语义：“画画”需要纸笔和创作，与“还想再睡一会儿”的早晨情境无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”是娱乐活动，不能与“闭着眼睛”加“还想再睡一会儿”组成合理的情境。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上，“闭着眼睛穿衣”符合语境。", "搬家": "语义：“搬家”是大规模的搬迁，“闭着眼睛搬家”与早晨想再睡一会儿的情境不符。", "画画": "语义：“画画”需要纸笔和创作，与“还想再睡一会儿”的早晨情境无关。", "跳舞": "语义：“跳舞”是娱乐活动，不能与“闭着眼睛”加“还想再睡一会儿”组成合理的情境。"}, "sentence_index": 6, "correct_answer": "穿衣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先穿衣，再放进柜子里。", "explanation": "这里应该用〈叠〉。穿衣是把衣服穿到身上，应先把衣服叠好再放进柜子，不能说“穿衣”。"}, {"text": "妈妈在河边穿衣，然后晾在树上。", "explanation": "这里应该用〈洗衣服〉。穿衣是把衣服穿到身上，洗衣服才是把衣服弄干净，不能说“穿衣”。"}, {"text": "他在服装厂穿衣，每天能缝一百件衣服。", "explanation": "这里应该用〈缝〉。穿衣是把衣服穿到身上，不指缝制衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天冷了，妈妈给孩子穿衣一件小棉袄。", "corrected_sentence": "天冷了，妈妈给孩子穿一件小棉袄。", "error_description": "错误：「穿衣」是动宾结构，「衣」已是它的宾语，后面不能再直接带宾语「一件小棉袄」。正确说法是「穿一件小棉袄」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天很早就起来穿衣一件衣服。", "corrected_sentence": "他每天很早就起来穿一件衣服。", "error_description": "错误：「穿衣」是动宾结构，「衣」已是它的宾语，后面不能再直接带宾语。正确说法是删去多余的「衣」：「穿一件衣服」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
