INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "合成纤维是人们用化学方法做出来的线，可以用来做衣服。", "primary_collocate": null, "pronunciation": "hé chéng xiān wéi", "ipa": "xɤ˧˥ ʈʂʰɤŋ˧˥ ɕjɛn˥ weɪ˧˥", "syllable_count": 4, "sentences": [{"text": "合成纤维是用化学方法做出来的线。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套是合成纤维做的，很轻。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说合成纤维的衣服夏天会很热。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合成纤维的衣服洗了很快就干。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条围巾不是羊毛的，是合成纤维的。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买衣服时，我先看里面有没有合成纤维。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用合成纤维做的雨伞很轻，也不怕水。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合成纤维是工厂里做出来的，不是长出来的。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双袜子里有一半是合成纤维。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一块合成纤维的布。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "化纤", "label": "简称"}, {"form": "一种合成纤维", "label": "量词"}], "register": "中性", "sense_fingerprint": "人用化学方法做出来的线，可以做衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合成纤维", "is_correct": true, "explanation": "正确：“合成纤维”是用化学方法做出来的线。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是天然纤维，不是用化学方法做出来的。"}, {"text": "蚕丝", "is_correct": false, "explanation": "语义：蚕丝来自蚕茧，是天然的，不是化学方法做的。"}, {"text": "白菜", "is_correct": false, "explanation": "搭配：“做出来的线”要求可以纺线的材料，不能说白菜做出来的线。"}], "explanations": {"合成纤维": "正确：“合成纤维”是用化学方法做出来的线。", "棉花": "语义：棉花是天然纤维，不是用化学方法做出来的。", "蚕丝": "语义：蚕丝来自蚕茧，是天然的，不是化学方法做的。", "白菜": "搭配：“做出来的线”要求可以纺线的材料，不能说白菜做出来的线。"}, "sentence_index": 0, "correct_answer": "合成纤维"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "棉花是地里长出来的合成纤维。", "explanation": "这里应该用〈天然纤维〉。棉花是长出来的，合成纤维是用化学方法做出来的。"}, {"text": "这条宽带线路用合成纤维铺设，传输速度很快。", "explanation": "这里应该用〈光纤〉。光纤用来传输光信号，合成纤维是纺织材料，不能用来铺设通信线路。"}, {"text": "很多蔬菜含有合成纤维。", "explanation": "这里应该用〈膳食纤维〉。膳食纤维存在于蔬菜中，有助于消化；合成纤维是化学做出来的，不是蔬菜的成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合成纤维", "is_correct": true, "explanation": "正确：“合成纤维”轻，也不怕水，可以用来做雨伞。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁很重，不可能做出很轻的雨伞。"}, {"text": "棉布", "is_correct": false, "explanation": "语义：棉布吸水，用它做的雨伞不能说“也不怕水”，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头很重，不符合“很轻”的描述。"}], "explanations": {"合成纤维": "正确：“合成纤维”轻，也不怕水，可以用来做雨伞。", "铁": "语义：铁很重，不可能做出很轻的雨伞。", "棉布": "语义：棉布吸水，用它做的雨伞不能说“也不怕水”，与句意矛盾。", "石头": "语义：石头很重，不符合“很轻”的描述。"}, "sentence_index": 6, "correct_answer": "合成纤维"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "羊身上长满了合成纤维。", "explanation": "这里应该用〈羊毛〉。羊身上长的是羊毛，合成纤维是工厂用化学方法做的。"}, {"text": "我早饭吃了一碗合成纤维。", "explanation": "这里应该用〈米饭〉。合成纤维是做衣服的线，不能吃。"}, {"text": "蚕吐出来的丝是合成纤维。", "explanation": "这里应该用〈蚕丝〉。蚕丝是天然的，合成纤维是用化学方法做出来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种很轻地合成纤维可以做衣服。", "corrected_sentence": "这种很轻的合成纤维可以做衣服。", "error_description": "修饰语错误：“很轻”修饰名词“合成纤维”，应用“的”，不能用“地”。正确形式是“很轻的合成纤维”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把合成纤维纺。", "corrected_sentence": "他们把合成纤维纺成了线。", "error_description": "补语缺失：“把”字句中的动词后面需要补语，“把合成纤维纺”不完整，应为“把合成纤维纺成了线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
