INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26220, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把布放进有颜色的水里，让布变成那种颜色。", "primary_collocate": null, "pronunciation": "yìn rǎn", "ipa": "in˥˩ ʐan˨˩˦", "syllable_count": 2, "sentences": [{"text": "把白布放进红水里印染，布就变红了。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在印染一块白布。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的美术课教同学印染手帕。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把布印染好，再拿去做衣服。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子是用蓝色印染的。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在家里印染了一块漂亮的布。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印染要用染料，也要用很多水。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布印染完以后，要放在太阳下晒干。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想试试用茶水印染白衬衫。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把旧布印染成了黄色。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "印染了", "label": "体标"}, {"form": "印染过", "label": "体标"}, {"form": "印染厂", "label": "复合"}], "register": "中性", "sense_fingerprint": "把布放进有颜色的水里，让布变色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印染", "is_correct": true, "explanation": "正确：“把白布放进红水里印染，布就变红了”，印染的结果是布变色，符合句意。"}, {"text": "漂白", "is_correct": false, "explanation": "语义：漂白会使布变白，与“布就变红了”的结果相矛盾。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”是用熨斗烫平，不在水里进行，与“放进红水里”不搭配。"}, {"text": "缝制", "is_correct": false, "explanation": "搭配：“缝制”指把布料做成衣物，与“放进红水里”的动作和“布就变红了”的结果都不符。"}], "explanations": {"印染": "正确：“把白布放进红水里印染，布就变红了”，印染的结果是布变色，符合句意。", "漂白": "语义：漂白会使布变白，与“布就变红了”的结果相矛盾。", "熨烫": "搭配：“熨烫”是用熨斗烫平，不在水里进行，与“放进红水里”不搭配。", "缝制": "搭配：“缝制”指把布料做成衣物，与“放进红水里”的动作和“布就变红了”的结果都不符。"}, "sentence_index": 0, "correct_answer": "印染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家出版社专门印染书籍。", "explanation": "这里应该用〈印刷〉。印染是给布料着色，书籍要用印刷。"}, {"text": "我想把头发印染成金色。", "explanation": "这里应该用〈染〉。印染用于布料，给头发着色要用“染”。"}, {"text": "我想把白纸印染成蓝色。", "explanation": "这里应该用〈上色〉。纸张不是布料，给白纸着色要用“上色”，不能说印染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印染", "is_correct": true, "explanation": "正确：印染需要染料和水，“要用染料，也要用很多水”符合印染的过程。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：晾晒是把湿物晒干，并不需要染料。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是使东西变干的步骤，与“要用染料”无关。"}, {"text": "烹调", "is_correct": false, "explanation": "搭配：“烹调”是做饭菜的动作，与“染料”不搭配。"}], "explanations": {"印染": "正确：印染需要染料和水，“要用染料，也要用很多水”符合印染的过程。", "晾晒": "语义：晾晒是把湿物晒干，并不需要染料。", "烘干": "语义：烘干是使东西变干的步骤，与“要用染料”无关。", "烹调": "搭配：“烹调”是做饭菜的动作，与“染料”不搭配。"}, "sentence_index": 6, "correct_answer": "印染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用彩灯印染客厅，屋子变得很亮。", "explanation": "这里应该用〈装饰〉。印染只用于布料着色，布置客厅要用“装饰”。"}, {"text": "他花了一个下午印染那卷胶卷。", "explanation": "这里应该用〈冲洗〉。印染是把布放进颜色水里使布变色，冲洗胶卷要用“冲洗”。"}, {"text": "妈妈用抹布印染桌子。", "explanation": "这里应该用〈擦〉。印染是布料着色的工艺，擦桌子要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈印染了三个白布，准备做手帕。", "corrected_sentence": "妈妈印染了三块白布，准备做手帕。", "error_description": "量词错误：“布”应用量词“块”，不能用“个”。正确形式是“三块白布”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在印染过一块蓝色手帕。", "corrected_sentence": "妈妈正在印染一块蓝色手帕。", "error_description": "错误：“正在印染过”。“正在”表示动作正在进行，“过”表示曾经经历，二者矛盾。正确形式是“正在印染一块蓝色手帕”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
