INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对事情的结果起决定作用的重要原因或条件。", "primary_collocate": null, "pronunciation": "guān jiàn yīn sù", "ipa": "kwan˥˥ tɕjɛn˥˩ in˥˥ su˥˩", "syllable_count": 4, "sentences": [{"text": "想赢得比赛，先要找到关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小小的关键因素改变了结果。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘带准考证，这个小疏忽成了失利的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "furigana": "tā wàng dài zhǔn kǎo zhèng, zhè ge xiǎo shū hu chéng le shī lì de guān jiàn yīn sù.", "sentence_source": "generated"}, {"text": "他没发现那个关键因素，所以做错了。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现门没锁好，这个小细节是事故的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "furigana": "tā fā xiàn mén méi suǒ hǎo, zhè ge xiǎo xì jié shì shì gù de guān jiàn yīn sù.", "sentence_source": "generated"}, {"text": "一小撮盐，就是这锅汤的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "furigana": "yī xiǎo cuō yán, jiù shì zhè guō tāng de guān jiàn yīn sù.", "sentence_source": "generated"}, {"text": "鞋带松了一下，就成了他输掉比赛的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "furigana": "xié dài sōng le yí xià, jiù chéng le tā shū diào bǐ sài de guān jiàn yīn sù.", "sentence_source": "generated"}, {"text": "表格里有一行数字，是决定报价的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "furigana": "biǎo gé lǐ yǒu yì háng shù zì, shì jué dìng bào jià de guān jiàn yīn sù.", "sentence_source": "generated"}, {"text": "少了这个关键因素，计划就不能成功。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙落在车里，这就是那天迟到的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "furigana": "tā bǎ yào shi luò zài chē lǐ, zhè jiù shì nà tiān chí dào de guān jiàn yīn sù.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "關鍵因素", "label": "繁体"}], "register": "中性", "sense_fingerprint": "决定结果的主要原因/条件；成为……的关键因素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3730d27a-05b6-43d9-b563-68f34a3445ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关键因素", "is_correct": true, "explanation": "正确：“关键因素”指对结果起决定作用的原因或条件，符合“赢得比赛”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“先要找到”后接的是可寻找的具体事物，“颜色”不能作为赢得比赛的条件去找。"}, {"text": "讲台", "is_correct": false, "explanation": "语义：讲台是授课用的台子，与赢得比赛的条件无关。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是写作的任务，与赢得比赛的条件无关。"}], "explanations": {"关键因素": "正确：“关键因素”指对结果起决定作用的原因或条件，符合“赢得比赛”的语境。", "颜色": "搭配：“先要找到”后接的是可寻找的具体事物，“颜色”不能作为赢得比赛的条件去找。", "讲台": "语义：讲台是授课用的台子，与赢得比赛的条件无关。", "作文": "语义：作文是写作的任务，与赢得比赛的条件无关。"}, "sentence_index": 0, "correct_answer": "关键因素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个小插曲只是关键因素，结果并没有因此改变。", "explanation": "这里应该用〈次要细节〉。“关键因素”指决定结果的部分，与“结果并没有因此改变”相矛盾。"}, {"text": "墙上的花瓶只是关键因素，它对比赛结果没有任何影响。", "explanation": "这里应该用〈装饰品〉。花瓶对结果没有影响，不能称为关键因素。"}, {"text": "他把关键因素交给了门卫。", "explanation": "这里应该用〈钥匙〉。“关键因素”是抽象的原因或条件，不是能交给门卫的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关键因素", "is_correct": true, "explanation": "正确：“关键因素”指决定结果的小部分，符合“导致输掉比赛”的语境。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是获胜者得到的奖励，不会导致输掉比赛。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众只是看比赛的人，不能成为输掉比赛的原因。"}, {"text": "球迷", "is_correct": false, "explanation": "搭配：“输掉比赛的”后接的应是原因或事物，“球迷”不能这样指向导致失利的因素。"}], "explanations": {"关键因素": "正确：“关键因素”指决定结果的小部分，符合“导致输掉比赛”的语境。", "奖杯": "语义：奖杯是获胜者得到的奖励，不会导致输掉比赛。", "观众": "语义：观众只是看比赛的人，不能成为输掉比赛的原因。", "球迷": "搭配：“输掉比赛的”后接的应是原因或事物，“球迷”不能这样指向导致失利的因素。"}, "sentence_index": 6, "correct_answer": "关键因素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天要喝关键因素。", "explanation": "这里应该用〈饮料〉。“喝”的对象是饮品，“关键因素”是抽象的原因或条件，不能喝。"}, {"text": "他每天早上都要去关键因素上班。", "explanation": "这里应该用〈公司〉。“去…上班”需要一个工作场所，“关键因素”不是地点。"}, {"text": "他每天都向关键因素问好。", "explanation": "这里应该用〈老师〉。“问好”的对象应是人，“关键因素”是抽象的原因或条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小疏忽是他失利的一只关键因素。", "corrected_sentence": "这个小疏忽是他失利的一个关键因素。", "error_description": "错误在于“关键因素”前的量词。应说“一个关键因素”，不能用“只”；“只”多用于动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗小螺丝是事故的一根关键因素。", "corrected_sentence": "那颗小螺丝是事故的一个关键因素。", "error_description": "错误在于“关键因素”前的量词。“根”用于细长条状的东西，抽象的“关键因素”不能用“根”计量；应说“一个关键因素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
