INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿过的衣服，不是新的。", "primary_collocate": null, "pronunciation": "jiù yī fu", "ipa": "tɕjoʊ˥˩ i˥ fu", "syllable_count": 3, "sentences": [{"text": "这些旧衣服已经穿了五年。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢买新的，常穿朋友给的旧衣服。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上卖旧衣服，换了一点钱。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服太多了，床下面都放不下。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧衣服剪开，做成了一个小包。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，大家都把旧衣服送到学校。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门卖别人穿过的旧衣服。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长得快，旧衣服很快就小了。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶舍不得扔旧衣服，总说还能穿。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一个箱子，里面都是旧衣服。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "旧衣物", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿过的、不是新的衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff18899e-4ea4-436c-9109-7ad54f9ec2c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
